// https://stackoverflow.com/questions/1007981/how-to-get-function-parameter-names-values-dynamically
const COMMENTS_REGEXP = /((\/\/.*$)|(\/\*[\s\S]*?\*\/))/mg;
const ARGUMENT_NAMES = /([^\s,]+)/g;
export function getParamNames(func) {
	var fnStr = func.toString().replace(COMMENTS_REGEXP, '');
	var result = fnStr.slice(fnStr.indexOf('(')+1, fnStr.indexOf(')')).match(ARGUMENT_NAMES);
	if(result === null) result = [];
	return result;
}

export function getComments(func) {
	return [...func.toString().matchAll(COMMENTS_REGEXP)].map(r => r[0]);
}

export function getMethods (obj) {
	let properties = new Set();
	let currentObj = obj;
	do {
		Object.getOwnPropertyNames(currentObj).map(item => properties.add(item));
	} while ((currentObj = Object.getPrototypeOf(currentObj)));
	return [...properties.keys()].filter(item => { try {return typeof obj[item] === 'function';} catch (e) {return false;} });
}

// Based on https://stackoverflow.com/questions/35228052/debounce-function-implemented-with-promises
export function debounce(f, interval) {
	let timer = null;

	return (...args) => {
		clearTimeout(timer);
		return new Promise((resolve) => {
			timer = setTimeout(
				() => resolve(f(...args)),
				interval,
			);
		});
	};
}

