const warnCache = new Set();
export const warnOnce = warn => {
	if (warnCache.has(warn)) return;
	warnCache.add(warn);
	console.warn(warn);
};

export function easeOutCubic(x) {
	return 1 - (1 - x)**3;
}


export function lerp (start, end, t) {
	return (1-t) * start + t * end;
}

