// https://github.com/tc39/proposal-weakrefs#iterable-weakmaps
export class IterableWeakMap {
	#weakMap = new WeakMap();
	#refSet = new Set();
	#finalizationGroup = new FinalizationRegistry(IterableWeakMap.#cleanup);

	static #cleanup({ set, ref }) {
		set.delete(ref);
	}

	constructor(iterable=[]) {
		for (const [key, value] of iterable) {
			this.set(key, value);
		}
	}

	set(key, value) {
		if (this.#weakMap.has(key)) {
			this.delete(key);
		}

		const ref = new WeakRef(key);

		this.#weakMap.set(key, { value, ref });
		this.#refSet.add(ref);
		this.#finalizationGroup.register(key, {
			set: this.#refSet,
			ref
		}, ref);
	}

	has (key) {
		const entry = this.#weakMap.get(key);
		return !!(entry && (entry.value !== undefined));
	}

	get(key) {
		const entry = this.#weakMap.get(key);
		return entry && entry.value;
	}

	getKeysFromValue(value) {
		return [...this].filter(([,v])=>v===value).map(([k])=>k);
	}

	delete(key) {
		const entry = this.#weakMap.get(key);
		if (!entry) {
			return false;
		}

		this.#weakMap.delete(key);
		this.#refSet.delete(entry.ref);
		this.#finalizationGroup.unregister(entry.ref);
		return true;
	}

	*[Symbol.iterator]() {
		for (const ref of this.#refSet) {
			const key = ref.deref();
			if (!key) continue;
			const { value } = this.#weakMap.get(key);
			yield [key, value];
		}
	}

	entries() {
		return this[Symbol.iterator]();
	}

	*keys() {
		// eslint-disable-next-line no-unused-vars
		for (const [key, value] of this) {
			yield key;
		}
	}

	*values() {
		// eslint-disable-next-line no-unused-vars
		for (const [key, value] of this) {
			yield value;
		}
	}
}

/**
 * Find the point on a plane that lies closest to
 * @param {THREE.Vector3} positionOnPlane any point on the plane.
 * @param {THREE.Vector3} planeNormal the normal of the plane
 * @param {THREE.Vector3} pointToTest point to test
 * @param {THREE.Vector3} resultPoint where to store the result.
 * @returns
 */
export function nearestPointInPlane(positionOnPlane, planeNormal, pointToTest, resultPoint) {
	var t = distanceOfPointFromPlane(positionOnPlane, planeNormal, pointToTest);
	// closest point on the plane
	resultPoint.copy(planeNormal);
	resultPoint.multiplyScalar(t);
	resultPoint.add(pointToTest);
	return resultPoint;
}

export function querySelectorAllWithParts(root, selector, arrayTargetForPartHavers=[]) {
	const selectorParts = selector.split(/,(?=[^\]]*(?:\[|$))/);
	const out = [];
	for (const selector of selectorParts) {
		if (!selector.includes('::part')) {
			out.push(...root.querySelectorAll(selector));
		} else {
			const partName = selector.match(/([^\s]*)::part\((.*)\)/);
			if (partName) for (const el of root.querySelectorAll(partName[1] || '*')) {
				arrayTargetForPartHavers.push(el);
				out.push(...queryParts(el, partName[2].trim()));
			}
		}
	}
	return out;
}

const domParser = new DOMParser();
export function htmlToText(html){
	//remove code brakes and tabs
	html = html.replace(/\n/g, "");
	html = html.replace(/\t/g, "");

	//keep html brakes and tabs
	html = html.replace(/<\/td>/g, "\t");
	html = html.replace(/<\/table>/g, "\n");
	html = html.replace(/<\/tr>/g, "\n");
	html = html.replace(/<\/p>/g, "\n\n");
	html = html.replace(/<\/div>/g, "\n");
	html = html.replace(/<\/h>/g, "\n");
	html = html.replace(/<br>/g, "\n"); html = html.replace(/<br( )*\/>/g, "\n");

	//parse html into text
	var dom = domParser.parseFromString('<!doctype html><body>' + html, 'text/html');
	return dom.body.textContent.trim();
}

export function matchesWithParts(element, selector) {
	const selectorParts = selector.split(/,(?=[^\]]*(?:\[|$))/);
	let matches = false;
	for (const selector of selectorParts) {
		if (!selector.includes('::part')) {
			matches = matches || element.matches(selector);
		} else {
			const partName = selector.match(/([^\s]*)::part\((.*)\)/);
			if (partName) {
				matches = matches || (element.getRootNode()?.host?.matches(partName[1] || '*') && element.matches(`[part~="${partName[2].trim()}"]`));
			}
		}
		if (matches) break;
	}
	return matches;
}

export function querySelectorAllWithPartsLive(element, selector) {

	const partHaverEls = [];
	var result = querySelectorAllWithParts(element, selector, partHaverEls);

	// Create observer instance.
	var observer = new MutationObserver(function (mutations) {
		mutations.forEach(function (mutation) {
			Array.prototype.forEach.call(mutation.addedNodes, function (node) {
				if (node.nodeType === Node.ELEMENT_NODE && matchesWithParts(node, selector)) result.push(node);
			});
			Array.prototype.forEach.call(mutation.removedNodes, function (node) {
				const index = result.indexOf(node);
				if (index !== -1) result.splice(index, 1); 
			});
			if (mutation.type === 'attributes') {
				const node = mutation.target;
				const matches = matchesWithParts(node, selector);
				const index = result.indexOf(node);
				if (matches && index === -1) {
					result.push(node);
				}
				if (!matches && index !== -1) {
					result.splice(index, 1); 
				}
			}
		});
	});

	// detect partHaverEls gaining a shadowRoot or that shadowRoot having changes.
	for (const el of partHaverEls) {
		customElements.upgrade(el);
		if (el.shadowRoot) observer.observe(el.shadowRoot, { childList: true, subtree: true, attributes:true, attributeFilter: ["class", "part", "id"] });
	}

	// Set up observer.
	observer.observe(element, { childList: true, subtree: true });

	result.dispose = function () {
		observer.disconnect();
	};

	result.__query = selector;

	return result;
}

const cachedFunctionsCache = new Map();
export function cacheable(fn) {
	if (cachedFunctionsCache.has(fn)) return cachedFunctionsCache.get(fn);
	const cache = new Map();
	const cachedFn = function (arg) {
		if (cache.has(arg)) return cache.get(arg);
		const result = fn(arg);
		cache.set(arg, result);
		return result;
	};
	cachedFunctionsCache.set(fn, cachedFn);
	return cachedFn;
}

export function queryParts(el, parts, results=[]) {
	if (!el.shadowRoot) return results;
	const partNames = parts.split(/\s+/);
	const selectorLocalShadowRoot = partNames.map(name => `[part~="${name}"]`).join('');
	const selectorExportParts = partNames.map(name => `[exportparts~="${name}"]`).join('');
	results.push(...el.shadowRoot.querySelectorAll(selectorLocalShadowRoot));
	const exportPartEls = el.shadowRoot.querySelectorAll(selectorExportParts);
	if (exportPartEls) {
		for (const el of exportPartEls) {
			queryParts(el, parts, results);
		}
	}
	return results;
}

export function querySelectorAllLive(element, selector) {

	// Initialize results with current nodes.
	var result = Array.prototype.slice.call(element.querySelectorAll(selector));

	// Create observer instance.
	var observer = new MutationObserver(function (mutations) {
		mutations.forEach(function (mutation) {
			[].forEach.call(mutation.addedNodes, function (node) {
				if (node.nodeType === Node.ELEMENT_NODE && node.matches(selector)) result.push(node);
			});
			[].forEach.call(mutation.removedNodes, function (node) {
				const index = result.indexOf(node);
				if (index !== -1) result.splice(index, 1); 
			});

		});
	});

	// Set up observer.
	observer.observe(element, { childList: true, subtree: true });

	result.dispose = function () {
		observer.disconnect();
	};

	return result;
}

export const clamp = (num, min, max) => Math.min(Math.max(num, min), max);
export function powerOfTwo(x) {
	return Math.pow(2, Math.floor(Math.log(x)/Math.log(2)));
}
