
/* jshint browser:true, esversion:11 */
import {
	MathUtils,
	Color,
	Vector3,
	Vector2,
	Euler,
	Quaternion,
	Texture,
	BufferGeometry,
	Material,
	Camera,
	Mesh,
	Scene,
	WebGLRenderer,
	Object3D,
	InstancedMesh
} from 'three';
import * as THREE_CONSTANTS from 'three/src/constants.js';
import { reflectObjectFromEl } from './utils/reflect-object.js';
import { queryParts, querySelectorAllWithPartsLive } from './utils/utils.js';
export const THREE_TYPES = {
	Texture, Material, BufferGeometry, Object, Object3D, Camera, Mesh, Scene, WebGLRenderer, InstancedMesh
};
const spaceRegex = /\s+/;

const reusableObjectPropertyCache = new WeakMap();

export const schemaTypeParsing = baseclass => class extends baseclass {
	static name = 'SchemaTypeParsing';

	stringToValue(attr, value) {
		if (!reusableObjectPropertyCache.has(this)) {
			reusableObjectPropertyCache.set(this, {});
		}
		const reusableObjectPropertyCacheProperty = reusableObjectPropertyCache.get(this);

		if (value === undefined) {
			throw Error('parse attribute error given value is undefined');
		}

		const schemaEntry = this.constructor.getSchemaEntry(attr);
		const type = schemaEntry.type || typeof schemaEntry.default;
		const property = schemaEntry.as || attr;

		if (typeof value === 'string') value = value.trim();
		
		// If the schema entry is just a type then use that as the type
		
		if (schemaEntry.map) {
			const mappedValue = schemaEntry.map[value];
			value = typeof mappedValue === 'undefined' ? value : mappedValue;
		}

		let outValue = value;

		if (typeof outValue === 'string' && type !== 'string') {
			if (type === 'Class') {
				outValue = document.getElementsByClassName(value);
			} else if (type === 'Element') {
				let el = null;
				try {
					el = this.getRootNode().querySelector(value) || document.querySelector(value);
				} catch (e) {
					// In case it's not a valid selector
				}
				if (el) {
					outValue = el;
					if (el.isShortHandElement) el.onAssign(attr, new WeakRef(this));
					this.objectAssigned(attr, el);
				}
			} else if (type === 'Elements') {
				let els = null;
				try {
					els = querySelectorAllWithPartsLive(document, value);
				} catch (e) {
					// In case it's not avalid selector
				}
				if (els) {
					outValue = els;
					for (const el of els) {
						if (el.isShortHandElement) el.onAssign(attr, new WeakRef(this));
						this.objectAssigned(attr, el);
					}
				}
			} else if (type === 'angle') {
				const parsedValue = window.parseFloat(outValue);
				if (!isNaN(parsedValue)) {
					outValue = parsedValue*Math.PI/180;
				}
			} else {
				const threeValueMatch = value.indexOf('THREE.') === 0;
				if (threeValueMatch) {
					const threeConstant = value.substring(6);
					outValue = THREE_CONSTANTS[threeConstant];
				} else if (type === 'Color') {
					const color = reusableObjectPropertyCacheProperty[property] = reusableObjectPropertyCacheProperty[property] || new Color();
					color.set(value);
					outValue = color;
				} else if (type === 'boolean') {
					outValue = (value.toLowerCase() !== 'false');
				} else if (type === 'number') {
					outValue = parseFloat(value);
				} else if (type === 'percentage') {
					outValue = parseFloat(value)*0.01;
				} else if (type === 'boolean[]') {
					if (value === '') outValue = [];
					else outValue = value.split(spaceRegex).map(v => (v.toLowerCase() !== 'false'));
				} else if (type === 'number[]') {
					if (value === '') outValue = [];
					else outValue = value.split(spaceRegex).map(v => parseFloat(v));
				} else if (type === 'string[]') {
					if (value === '') outValue = [];
					else outValue = value.split(spaceRegex);
				} else if (type === 'Map<string,number>') {
					outValue = new Map();
					for (const pair of value.split(',')) {
						const array = pair.trim().split(spaceRegex);
						if (array.length >= 2) outValue.set(array[0], parseFloat(array[1]));
					}
				} else if (type === 'Vector2') {
					const vector2 = reusableObjectPropertyCacheProperty[property] = reusableObjectPropertyCacheProperty[property] || new Vector2();
					const valueAsArrayString = value.split(spaceRegex);
					if (valueAsArrayString.length === 2) {
						vector2.fromArray(valueAsArrayString.map(n => parseFloat(n)));
					}
					outValue = vector2;
				} else if (type === 'Vector3') {
					const vector3 = reusableObjectPropertyCacheProperty[property] = reusableObjectPropertyCacheProperty[property] || new Vector3();
					const valueAsArrayString = value.split(spaceRegex);
					if (valueAsArrayString.length === 3) {
						vector3.fromArray(valueAsArrayString.map(n => parseFloat(n)));
					}
					outValue = vector3;
				} else if (type === 'Quaternion') {
					const quaternion = reusableObjectPropertyCacheProperty[property] = reusableObjectPropertyCacheProperty[property] || new Quaternion();
					const valueAsArrayString = value.split(spaceRegex);
					if (valueAsArrayString.length === 4) {
						quaternion.fromArray(valueAsArrayString.map(n => parseFloat(n)));
					}
					outValue = quaternion;
				} else if (type === 'Euler') {
					const euler = reusableObjectPropertyCacheProperty[property] = reusableObjectPropertyCacheProperty[property] || new Euler();
					const valueAsArrayString = value.split(spaceRegex);
					if (valueAsArrayString.length === 3) {
						euler.fromArray(valueAsArrayString.map(n => parseFloat(n)*MathUtils.DEG2RAD));
					}
					outValue = euler;
				} else {
					let expectingArray = false;
					let arrayType = type;
					let qs = 'querySelector';
					let noArrayForSingle = false;
					if (type.slice(-2) === '[]') {
						expectingArray = true;
						arrayType = type.slice(0, -2);
						qs = 'querySelectorAll';
					}
					if (type.slice(-3) === '[]?') {
						expectingArray = true;
						arrayType = type.slice(0, -3);
						qs = 'querySelectorAll';
						noArrayForSingle = true;
					}

					outValue = async function () {
						let outValueFromEl = outValue;
						let foundElements = null;
						let isValidSelector = false;
						if (!value.includes('/') && value !== '#' && value !== '.' && !value.includes('-gradient(') && !value.includes('path(')) {

							// This supports using ::part() to get a sub element 
							const selectors = value.split('::');
							const rootNode = this.getRootNode();
							let result;
							try {
								if (rootNode) {
									result = rootNode[qs](selectors[0]);
								}
								if (!result || (expectingArray && result.length === 0)) {
									result = document[qs](selectors[0]);
								}
							} catch(e) {
								console.warn(e);
							}
							if (!expectingArray && result) window.customElements.upgrade(result);
							if (expectingArray) for (const el of result) window.customElements.upgrade(el);
							
							if (selectors.length === 1) {
								foundElements = expectingArray ? Array.from(result) : result;
							} else if (!expectingArray && result && result.isShortHandElement) {
								await result.object; // In case the object has internal parts which are populated during the object creation
								const part = selectors[1].match(/(part)\((.+)\)/);
								if (part && part[1] === 'part' && part[2]) {
									const partSearch = queryParts(result, part[2]);
									foundElements = partSearch[0] || null;
								}
							} else if (expectingArray && result.length) {
								foundElements = [];
								for (const el of result) {
									if (!el.isShortHandElement) continue;
									await el.object; // In case the object has internal parts which are populated during the object creation
									const part = selectors[1].match(/(part)\((.+)\)/);
									if (part && part[1] === 'part' && part[2]) {
										const partSearch = queryParts(el, part[2]);
										foundElements = foundElements.push(...partSearch);
									}
								}
							} else {
								foundElements = null;
							}
							isValidSelector = true;
						}


						if (!expectingArray && foundElements) {
							const el = foundElements;
							if (type === 'url') {
								if (el.src) outValueFromEl = el;
								outValueFromEl = value;
							} else {
								const object = await el.object;
								if (!THREE_TYPES[type]) {
									throw Error(`Unrecognised type in parser "${type}"`);
								}
								if (object instanceof THREE_TYPES[type]) {
									const wr = new WeakRef(this);
									outValueFromEl = el.object ? 
										(el.constructor.canProxy ? reflectObjectFromEl(el, attr, wr) : el.object) :
										el;

									if (el.isShortHandElement) el.onAssign(attr, wr);
									this.objectAssigned(attr, el);
								} else {
									console.warn(`${attr} was expecting a ${type} but instead received:`, object);
								}
							}
						} else if (isValidSelector && expectingArray && foundElements.length) {
							outValueFromEl = [];
							const type = arrayType;
							for (const el of foundElements) {
								const object = await el.object;
								if (!THREE_TYPES[type]) {
									throw Error(`Unrecognised type in parser ${type}`);
								}
								if (object instanceof THREE_TYPES[type]) {
									const wr = new WeakRef(this);
									outValueFromEl.push(el.object ? 
										(el.constructor.canProxy ? reflectObjectFromEl(el, attr, wr) : el.object) :
										el
									);
									if (el.isShortHandElement) el.onAssign(attr, wr);
									this.objectAssigned(attr, el);
								} else {
									console.warn(`${attr} was expecting a ${type} but instead received:`, object);
								}
							}
							if (noArrayForSingle && outValueFromEl.length === 1) outValueFromEl = outValueFromEl[0];
						} else if (isValidSelector) {
							console.warn('No element matches selector: ' + value);
						}

						// Probably a query selector which did not match
						if (typeof outValueFromEl === 'string' && (type !== 'string' && type !== 'url')) {
							outValueFromEl = undefined;
						}
					
						return outValueFromEl;
					}.bind(this)();
				}
			}
		}

		// Probably a query selector which did not match
		if (typeof outValue === 'string' && (type !== 'string' && type !== 'url')) {
			outValue = undefined;
		}

		return outValue;
	}
};
