import { BufferAttribute, Color, Vector3 } from "three";
// This just calculates how much an edge is creased, darkening at the edges, resulting in outer corners
// getting as dimmde as inner corners

export function dirtyVertex( geometry ) {
	const tempColor = new Color();
	const hashMultiplier = ( 1 + 1e-10 ) * 1e2;

	// reusable vertors
	const verts = [ new Vector3(), new Vector3(), new Vector3() ];
	const tempVec1 = new Vector3();
	const tempVec2 = new Vector3();
	const tempNorm = new Vector3();

	// hashes a vector
	function hashVertex( v ) {

		const x = ~ ~ ( v.x * hashMultiplier );
		const y = ~ ~ ( v.y * hashMultiplier );
		const z = ~ ~ ( v.z * hashMultiplier );
		return `${x},${y},${z}`;

	}

	const resultGeometry = geometry.index ? geometry.toNonIndexed() : geometry;
	const posAttr = resultGeometry.attributes.position;
	const vertexMap = {};

	// find all the normals shared by commonly located vertices
	for ( let i = 0, l = posAttr.count / 3; i < l; i ++ ) {

		const i3 = 3 * i;
		const a = verts[ 0 ].fromBufferAttribute( posAttr, i3 + 0 );
		const b = verts[ 1 ].fromBufferAttribute( posAttr, i3 + 1 );
		const c = verts[ 2 ].fromBufferAttribute( posAttr, i3 + 2 );

		tempVec1.subVectors( c, b );
		tempVec2.subVectors( a, b );

		// add the normal to the map for all vertices
		const normal = new Vector3().crossVectors( tempVec1, tempVec2 ).normalize();
		for ( let n = 0; n < 3; n ++ ) {

			const vert = verts[ n ];
			const hash = hashVertex( vert );
			if ( ! ( hash in vertexMap ) ) {

				vertexMap[ hash ] = [];

			}

			vertexMap[ hash ].push( normal );

		}

	}

	// average normals from all vertices that share a common location if they are within the
	// provided crease threshold
	const colorArray = new Float32Array( posAttr.count * 3 );
	const colorAttr = new BufferAttribute( colorArray, 3, false );

	let minCol=Infinity;
	let maxCol=-Infinity;
	for ( let i = 0, l = posAttr.count / 3; i < l; i ++ ) {

		// get the face normal for this vertex
		const i3 = 3 * i;
		const a = verts[ 0 ].fromBufferAttribute( posAttr, i3 + 0 );
		const b = verts[ 1 ].fromBufferAttribute( posAttr, i3 + 1 );
		const c = verts[ 2 ].fromBufferAttribute( posAttr, i3 + 2 );

		tempVec1.subVectors( c, b );
		tempVec2.subVectors( a, b );

		tempNorm.crossVectors( tempVec1, tempVec2 ).normalize();
		const center = tempVec1.copy(a).add(b).add(c).multiplyScalar(1/3);

		// average all normals that meet the threshold and set the normal value
		for ( let n = 0; n < 3; n ++ ) {


			const vert = verts[ n ];
			const hash = hashVertex( vert );
			const otherNormals = vertexMap[ hash ];
			const centerToVert = tempVec2.subVectors(center, vert);
	
			let val = 0;
			for ( let k = 0, lk = otherNormals.length; k < lk; k ++ ) {

				const otherNorm = otherNormals[ k ];
				const angle = tempNorm.dot( otherNorm );
				val += angle-0.5;

			}
			val /= otherNormals.length;
			val -= Math.max(tempNorm.dot(centerToVert) * 10, 0);
			tempColor.setHSL(0, 0, val);
			minCol = Math.min(minCol, tempColor.r);
			maxCol = Math.max(maxCol, tempColor.r);
			colorAttr.setXYZ( i3 + n, tempColor.r, tempColor.g, tempColor.b );
		}

	}

	// Normalize color
	for (let i=0,l=colorArray.length;i<l;i++) {
		colorArray[i] -= minCol-0.1;
		colorArray[i] *= 1/((maxCol - minCol)+0.1);
	}

	geometry.setAttribute( 'color', colorAttr );
	return geometry;

}
