import { schemas } from "./schema.js";
import { shortHandElement } from "./ShortHandElementClass.js";
import { cacheable, dashesToCamelCase, getComments, getMethods, getParamNames } from "./utils/utils.js";

/**
 * Merge two schema maps.
 * @param {Map<any>} dest 
 * @param {Map<any>} src 
 */
export function mergeSchemas(dest, src, originMap, originName) {
	for (const [attr, schemaOrMixin] of src) {
		if (attr === 'mixins') {
			dest.get('mixins').push(...schemaOrMixin);
		} else {
			if (schemaOrMixin) {
				if (dest.get(attr) !== schemaOrMixin) {
					if (originMap) originMap.set(attr, originName);
					dest.set(attr, schemaOrMixin);
				}
			}
			else dest.delete(attr);
		}
	}
}

export const registeredElements = new Set();
export const elementRegistry = new Map();
export const documentation = [];
export const signatureSeperator = '→';
export const schemaReference = new Map();

const customPropertySyntaxCache = new Map();
function registerCSSCustomProperties(elementName, schema) {

	const cssCustomPropertyPrototype = {
		inherits: false,
		initialValue: "none"
	};
	for (const [name, schemaEntry] of schema.entries()) {
		if (schemaEntry.as && schemaEntry.as.includes('.')) {
			schemaEntry.multipartAs = schemaEntry.as.split('.');
		}

		let shouldRegister = true;
		if (schemaEntry.noCustomPropertyRegistration || schemaEntry.map?.none !== undefined) {
			shouldRegister = false;
		}

		const type = schemaEntry.type || typeof schemaEntry.default;
		cssCustomPropertyPrototype.name = '--' + name;
		if (schemaEntry.customPropertySyntax) {
			cssCustomPropertyPrototype.syntax = schemaEntry.customPropertySyntax;
			shouldRegister = true;
		} else if (type === 'number') {
			cssCustomPropertyPrototype.syntax = '<number>|<custom-ident>|none';
		} else if (type === 'Color') {
			cssCustomPropertyPrototype.syntax = '<color>|<custom-ident>|none';
		} else if (type === 'angle') {
			cssCustomPropertyPrototype.syntax = '<angle>|<custom-ident>|none';
		} else if (type === 'percentage') {
			cssCustomPropertyPrototype.syntax = '<percentage>|<custom-ident>|none';
		} else if (type === 'Vector3' || type === 'Vector2' || type === 'Euler' || type === 'Quaternion') {
			cssCustomPropertyPrototype.syntax = '<number>+|<custom-ident>|none';
		} else if (type === 'boolean') {
			cssCustomPropertyPrototype.syntax = 'true|false|<custom-ident>|none';
		} else {
			cssCustomPropertyPrototype.syntax = '*';
			shouldRegister = false;
		}

		if (customPropertySyntaxCache.has(name)) {
			if (shouldRegister && customPropertySyntaxCache.get(name).syntax !== cssCustomPropertyPrototype.syntax) {
				console.warn(`${elementName}: Trying to redefine CSS property syntax for property ${name} as ${cssCustomPropertyPrototype.syntax}, is is already registered as ${customPropertySyntaxCache.get(name).syntax} in ${customPropertySyntaxCache.get(name).elementName}`);
			}
			shouldRegister = false;
		}

		if (shouldRegister) {
			try {
				window.CSS.registerProperty(cssCustomPropertyPrototype);
				customPropertySyntaxCache.set(name, {elementName, syntax: cssCustomPropertyPrototype.syntax});
			} catch (e) {
				console.warn(`${elementName}:--${name} ${e.message}`);
			}
		}
	}
}

export function patchElement(elementName, patch) {
	const oldRegistration = elementRegistry.get(elementName);
	const schema = new Map([['mixins', []]]);
	mergeSchemas(schema, oldRegistration.class.shortHandSchema);
	schemaReference.set(elementName, schema);

	const NewClass = class PatchedShortHandElement extends patch(oldRegistration.class) {};
	if (NewClass.shortHandSchema) mergeSchemas(schema, NewClass.shortHandSchema);
	registerCSSCustomProperties(elementName, schema);
	const sHA = Object.freeze([...schema.keys()]);
	const observedAttributes = Object.freeze(['will-change', ...sHA]);
	const FinalClass = class extends NewClass {
		static shortHandSchema = schema;
		static shortHandAttributes = sHA;
		static get observedAttributes() { return observedAttributes; };
	};
	oldRegistration.class = FinalClass;
	return FinalClass;
}


export function registerShortHandElement(elementName, {
	type: THREEClass, mixin: componentMixin, native: builtIn}
) {
	registeredElements.add(elementName);

	let FinalClass = builtIn? builtIn.class: HTMLElement;
	const schema = new Map([['mixins', []]]);
	const shortHandEventDescriptions = [];
	const shortHandEventNames = new Set();
	const originMap = new Map();
	const addedMixins = new Set();

	let docPriority = 0;

	let documentationString = '';
	let prevDoc = '';

	function applyMixin(mixin) {
		if (!mixin || addedMixins.has(mixin)) return; // Stop infinite loops
		addedMixins.add(mixin);
		const oldSignature = FinalClass.signature || FinalClass.name;
		FinalClass = cacheable(mixin)(FinalClass);
		if (FinalClass.documentation && FinalClass.documentation !== prevDoc) {
			prevDoc = FinalClass.documentation;
			documentationString += '\n\n' + FinalClass.documentation;
		}
		if (!FinalClass.name) console.warn('No name for ', mixin);
		FinalClass.signature = oldSignature + signatureSeperator + FinalClass.name;
		if (FinalClass.shortHandSchema) mergeSchemas(schema, FinalClass.shortHandSchema, originMap, FinalClass.name);
		if (FinalClass.shortHandEventDescriptions) {
			for (const [eventName,description] of Object.entries(FinalClass.shortHandEventDescriptions)) {
				shortHandEventDescriptions.push({
					eventName,description,source:FinalClass.name
				});
				shortHandEventNames.add(eventName);
			}
		}
		if (Number.isFinite(FinalClass.documentationPriority)) {
			docPriority += FinalClass.documentationPriority;
		} else {
			docPriority -= 1;
		}
		for (const mixin of schema.get('mixins')) applyMixin(mixin);
	}

	// Apply the main shortHandElement mixin
	applyMixin(shortHandElement);

	// Add the schema entries for instanceof object types in from the schema file
	for (const [Type, schemaEntries] of schemas.entries()) {
		if (THREEClass.prototype instanceof Type) mergeSchemas(schema, schemaEntries, originMap,'Schema Entry for ' + Type.name);
	}
	while (schema.get('mixins').length) for (const mixin of schema.get('mixins').splice(0)) applyMixin(mixin);

	// Add the schema entries for direct matches from the schema file
	for (const [Type, schemaEntries] of schemas.entries()) {
		if (THREEClass === Type) mergeSchemas(schema, schemaEntries, originMap, 'Schema Entry for ' + Type.name);
	}
	while (schema.get('mixins').length) for (const mixin of schema.get('mixins').splice(0)) applyMixin(mixin);

	// Finally add the main component mixin
	applyMixin(componentMixin);

	// if more mixins were added by the main component then add those too
	while (schema.get('mixins').length) for (const mixin of schema.get('mixins').splice(0)) applyMixin(mixin);

	// Delete the now empty array it's not needed
	schema.delete('mixins');

	registerCSSCustomProperties(elementName, schema);

	const sHA = Object.freeze([...schema.keys()]);
	const observedAttributes = Object.freeze(['will-change', ...sHA]);
	const ThisThing = class extends FinalClass {
		static THREEClass = THREEClass;
		static name = dashesToCamelCase(elementName);
		static shortHandEventNames = shortHandEventNames;

		static shortHandSchema = schema;
		static shortHandAttributes = sHA;
		static get observedAttributes() { return observedAttributes; };
	};

	elementRegistry.set(elementName, {
		type: THREEClass, mixin: componentMixin, class: ThisThing
	});

	documentation:
	{
		const schema = Object.fromEntries(Array.from(ThisThing.shortHandSchema.entries()).map(entry => {
			const out = Object.assign({}, entry[1]);
			delete out.as;
			delete out.constructorArgument;
			delete out.stage;
			out.type =  out.type || ((typeof out.default !== 'undefined') && typeof out.default);
			out.default = out.default || undefined;

			if (typeof out.type === 'undefined' && typeof out.default === 'undefined') {
				console.error({type: out.type, default: out.default});
				console.error(`${elementName} has an invalid schema for ${entry[0]} one of type or default needs to be set.`);
			}

			return [entry[0], out];
		}).filter(o => !!o));
		const exampleString = Array.from(ThisThing.shortHandSchema.entries()).map(([attr, details]) => details.example && `${attr}="${details.example}"`).filter(s=>!!s).join(' ');
		
		const methods = [];
		const Original = shortHandElement(builtIn? builtIn.class: HTMLElement);
		const originalNames = getMethods(Original.prototype);
		for (const name of getMethods(ThisThing.prototype)) {
			try {
				if (!originalNames.includes(name)) {
					let currentObj = ThisThing.prototype;
					let out;
					do {
						if (Object.hasOwn(currentObj, name)) out = currentObj;
					} while (!out && (currentObj = Object.getPrototypeOf(currentObj)));
					methods.push({
						name,
						arguments: getParamNames(ThisThing.prototype[name]),
						comment: out.constructor.name + ': ' + (getComments(ThisThing.prototype[name])[0] || '').replace(/(^[/*\s]+)|([/*\s]+$)|\n[\s*]*/mg, ' ').trim(),
					});
				}
			// eslint-disable-next-line no-unused-vars
			} catch (e) {
				// Do nothing
			}
		}
		
		documentation.push({
			signature: ThisThing.signature,
			name: elementName,
			documentation: documentationString.replace(/\n\n\n+/, '\n\n').replace(/^\n+/, '').replace(/\n+$/, ''),
			className: THREEClass.name,
			example: `<${builtIn ? builtIn.tagName + ` is="${elementName}"` : elementName}${exampleString ? ' ' + exampleString : ''}>`,
			exampleShort: `<${builtIn ? builtIn.tagName + ` is="${elementName}"` : elementName}>`,
			schema,
			originMap,
			methods,
			docPriority,
			eventDescriptions: shortHandEventDescriptions
		});
	}

	schemaReference.set(elementName, schema);

	// Default behaviour, don't do this in node.
	if(typeof process !== 'object') {
		queueMicrotask(() => customElements.define(elementName, elementRegistry.get(elementName).class, builtIn && { extends: builtIn.tagName }));
	}
}
