/**
 * 
 * @param {BufferGeometry} geometry 
 * @returns 
 */
export function flipNormals( geometry ) {
	const resultGeometry = geometry.index ? geometry.toNonIndexed() : geometry;
	const posArray = resultGeometry.attributes.position.array;

	for ( let i = 0, l = posArray.length; i < l; i += 9 ) {
		[posArray[i + 0], posArray[i + 6]] = [posArray[i + 6], posArray[i + 0]];
		[posArray[i + 1], posArray[i + 7]] = [posArray[i + 7], posArray[i + 1]];
		[posArray[i + 2], posArray[i + 8]] = [posArray[i + 8], posArray[i + 2]];
	}
	return resultGeometry;
}
