import { defaultDocumentationMessage } from '../strings.js';
import { html as uhtml, render } from 'uhtml/keyed';
import { html } from '../utils/utils.js';
import DOMPurify from 'dompurify';
import { registerShortHandElement, schemaReference } from '../customElementRegistration.js';
import { Layers } from 'three';
import { querySelectorAllLive, shortHandSchema } from '../utils/utils.js';
import { REQUIRES_RECONSTRUCT, STORED_ON_EL } from '../schema.js';

let documentation = defaultDocumentationMessage;
documentation: {

	// Add any documentation for the README in here perhaps describe what attributes are optional
	// or how to use it.
	documentation = `The use example copies a template and will replace values to match those set in the attributes e.g:

\`\`\`html
<template>
	<sh-mesh geometry="\${shape|sphere}" material="gold" location="\${my-location|0 1 -2}"></sh-mesh>
</template>

<sh-use href="template" shape="box" style="--my-location: 0.5 0.5 -1;"></sh-use>
<sh-use href="template" shape="box" style="--my-location: -0.5 0.5 -1;"></sh-use>
\`\`\`

If any of the attributes change it will update but if you have animating CSS properties then you need to use \`will-change\`
`;
}

const purifySettings = {
	ALLOWED_ATTR: ['style', 'name'],
	ADD_TAGS: ['style', 'slot'],
	USE_PROFILES: {html: true},
	FORCE_BODY: true,
	CUSTOM_ELEMENT_HANDLING: {
		tagNameCheck: (tagName) => tagName.match(/^sh-/),
		attributeNameCheck: () => true,
		allowCustomizedBuiltInElements: true, // allow customized built-ins
	},
};

const templatePre = `<style>
:host {
	display: block;
}
</style>
`;

export const name = 'Use';

const tagRegex = /<([a-z0-9-]+)[^<>]+$/i;
const attrRegex = /([a-z0-9-]+)="$/i;
const slotContentsRegex = /SLOT_CONTENTS\(\s*(.*)\s*\)/;
export class UseClass {
	#template;
	#computedStyle;
	#sceneEls;
	constructor(href) {
		this.href = href;
	}
	build(el) {
		this.#computedStyle = this.#computedStyle || window.getComputedStyle(el);
		const needsSlot = !this.href.content.querySelector('slot:not([name])');
		const slots = Array.from(this.href.content.querySelectorAll('slot')).map(slot => slot.outerHTML).join('');
		el.shadowRoot.innerHTML = slots;
		this.#template = [[], []];
		let text = this.href.innerHTML;
		const clean = templatePre + DOMPurify.sanitize( text, purifySettings) + (needsSlot ? '<slot></slot>' : '');
		clean.split(/\$\{(?<attr>[^$]+)\}/g).forEach((o,i) => this.#template[i%2].push(i%2?o.split('|'):o));

		let tag;
		for (let i=0,l=this.#template[1].length;i<l;i++) {
			const detail = this.#template[1][i];
			const lastTagIfInElement = this.#template[0][i].match(tagRegex);
			if (lastTagIfInElement) {
				tag = lastTagIfInElement[1];
			}
			const elAttr = this.#template[0][i].trim().match(attrRegex)?.[1];
			if (elAttr && tag) {
				const schema = schemaReference.get(tag)?.get(elAttr);
				if (schema) {
					this.#template[1][i][2] = schema;
				} else {
					console.log('No schema found, ' + tag + ' ' + elAttr);
					console.log(this.#template[0][i] + '${' + detail + '}' + (this.#template[0][i+1] || ''));
				}
			}
		}

		this.update(el);
		this.#sceneEls = querySelectorAllLive(el.shadowRoot, '*');
	}
	#detailToString(detail, el) {
		const [attr, defaultValue, schema] = detail;

		const isSlotContents = attr.match(slotContentsRegex);
		if (isSlotContents) {
			let slot;
			const slotName = isSlotContents[1];
			if (!slotName) {
				slot = el.shadowRoot.querySelector('slot');
			} else {
				slot = el.shadowRoot.querySelector('slot[name="' + slotName + '"]');
			}
			if (slot) return uhtml(slot.assignedNodes().map(n => n.outerHTML ? n.outerHTML : n.textContent));
			return '';
		}

		let cssValue = this.#computedStyle.getPropertyValue('--' + attr);
		let valueToUse = cssValue || el.getAttribute(attr);
		if (valueToUse === 'none' && !(schema.map && typeof schema.map.none === 'undefined')) {
			valueToUse = el.getAttribute(attr) || null;
		}
		return valueToUse ||
		defaultValue ||
		"";
	}
	update(el) {
		render(el.shadowRoot, uhtml(
			this.#template[0],
			...this.#template[1].map(detail => this.#detailToString(detail, el))
		));
	}
	dispose() {
		console.log('Removed from DOM');
	}

	visible = true;
	layers = new Layers();
	raycast(raycaster, intersects) {
		if (!this.#sceneEls) return;
		for (const el of this.#sceneEls) {
			const o = el.object;
			if (o && o.raycast) {
				if (el.properties &&
					(
						el.properties.pointerEvents === 2 ||
						((el.properties.pointerEvents === 1 || el.properties.pointerEvents === undefined) && o.visible)
					)
				) o.raycast(raycaster, intersects);
			}
		}
	}
	getEls() {
		return this.#sceneEls;
	}
}

const observer = new MutationObserver((mutations) => { 
	mutations.forEach((mutation) => {
		if (!(mutation.target.object instanceof Promise)) {
			mutation.target.object.update(mutation.target);
		}
	});
});
const config = { attributes: true };

