export const type = UseClass;

/** @param {typeof HTMLElement} baseClass */
export const mixin = (baseClass) => class extends baseClass {
	static shortHandSchema = shortHandSchema({
		href: { type: 'Element', stage: STORED_ON_EL | REQUIRES_RECONSTRUCT },
	});
	static name = name;
	static documentation=documentation;
	static noWarnForUnrecognisedAttributes = true;
	#attrCache = {};
	properties = {
		pointerEvents: 2 // this is hacky because this is an unconfigurable property, should create better way to do this
	};

	constructor() {
		super();

		// Check if the HTML changes
		observer.observe(this, config);
		this.attachShadow({mode: 'open'});
		this.shadowRoot.addEventListener('slotchange', async () => {
			(await this.object).update(this);
		});
	}

	stringToValue(attr, value) {
		if (attr === 'href') {
			const parseAsURL = value.trim().match(/^((std:(?<stdPath>[^\s]+))|(?<url>[^\s]+)#(?<id>[^\s]+))$/i);
			if (parseAsURL) {
				if (parseAsURL.groups.stdPath) {
					if (standardTemplates.has(parseAsURL.groups.stdPath)) {
						return standardTemplates.get(parseAsURL.groups.stdPath);
					} else {
						throw Error(`No template called "${parseAsURL.groups.stdPath}" in the standard template library.`);
					}
				} else if (parseAsURL.groups.url) {
					// console.log('From remote address' + parseAsURL.groups.url + '\n' + parseAsURL.groups.id);
					return fetch(parseAsURL.groups.url)
						.then(response => response.text())
						.then(text => {
							const clean = DOMPurify.sanitize( text, purifySettings );
							const tempTemplate = document.createElement('template');
							tempTemplate.innerHTML = clean;
							const part = tempTemplate.content.getElementById(parseAsURL.groups.id);
							if (!part) throw Error(`Could not find element with id ${parseAsURL.groups.id} on ${parseAsURL.groups.url}`);
							else if (part.tagName === 'TEMPLATE') {
								return part;
							} else {
								const template = document.createElement('template');
								template.innerHTML = part.outerHTML;
								return template;
							}
						});
				}
			}
		}
		return super.stringToValue(attr, value);
	}

	tick(time, delta, frame, renderer, session) {

		super.tick(time, delta, frame, renderer, session);

		// Check if the CSS values change
		const computedStyle = window.getComputedStyle(this);
		if (this.object instanceof UseClass) {
			let needsUpdate = false;
			for (const attr of this.__shTrackedAttributes) {
				const value = computedStyle.getPropertyValue('--' + attr);
				if (value !== this.#attrCache[attr]) {
					this.#attrCache[attr] = value;
					needsUpdate = true;
				}
			}
			if (needsUpdate) this.object.update(this);

			for (const child of this.object.getEls()) {
				if (child.tick && !(child.object instanceof Promise) && !child.isShRenderer) {
					child.tick(time, delta, frame, renderer, session);
				}
			}
		}

	}

	async allAttributesChangedCallback() {
		const object = new UseClass(this.properties.href);
		await this.assignPostConstructAttributes(object);
		object.build(this);
		this.updateObject(object);
	}
};

export function registerTemplateToElement(name, href) {
	const elementMixin = (baseClass) => class extends mixin(baseClass) {
		static shortHandSchema = shortHandSchema({});
		static name = 'QuickStart';
		static documentation=`A wrapper for <sh-use href="${href}">`;
		async allAttributesChangedCallback() {
			const object = new UseClass(this.stringToValue('href', href));
			await this.assignPostConstructAttributes(object);
			object.build(this);
			this.updateObject(object);
		}
	};
	registerShortHandElement(name, {
		type: UseClass,
		mixin: elementMixin
	});
}
