import { PositionalAudio, Audio, Group } from 'three';
import { defaultDocumentationMessage } from '../strings.js';
import { getListener } from './audioListener.js';
import { shortHandSchema } from '../utils/utils.js';
import { REQUIRES_RECONSTRUCT, STORED_ON_EL } from '../schema.js';

let documentation = defaultDocumentationMessage;
documentation: {
	documentation = `Playback positional audio.`;
}

export const name = 'Audio';
export const type = PositionalAudio; // Replace with what ever THREE object this is 
export const native =  {class: HTMLAudioElement, tagName: 'audio'}; // Optional in case the element extends a native element
/** @param {typeof HTMLAudioElement} baseClass */
export const mixin = (baseClass) => class extends baseClass {
	static shortHandSchema = shortHandSchema({
		'static': {default: false, stage: STORED_ON_EL | REQUIRES_RECONSTRUCT},
		'volume': {default: 1, stage: STORED_ON_EL }
	});
	static name = name;
	static documentation=documentation; 

	#audio;
	constructor() {
		super();
		this.addEventListener('play', this, {
			once: true
		});
	}

	get volume() {
		return this.properties.volume;
	}

	set volume(v) {
		this.properties.volume = v;
		this.updateVolume();
	}

	updateVolume() {
		if (this.#audio) this.#audio.setVolume(this.properties.volume);
	}

	async attributeChangedCallback(attr, oldValue, newValue, fromStyleChange) {
		await super.attributeChangedCallback(attr, oldValue, newValue, fromStyleChange);

		if (attr === 'volume') this.updateVolume();
	}


	handleEvent(e) {
		if (e.type === 'play') {
			const audio = new (this.properties.static ? Audio : PositionalAudio)(getListener());
			
			audio.setMediaElementSource(this);
			this.object.add(audio);
	
			this.#audio = audio;

			this.updateVolume();
		}
	}

	async allAttributesChangedCallback() {
		const object = new Group();
		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
};
