import { pathToCurvePath, pathToShape } from './pathTo.js';
import { BufferGeometry, CurvePath, Line, Mesh, Quaternion, ShapeGeometry, Vector2, Vector3 } from "three";
import { mixins as transformMixins, changeOn as transformChangeOn } from "../transform.js";
import { toCreasedNormals } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { getRectanglePath } from './pathToRect.js';
import { ExtrudeGeometry } from './extrude-geometry.js';
import { dirtyVertex } from './dirty-vertex.js';
import { flipNormals } from './flip-normals.js';
import { buildIndex } from './build-index.js';
import { prettyPrintElement } from '../../utils/utils.js';
import { THREE_TYPES } from '../../schema-type-parsing.js';

Object.assign(THREE_TYPES, {CurvePath});

const documentation = `You can use path() to define geometry e.g. \`geometry="path(some svg style path)"\` the syntax is \`path(shapeA)/path(holeA) path(holeB), path(shapeB)/path(holeC) [{number of  subdivisions} {path3d(path to extrude along) | path(custom bevel path)} ] [depth [bevelSize] [bevelThickness]] ["smooth"] ["ao"] ["inside"]"\`

It also supports rect([width] [height] [radiusX] [radiusY] [offsetX] [offsetY])

some examples: Two concentric circles, Aligned to be on 0,0 and go up 0.5cm in the y direciton.
\`\`\`
geometry="path(M0-.027A.027.027 0 110 .027.027.027 0 110-.027) / path(M0-.0225A.0225.0225 0 100 .0225.0225.0225 0 100-.0225), path(M0-.015A.015.015 0 110 .015.015.015 0 110-.015) / path(M0-.01A.01.01 0 100 .01.01.01 0 100-.01) 1 path(m0 0l0 .005) smooth ao"
\`\`\`

some examples: A sword with 0.1 depth and 0.01 bevel
\`\`\`
geometry="path(M-.1.3.5-.4.8-.5.7-.2 0 .4C.1.5.1.6.2.5.2.6.3.7.2.7A.142.142 90 01.1.8.5.5 90 00-.1.5Q-.15.49-.15.55T-.3.68-.38.6-.25.45-.2.4A.5.5 90 00-.5.2.142.142 90 01-.4.1C-.4 0-.3.1-.2.1-.3.2-.2.2-.1.3M.5-.4.5-.2.7-.2.52-.22.5-.4) 0.1 0.01"
\`\`\`
`;

function getCurvePath(data, is3d) {
	try {
		return pathToCurvePath(data, is3d);
	} catch (e) {
		const {location} = e;
		if (location) {
			console.log(`%c${e.message}\n %c${data.slice(0,location.start.offset)}%c${data.slice(location.start.offset,location.end.offset)}%c${data.slice(location.end.offset)}`,
				'color:orange;','','font-weight:bold;color:red;','');
		} else {
			console.log(e);
		}
		return false;
	}
}

export function register (registerShortHandElement,  schema) {
	const curveSegments = 8;
	const tempVector2 = new Vector2();
	const tempVector3 = new Vector3();
	const tempQuaternion = new Quaternion();
	const xAxis = new Vector3(1,0,0);
	const zAxis = new Vector3(0,0,1);
	const geomRegex = /^(?<shapes>(?:(?<pathtypeA>path|path2d|rect)\((?:[^)]+)\)\s*((?:\/\s*(?<pathtypeB>path|path2d|rect)\((?:[^)]+)\)?))*\s*,?\s*)+)(?<extrudePathOrBevel>(?:(?<steps>[\d.e]+))\s+(?:(?:path3d\((?<extrudePathData>[^)]+)\))|(?:path\((?<frontBevelPathData>[^)]+)\)\s*(?:\spath\((?<backBevelPathData>[^)]+)\))?)?))?(?:\s+(?<depth>[\d.e]+))?(?:\s+(?<bevelSize>[\d.e]+))?(?:\s+(?<bevelThickness>[\d.e]+))?(?:\s+(?<flags>((smooth|ao|inside)\s*)+))?\s*$/i;
	const shapeRegex = /(?<pathtypeA>path|path2d|rect)\((?<shapeData>[^)]+)\)\s*(\/\s*(?<holes>(?:\s*(?<pathtypeB>path|path2d|rect)\((?:[^)]+)\)?)*))?/gi;
	const holeRegex = /(?<pathtype>path|path2d|rect)\((?<holeData>[^)]+)\)/g;
	const rectRegex = /(?<width>[\d.e]+)?\s*(?<height>[\d.e]+)?\s*(?<rx>[\d.e]+)?\s*(?<ry>[\d.e]+)?\s*(?<x>[-\d.e]+)?\s*(?<y>[-\d.e]+)?/;
	const shapeParseMixin = baseclass => class extends baseclass {
		static name = 'PathParser';
		static documentation = documentation;

		stringToValue(attr, value) {
			const schemaEntry = this.constructor.getSchemaEntry(attr);
			const type = schemaEntry.type;

			if ((type === 'Geometry' || type === 'BufferGeometry') && this.constructor.THREEClass === Line) {
				const p = value.trim().match(/^(path|path2d|path3d|rect)\((.*)\)$/);
				if (p) {
					let [,command,data] = p;
					const is3D = command === 'path3d';
					if (command === 'rect') {
						data = getRectanglePath(data.trim().match(rectRegex).groups);
					}
					try {
						const curvePath = pathToCurvePath(data, is3D);
						return new BufferGeometry().setFromPoints( curvePath.getPoints(curveSegments) );
					} catch (e) {
						const {location} = e;
						if (location) {
							console.log(`%c${e.message}\n %c${data.slice(0,location.start.offset)}%c${data.slice(location.start.offset,location.end.offset)}%c${data.slice(location.end.offset)}`,
								'color:orange;','','font-weight:bold;color:red;','');
						} else {
							console.log(e);
						}
						return null;
					}
				}
			} else if (type === 'Geometry' || type === 'BufferGeometry') {
				const p = value.trim().match(geomRegex);
				if (p) {
					let {
						depth,
						bevelSize,
						bevelThickness,
						flags,
						shapes,
						steps,
						extrudePathData,
						frontBevelPathData,
						backBevelPathData,
					} = p.groups;
					const flagArray = flags ? flags.split(/\s+/) : [];
					const isSmooth = flagArray.includes('smooth');
					const isAO = flagArray.includes('ao');
					const isInside = flagArray.includes('inside');

					steps = parseFloat(steps || 1);
					depth = parseFloat(depth || 0);
					bevelSize = parseFloat(bevelSize || 0);
					const bevelThicknessValue = parseFloat(bevelThickness || 0);

					/**
					 * @type {CurvePath}
					 */
					let frontBevel, backBevel, extrudePath;
					if (extrudePathData) extrudePath = getCurvePath(extrudePathData);
					if (frontBevelPathData) frontBevel = getCurvePath(frontBevelPathData);
					if (backBevelPathData) backBevel = getCurvePath(backBevelPathData);

					let data;
					let hasHoles = false;
					const shape = Array.from(shapes.matchAll(shapeRegex)).map(match => {
						data = match.groups.shapeData;
						if (match.groups.pathtypeA === 'rect') {
							data = getRectanglePath(data.trim().match(rectRegex).groups);
						}
						const shape = pathToShape(data);
						if (match.groups.holes) shape.holes = Array.from(match.groups.holes.matchAll(holeRegex)||[]).map(match => {
							data = match.groups.holeData;
							hasHoles = true;
							if (match.groups.pathtype === 'rect') {
								data = getRectanglePath(data.trim().match(rectRegex).groups);
							}
							return getCurvePath(data);
						});
						return shape;
					});

					if (depth || extrudePath || frontBevel) {
						const bevelSegments = frontBevel ? steps : 5;
						const geometry = new ExtrudeGeometry(shape, {
							depth,
							bevelEnabled: !!(bevelSize || frontBevel) && !extrudePath,
							bevelSegments,
							steps,
							bevelSize,
							extrudePath,
							bevelContourFront: frontBevel ? t=>(frontBevel.getPoint(t, tempVector2), {
								z: tempVector2.y,
								bs: isInside ? -tempVector2.x : tempVector2.x
							}) : undefined,
							bevelContourBack: backBevel ? t=>(backBevel.getPoint(t, tempVector2), {
								z: -tempVector2.y,
								bs: isInside ? -tempVector2.x : tempVector2.x
							}) : undefined,
							bevelThickness: bevelThickness ? bevelThicknessValue : bevelSize,
							curveSegments
						});
						geometry.rotateX(-Math.PI/2);
						let outGeometry = geometry;
						if (isInside) outGeometry = flipNormals(outGeometry);
						if (isAO) outGeometry = dirtyVertex(outGeometry);
						if (isSmooth) outGeometry = toCreasedNormals(outGeometry);
						return buildIndex(outGeometry, prettyPrintElement(this) + '-extruded-geometry', hasHoles);
					} else {
						const geometry = new ShapeGeometry(shape);
						return  buildIndex(geometry);
					}
				}
			}
			return super.stringToValue(attr, value);
		}
	};

	schema.schemas.get(Line).get('mixins').push(shapeParseMixin);
	schema.schemas.get(Mesh).get('mixins').push(shapeParseMixin);
	const pathParseMixin = baseclass => class extends baseclass {
		static name = 'PathParser';

		stringToValue(attr, value) {
			const schemaEntry = this.constructor.getSchemaEntry(attr);
			const type = schemaEntry.type;

			if (type === 'CurvePath') {
				const p = value.trim().match(/^(path|path2d|path3d)\((.+)\)$/);
				if (!p) return null;
				const [,command,data] = p;
				const is3D = command === 'path3d';
				try {
					const curvePath = pathToCurvePath(data, is3D);
					curvePath.is2DPath = !is3D;
					return curvePath;
				} catch (e) {
					const {location} = e;
					if (location) {
						console.log(`%c${e.message}\n %c${data.slice(0,location.start.offset)}%c${data.slice(location.start.offset,location.end.offset)}%c${data.slice(location.end.offset)}`,
							'color:orange;','','font-weight:bold;color:red;','');
					} else {
						console.log(e);
					}
					return null;
				}
			}
			return super.stringToValue(attr, value);
		}
	};

	transformChangeOn.push('offset-path', 'offset-distance');
	transformMixins.push(baseclass => class extends baseclass {
		static name = 'OffsetPath';
		static shortHandSchema = new Map([
			["mixins", [pathParseMixin]],
			['offset-path', { as: 'offsetPath', type: 'CurvePath', stage: schema.STORED_ON_EL }],
			['offset-distance', {  as: 'offsetDistance', type: 'percentage', stage: schema.STORED_ON_EL }],
		]); // Optional: but you probably want it, see ../schema.js for examples

		#waitingForOffsetPath=[];
		async #updatePose() {
			if (
				typeof this.properties.offsetPath === 'object' &&
				typeof this.properties.offsetDistance !== 'undefined'
			) {
				this.properties.offsetPath.getPoint(this.properties.offsetDistance, tempVector3);
				if (this.properties.offsetPath.is2DPath) tempVector3.applyAxisAngle(xAxis,Math.PI/2); // rotate into xz plane
				this.object.position.add(tempVector3);

				this.properties.offsetPath.getTangent(this.properties.offsetDistance, tempVector3);
				if (this.properties.offsetPath.is2DPath) tempVector3.applyAxisAngle(xAxis,Math.PI/2); // rotate into xz plane
				tempQuaternion.setFromUnitVectors(zAxis, tempVector3);
				this.object.quaternion.multiply(tempQuaternion);
			}
		}

		async connectedCallback() {
			await super.connectedCallback();
			await this.#updatePose();
					
			// For debugging
			// if (this.properties.offsetPath) {
			// 	const material = new LineBasicMaterial( { color: 0x0000ff } );
			// 	const points = this.properties.offsetPath.getPoints(24).map(p => {
			// 		if (this.properties.offsetPath.is2DPath) {
			// 			p.applyAxisAngle(xAxis,Math.PI/2);
			// 		}
			// 		return p;
			// 	});
			// 	const geometry = new BufferGeometry().setFromPoints(points);
			// 	(await this.object).parent.add(new Line( geometry, material ));
			// 	console.log(points);
			// }
		}
	
		async attributeChangedCallback(attr, oldValue, newValue, styleAttributeChange) {
			await super.attributeChangedCallback(attr, oldValue, newValue, styleAttributeChange);
			if (attr === 'offset-path' || attr === 'offset-distance') await this.#updatePose(attr);
		}
	});
}

