import { prettyPrintElement } from "./utils";


function checkStillValid(elWeakRef, attr, usingElWeakRef) {
	const el = elWeakRef.deref();
	if (!el) {
		const usingEl = usingElWeakRef.deref();
		if (usingEl) {
			console.log(`${attr} on ${prettyPrintElement(prettyPrintElement(this))} references a cleaned up element.`);
			usingEl.attributeChangedCallback(attr, usingEl.attributes.getNamedItem(attr) || '', null);
		}
	}
	return el;
}

/* This allows us to get a proxy for the current object an element so that if it gets
reconstructed with a new object the updated one is available */
/** @type {WeakMap<HTMLElement,Proxy<HTMLElement>} */
const elProxies = new WeakMap();
/**
 * Returns a proxy that will clean itself up if the original object is destroyed
 * @param {HTMLElement} el 
 * @param {string} attr 
 * @param {WeakRef<HTMLElement>} usingEl 
 * @returns 
 */
export function reflectObjectFromEl(el, attr, usingElWeakRef) {
	if (elProxies.has(el)) return elProxies.get(el);
	const prettyElName = prettyPrintElement(el);
	const elWeakRef = new WeakRef(el);
	const proxy = new Proxy ({el: elWeakRef, get original() {return elWeakRef.deref()?.object;}}, {
		get(target, prop) {
			const el = checkStillValid(elWeakRef, attr, usingElWeakRef);
			if (!el) throw Error(`Element ${prettyElName} used as ${attr} has been garbage collected, make sure you unassign it first.`);
			if (!el.object) throw Error('Element.object is undefined');
			return Reflect.get(el.object, prop);
		},
		set(target, prop, value) {
			const el = checkStillValid(elWeakRef, attr, usingElWeakRef);
			if (!el) throw Error(`Element ${prettyElName} used as ${attr} has been garbage collected, make sure you unassign it first.`);
			if (!el.object) throw Error('Element.object is undefined');
			return Reflect.set(el.object, prop, value);
		},
		defineProperty(target, property, attributes) {
			const el = checkStillValid(elWeakRef, attr, usingElWeakRef);
			if (!el) throw Error(`Element ${prettyElName} used as ${attr} has been garbage collected, make sure you unassign it first.`);
			if (!el.object) throw Error('Element.object is undefined');
			return Reflect.defineProperty(el.object, property, attributes);
		},
		deleteProperty(target, p) {
			const el = checkStillValid(elWeakRef, attr, usingElWeakRef);
			if (!el) throw Error(`Element ${prettyElName} used as ${attr} has been garbage collected, make sure you unassign it first.`);
			if (!el.object) throw Error('Element.object is undefined');
			return Reflect.deleteProperty(el.object, p);
		},
		has(target, p) {
			const el = checkStillValid(elWeakRef, attr, usingElWeakRef);
			if (!el) throw Error(`Element ${prettyElName} used as ${attr} has been garbage collected, make sure you unassign it first.`);
			if (!el.object) throw Error('Element.object is undefined');
			return Reflect.deleteProperty(el.object, p);
		},
		isExtensible() {
			const el = checkStillValid(elWeakRef, attr, usingElWeakRef);
			if (!el) throw Error(`Element ${prettyElName} used as ${attr} has been garbage collected, make sure you unassign it first.`);
			return Reflect.isExtensible(el.object);
		},
		getPrototypeOf() {
			const el = checkStillValid(elWeakRef, attr, usingElWeakRef);
			if (!el) throw Error(`Element ${prettyElName} used as ${attr} has been garbage collected, make sure you unassign it first.`);
			return Reflect.getPrototypeOf(el.object);
		},
		setPrototypeOf(target, v) {
			const el = checkStillValid(elWeakRef, attr, usingElWeakRef);
			if (!el) throw Error(`Element ${prettyElName} used as ${attr} has been garbage collected, make sure you unassign it first.`);
			return Reflect.setPrototypeOf(el.object, v);
		}
	});

	elProxies.set(el, proxy);
	return proxy;
}
