import { defaultDocumentationMessage } from '../strings.js';
import { shortHandSchema } from '../utils/utils.js';
import { THREE_TYPES } from '../schema-type-parsing.js';
import { defaultGeomMap } from '../schema.js';
import { Group } from 'three';

let documentation = defaultDocumentationMessage;
documentation: {
	documentation = `Use this to render a shape from BatchedMesh`;
}

class BatchedMeshItem extends Group {
	constructor (properties) {
		super();
		this.for = properties.for;
		this.requestedGeometry = properties.requestedGeometry;
	}
}

Object.assign(THREE_TYPES, {BatchedMeshItem});

export const name = 'BatchedMeshItem';
export const type = BatchedMeshItem; // Replace with what ever THREE object this is 
/** @param {typeof HTMLElement} baseClass */
export const mixin = (baseClass) => class extends baseClass {
	static shortHandSchema = shortHandSchema({
		shape: {default: 0},
		geometry: {as: 'requestedGeometry', map: defaultGeomMap, type: 'BufferGeometry', default: "box"}
	});

	static name = name;
	static documentation=documentation;
};
