import { THREE_TYPES } from '../schema-type-parsing.js';
import { defaultDocumentationMessage } from '../strings.js';
import { ShortHandCustomEvent, html } from '../utils/utils.js';

export class SHWebXRSessionConfig extends EventTarget {

	/** @type {WeakRef<WebGLRenderer>} **/
	renderer;
	async setRenderer(renderer) {
		this.renderer = renderer;
		(await renderer.deref().object).xr.setFoveation(this.#tempFoveation);
	}

	session = null;
	constructor ({
		domOverlay,
		referenceSpaceType = 'local-floor',
		optionalFeatures = [], // e.g. 'hand-tracking', 'layers', 'hit-test', 'lighting-estimation'
		requiredFeatures = []
	}) {
		super();
		this.optionalFeatures = optionalFeatures;
		this.requiredFeatures = requiredFeatures;
		this.referenceSpaceType = referenceSpaceType;
		this.requiredFeatures.push(referenceSpaceType);
		this.domOverlay = domOverlay;
	}
	#tempFoveation = 1;
	set foveation(value) {
		this.#tempFoveation = value;
		if (!this.renderer) {
			return;
		}
		const renderer = this.renderer.deref().object;
		renderer.xr.setFoveation(value);
	}
	get foveation() {
		if (!this.renderer) return this.#tempFoveation;
		const renderer = this.renderer.deref().object;
		return renderer.xr.getFoveation();
	}
	addOptionalFeature(name) {
		this.optionalFeatures.push(name);
	}
	addRequiredFeature(name) {
		this.requiredFeatures.push(name);
	}
	async enterVR() {
		return this.#enterSession('immersive-vr');
	}
	async enterAR() {
		return this.#enterSession('immersive-ar');
	}
	async enterInlineXR() {
		return this.#enterSession('inline');
	}
	async #enterSession(type) {
		if (!navigator.xr) throw ('WebXR is not avaialble in this browser.');
		if (this.session) throw Error('Already in session');
		const sessionInit = this;
		const session = await navigator.xr.requestSession( type, sessionInit );
		session.addEventListener( 'end', (function onSessionEnd(e) {
			session.removeEventListener('end', onSessionEnd);
			this.dispatchEvent(new ShortHandCustomEvent(e.type, {detail: e}));
			this.session = null;
		}).bind(this));
		const xr = this.renderer.deref().object.xr;
		xr.setReferenceSpaceType(this.referenceSpaceType);
		await xr.setSession( session );
		this.baseReferenceSpace = await session.requestReferenceSpace( this.referenceSpaceType );
		xr.setReferenceSpace(this.baseReferenceSpace);
		this.el.setSession(session);
		const features = {
			optional: this.optionalFeatures,
			required: this.requiredFeatures,
			enabled: session.enabledFeatures
		};
		this.dispatchEvent(new ShortHandCustomEvent('sessionstart', {
			detail: {
				type,
				session,
				features
			}
		}));
		console.log('session started', features);
	}
	endXRSession () {
		if (this.session) {
			this.session.end();
		}
		this.session = null;
		this.el.session = null;
		this.baseReferenceSpace = null;
	}
}

Object.assign(THREE_TYPES, {SHWebXRSessionConfig});

let documentation = defaultDocumentationMessage;
documentation: {
	documentation = `This object is used to configure WebXR sessions.`;
}


const template = document.createElement('template');
template.innerHTML = html`
	<style>
		:host {
			display: none;
		}
	</style>

	<slot></slot>
`;

export const name = 'XRSession';
export const type = SHWebXRSessionConfig; // Replace with what ever THREE object this is 
/** @param {typeof HTMLElement} baseClass */
export const mixin = (baseClass) => class extends baseClass {
	static shortHandSchema = new Map([
		["dom-overlay", { as: 'domOverlay', type: "Element" }],
		["reference-space", {as: 'referenceSpaceType', type: "string[]", example: "local-floor", notes: 'other useful values might be: local and bounded-floor, see https://developer.mozilla.org/en-US/docs/Web/API/XRReferenceSpace'}],
		["optional-features", { as: 'optionalFeatures', type: "string[]", example: "hand-tracking" }],
		["required-features", { as: 'requiredFeatures', type: "string[]" }],
		["foveation", { default: 1 }],
	]);
	static shortHandEventDescriptions = {
		'sessionstart': 'Fired a WebXR session starts.',
		'end': 'Fired when a session ends.'
	};

	static name = name;

	static template=template;
	static documentation=documentation;

	#renderer;

	constructor() {
		super();
		this.detectXR();
	}

	async connectedCallback() {
		this.getRootNode().addEventListener('click', e => {
			if (e.target.dataset.action==="enter-vr") this.enterVR();
			if (e.target.dataset.action==="enter-ar") this.enterAR();
			if (e.target.dataset.action==="enter-inline") this.enterInlineXR();
			if (e.target.dataset.action==="end-xr") this.endXR();
		});
		await super.connectedCallback();
	}

	async enterVR() {
		/* start a WebXR "immersive-vr" session. */
		const object = await this.object;
		await object.enterVR();
		this.classList.add('in-vr'); 
	}

	async enterAR() {
		const object = await this.object;
		await object.enterAR();
		this.classList.add('in-ar'); 
	}

	async enterInlineXR() {
		const object = await this.object;
		await object.enterInlineXR();
		this.classList.add('in-inline-xr'); 
	}

	async endXR() {
		(await this.object).endXRSession();
		this.classList.remove('in-vr'); 
		this.classList.remove('in-ar'); 
		this.classList.remove('in-inline-xr'); 
	}

	setSession(session) {
		this.session = session;
		this.object.session = session;
		session.addEventListener('end', () => {
			this.object.session = null;
			this.endXR(this);

			this.emit('end');
		}, {once: true});

		for (const name of ["select", "selectstart", "selectend", "squeeze", "squeezeend", "squeezestart", "inputsourceschange"]) {
			session.addEventListener(name, e => {
				const evt = new CustomEvent(e.type, {detail: e});
				this.object.dispatchEvent(evt);
				this.dispatchEvent(evt);
				this.#renderer.deref().dispatchEvent(evt);
			});
		}
		if (super.setSession) super.setSession(session);
		this.emit('sessionstart', {
			session
		});
	}

	/**
	 * called when this element is used as a property
	 * @param {string} attr 
	 * @param {WeakRef<HTMLElement>} el 
	 */
	async onAssign(attr, elRef) {
		super.onAssign(attr, elRef);
		this.#renderer = elRef;
		(await this.object).setRenderer(elRef);
	}

	async detectXR() {
		if (!navigator.xr) return;
		if(await navigator.xr.isSessionSupported( 'immersive-vr' )) {
			this.classList.add('vr-supported');
		}
		if(await navigator.xr.isSessionSupported( 'immersive-ar' )) {
			this.classList.add('ar-supported');
		}
		if(await navigator.xr.isSessionSupported( 'inline' )) {
			this.classList.add('inline-xr-supported');
		}
	}

	async allAttributesChangedCallback() {
		await super.allAttributesChangedCallback(); 
		this.object.addEventListener('end', this.endXR.bind(this));
	}
};
