import { Scene, FogExp2 } from "three";

export function register (registerShortHandElement, schema) {
	const schemas = schema.schemas;

	// Create new mixins
	schemas.get(Scene).get('mixins').push(baseclass => class extends baseclass {
		static name = 'SceneFog';

		static shortHandSchema = new Map([
			// ['fog', {as: 'fog.color,fog.density', type: '<Color number>', example: '#6b6b73 0.1'}], // something like this would be cool but needs implementing
			['fog-color', { as: 'fog.color', type: 'Color' }],
			['fog-density', { as: 'fog.density', type: 'number', default: 0, example: '0.035' }],
		]);

		#fog = new FogExp2();
		assignPostConstructAttributes(object) {
			object.fog = this.#fog;
			return super.assignPostConstructAttributes(object);
		}
	});
}

