import { Matrix4, Object3D, Quaternion, Vector3 } from 'three';
import { STORED_ON_EL } from '../schema';
import { shortHandSchema } from '../utils/utils';

export const mixins = [];
export const changeOn = ['transform', 'location', 'rotate', 'scale'];
const tempQuaternion = new Quaternion();
const tempVector3 = new Vector3();
const transformCache = new WeakMap();

export function refreshTransform(el) {
	if (!el.object || el.object instanceof Promise) return;

	if (!el.object.__hasInitial) {
		el.object.__hasInitial = true;
		if (!(el.object.scale.x === 1 && el.object.scale.y === 1 && el.object.scale.z === 1)) {
			el.object.__initialScale = el.object.scale.clone();
		}
		if (el.object.position.length() > 0) {
			el.object.__initialPosition = el.object.position.clone();
		}
		if (!(el.object.quaternion.x === 0 && el.object.quaternion.y === 0 && el.object.quaternion.z === 0 && el.object.quaternion.w === 1)) {
			el.object.__initialQuaternion = el.object.quaternion.clone();
		}
	}

	if (typeof el.properties.transform === 'string') {
		transformCache.get(el).decompose(el.object.position, el.object.quaternion, el.object.scale);
	} else {
		el.object.position.set(0,0,0);
		el.object.quaternion.identity();
		el.object.scale.set(1,1,1);
	}
	if (el.postConstruct.has('quaternion')) {
		tempQuaternion.copy(el.postConstruct.get('quaternion'));
		el.object.quaternion.multiply(tempQuaternion);
	} else if (el.postConstruct.has('rotation')) {
		tempQuaternion.setFromEuler(el.postConstruct.get('rotation'));
		el.object.quaternion.multiply(tempQuaternion);
	} else if (el.object.__initialQuaternion) {
		el.object.quaternion.multiply(el.object.__initialQuaternion);
	}
	tempVector3.copy(el.object.position);
	if (el.postConstruct.has('position')) {
		tempVector3.add(el.postConstruct.get('position'));
	} else if (el.object.__initialPosition) {
		tempVector3.add(el.object.__initialPosition);
	}
	el.object.position.copy(tempVector3);

	tempVector3.copy(el.object.scale);
	if (el.postConstruct.has('scale')) {
		tempVector3.multiply(el.postConstruct.get('scale'));
	} else if (el.object.__initialScale) {
		tempVector3.multiply(el.object.__initialScale);
	}
	el.object.scale.copy(tempVector3);
}

export function register (registerShortHandElement,  schema) {
	const schemas = schema.schemas;

	schemas.get(Object3D).get('mixins').push(baseclass => class extends baseclass {
		static name = 'Transform';
		static shortHandSchema = shortHandSchema({
			mixins,
			transform: { type: 'string', stage: STORED_ON_EL }
		});
		
		constructor() {
			super();
			transformCache.set(this, new Matrix4().identity());
		}

		get #cachedDOMMatrix() {
			return transformCache.get(this);
		}

		stringToValue(attr, value) {
			if (attr === 'transform') {
				try {
					const domMatrix = new DOMMatrix(value);
					this.#cachedDOMMatrix.fromArray(domMatrix.toFloat32Array());
				} catch (e) {
					// Invaid string so ignore
				}
				if (this.object instanceof Promise) this.object.then(() => refreshTransform(this));
				else refreshTransform(this);
				return value;
			}
			return super.stringToValue(attr, value);
		}

		async connectedCallback() {
			await super.connectedCallback();
			await this.object;
			refreshTransform(this);
		}

		async attributeChangedCallback(attr, oldValue, newValue, styleAttributeChange) {
			await super.attributeChangedCallback(attr, oldValue, newValue, styleAttributeChange);
			if (changeOn.includes(attr)) {
				await this.object;
				refreshTransform(this);
			}
		}
	});
}
