import { BatchedMesh } from 'three';
import { defaultDocumentationMessage } from '../strings.js';
import { shortHandSchema } from '../utils/utils.js';
import { STORED_ON_EL, materialMap } from '../schema.js';

let documentation = defaultDocumentationMessage;
documentation: {
	documentation = `The purpose of this element is for efficiently rendering lots of objects which share a material.`;
}

export const name = 'BatchedMesh';
export const type = BatchedMesh; // Replace with what ever THREE object this is 
/** @param {typeof HTMLElement} baseClass */
export const mixin = (baseClass) => class extends baseClass {
	static shortHandSchema = shortHandSchema({
		material: { type: 'Material', map: materialMap, stage: STORED_ON_EL, default: materialMap.plastic, example: '#my-material'},
		items: { type: 'BatchedMeshItem[]', default: 'sh-mesh-batched-item', stage: STORED_ON_EL },
		geometry: undefined,
	});

	static name = name;
	static documentation=documentation; // Optional
	noGeometryBVH=true;

	constructor() {
		super();
	}

	tick(time, delta, frame, renderer, session) {
		super.tick(time, delta, frame, renderer, session);
	}

	/**
	 * This is called when an element is assigned to one of it's parameters
	 * @param {string} attr Attribute assigned to
	 * @param {HTMLElement} el element used
	 */
	objectAssigned(attr, el) {
		super.objectAssigned(attr, el);
	}

	/**
	 * called when this element is used as a property
	 * @param {string} attr 
	 * @param {WeakRef<HTMLElement>} el 
	 */
	// eslint-disable-next-line no-unused-vars
	#maxIndexCount=64;
	#geometryIndexes = new WeakMap();
	async allAttributesChangedCallback() {
		// calculate MaxGeometryCount, MaxVertexCount from assigned geometries
		// Dynamically set maxIndexCount as required but default to 64 then double as required
		let maxGeometryCount=0;
		let maxVertexCount=0;

		for (const item of this.properties.items) {
			maxGeometryCount++;
			maxVertexCount += item.requestedGeometry.attributes.position.count;
		}

		const object = new BatchedMesh(maxGeometryCount, maxVertexCount, this.#maxIndexCount, this.properties.material);

		for (const item of this.properties.items) {
			const geom = item.requestedGeometry;
			const id = object.addGeometry(geom);
			this.#geometryIndexes.set(item, id);
			item.updateMatrixWorld();
			object.setMatrixAt(id, item.matrixWorld);
		}

		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
};
