
/* jshint browser:true, esversion:11 */
import {
	Quaternion,
	Texture,
	BufferGeometry,
	Material,
	Mesh,
} from 'three';
import { STORED_ON_EL, ASSIGNED_IN_CONSTRUCTOR, REQUIRES_RECONSTRUCT, ASSIGNED_AFTER_CONSTRUCTION } from './schema.js';
import { ShortHandCustomEvent, easeOutCubic, lerp, prettyPrintElement, shortHandSchema } from './utils/utils.js';
import { schemaTypeParsing } from './schema-type-parsing.js';

/* check to see if an element has been removed and has no more references and if it has dispose of it's associated object */
const registry = new FinalizationRegistry(cleanUpObjs => {
	for (const o of cleanUpObjs) o.dispose();
});

const tempQuaternionA = new Quaternion();
const tempQuaternionB = new Quaternion();

const lerpable = ['number', 'Quaternion', 'Vector3', 'Vector2', 'Euler', 'Color'];
const attrAllowRegExp = /^(will-change|id|class|slot|part|style|data-.*|is)$/i;

export const name = 'ShortHandElement';
/**
 * @param {HTMLElement} baseClass 
 * @returns {HTMLElement}
 */
export const shortHandElement = baseClass => class ShortHandElement extends baseClass {
	static THREEClass;
	static shortHandSchema = shortHandSchema({
		mixins: [schemaTypeParsing],
		transition: { type: 'Map<string,number>', stage: STORED_ON_EL, customPropertySyntax: '*' }
	});
	static name = name;
	static canProxy = true;
	static tickPriority = 0;

	#staleAttributeRegistry = new FinalizationRegistry(attr => {
		console.log(`${attr} on ${this.tagName.toLowerCase()} references a cleaned up element.`);
		this.attributeChangedCallback(attr, this.attributes.getNamedItem(attr) || '', null);
	});
	isShortHandElement=true;
	ready = false;
	object;
	#toCleanUp;
	#promiseCache = new Map();
	#connectedPromise;
	#connectedResolver;
	#objectResolver;
	#waitingForBuild;
	#waitingForPost;
	#awaitingAllAttributesChanged;
	#hasAllAttributesPromise;
	#hasAllAttributesResolver;
	#onConstruct = {};
	postConstruct = new Map();
	constructorArguments = [];
	#t = {};
	#tEase = {};
	#transitionTargets = {};
	properties = {};
	constructor() {
		super();

		const refs = new Proxy(
			{},
			{ get: (o, ref)=>this.shadowRoot.querySelector(`[ref="${ref}"]`) }
		);
		Object.defineProperty(this, 'refs', {
			get() {return refs;}
		});

		this.object = new Promise(resolve => this.#objectResolver = resolve);
		this.#connectedPromise = new Promise(resolve => this.#connectedResolver = resolve);
		this.#hasAllAttributesPromise = new Promise(resolve => this.#hasAllAttributesResolver = resolve);

		this.#waitingForBuild = new Set();
		this.#waitingForPost = new Set();

		setTimeout(() => {
			if (this.#waitingForBuild.size) {
				console.log(`After 4 seconds, ${prettyPrintElement(this)} still has ${Array.from(this.#waitingForBuild).join(', ')} undefined so it cannot be used.`);
				console.log(this);
			} 
		}, 4000);

		this.#addShadowDOM();

		for (const attr of this.constructor.shortHandAttributes) {
			const defaultValue = this.constructor.defaultAttributeValue(attr);
			const schema = this.constructor.shortHandSchema.get(attr);
			const {stage, constructorArgument} = this.#parseSchema(attr);
			if (defaultValue === undefined && typeof constructorArgument === 'number') {
				this.#waitingForBuild.add(attr);
			}

			let attributeValue = this.attributes.getNamedItem(attr)?.value;
			if (attributeValue === 'none' && typeof schema?.map?.none === "undefined") attributeValue = null;
			if (attributeValue) {
				if (stage & ASSIGNED_AFTER_CONSTRUCTION) {
					this.#waitingForPost.add(attr);
				} else {
					this.#waitingForBuild.add(attr);
				}
			}
			if (defaultValue !== undefined) {
				let parsedDefaultValue = this.stringToValue(attr, defaultValue);
				if (!(parsedDefaultValue instanceof Promise)) {
					this.populateConstructorHelper(attr, parsedDefaultValue, true);
				}
			}
		}
		if (!this.constructor.noWarnForUnrecognisedAttributes) for (const {name:attr} of this.attributes) {
			if (!this.constructor.shortHandSchema.has(attr) && !attr.match(attrAllowRegExp) && !(attr in this)) {
				console.warn(`${prettyPrintElement(this)} Unrecognised attribute: "${attr}"`);
			}
		}
	}

	#addShadowDOM() {
		if (this.constructor.template) {
			this.attachShadow({mode: 'open'});
			this.shadowRoot.appendChild(document.importNode(this.constructor.template.content, true));
		}
	}

	// There are 3 places to set properties as constructor arguments,
	// as properties on a construction object (default)
	// and as properties on the constructed object this assigns them to the correct helper
	#constructorHelperSymbolStore = new Map();
	populateConstructorHelper(attr, value, thisIsJustTheDefaultValue) {
		this.#constructorHelperSymbolStore.set(attr, Symbol('Property updated'));
		const schemaEntry = this.constructor.shortHandSchema.get(attr);
		const property = schemaEntry.as || attr;
		const multipartAs = schemaEntry.multipartAs;
		const stage = this.constructor.shortHandSchema.get(attr).stage || ASSIGNED_IN_CONSTRUCTOR;
		const constructorArgument = this.constructor.shortHandSchema.get(attr).constructorArgument;
		
		if (!thisIsJustTheDefaultValue) {
			this.#waitingForBuild.delete(attr);
			this.#waitingForPost.delete(attr);
		}

		// If it's assigned as an argument in the constructor
		if (typeof constructorArgument === 'number') {
			this.constructorArguments[constructorArgument] = value;

			if (!(REQUIRES_RECONSTRUCT & stage)) {
				this.postConstruct.set(multipartAs || property, value);
			}

		// if it's assigned in the constructor set that value
		} else if (ASSIGNED_IN_CONSTRUCTOR & stage) {
			if (!multipartAs) {
				this.#onConstruct[property] = value;
			}

			if (!(REQUIRES_RECONSTRUCT & stage)) {
				this.postConstruct.set(multipartAs || property, value);
			}

		// If it's stored on the element set it there
		} else if (STORED_ON_EL & stage) {
			this.properties[property] = value;

		// It's set after construction so store it to be set there
		} else if (ASSIGNED_AFTER_CONSTRUCTION & stage) {
			this.postConstruct.set(multipartAs || property, value);
		}
	}
	
	// eslint-disable-next-line no-unused-vars
	tick(time, delta, frame, renderer, session){
		for (const name in this.#transitionTargets) {
			const [object, property, oldValue, newValue, type] = this.#transitionTargets[name];
			const easeDuration = this.properties.transition.get(name);
			const tOld = this.#t[name];
			if (easeDuration) {
				if (tOld < 1) {
					const d = delta/easeDuration;
					const t = Math.min(1, tOld + d); // linear
					const tEase = easeOutCubic(t);
					this.#t[name] = t;
					this.#tEase[name] = tEase;
				}
			} else {
				this.#t[name] = 1;
				this.#tEase[name] = 1;
			}
			if (this.#tEase[name] >= 1) {
				this.#tEase[name] = 1;
				delete this.#transitionTargets[name];
			}
			if (lerpable.includes(type)) {
				switch (type) {
				case 'number':
					object[property] = lerp(oldValue, newValue, this.#tEase[name]);
					break;
				case 'Quaternion':
					object[property].slerpQuaternions(oldValue, newValue, this.#tEase[name]);
					break;
				case 'Euler':
					tempQuaternionA.setFromEuler(oldValue);
					tempQuaternionB.setFromEuler(newValue);
					tempQuaternionA.slerp(tempQuaternionB, this.#tEase[name]);
					object[property].setFromQuaternion(tempQuaternionA, object[property].order);
					break;
				case 'Vector3':
				case 'Vector2':
					object[property].lerpVectors(oldValue, newValue, this.#tEase[name]);
					break;
				case 'Color':
					object[property].lerpColors(oldValue, newValue, this.#tEase[name]);
					break;
				}
			}
		}
	}

	async connectedCallback() {

		// No attributes so update attribute never called.
		// So fire this anyway.
		if (!this.ready && !this.#awaitingAllAttributesChanged && this.#waitingForPost.size === 0 && this.#waitingForBuild.size === 0) {
			this.#awaitingAllAttributesChanged = true;
			this.#hasAllAttributesResolver();
			await this.allAttributesChangedCallback();
			this.#awaitingAllAttributesChanged = false;
			this.ready = true;
		}

		this.#connectedResolver();

		if (this.#waitingForPost.size === 0 && this.#waitingForBuild.size === 0) {
			this.#hasAllAttributesResolver();
		}
	}

	async disconnectedCallback () {
		this.#connectedPromise = new Promise(resolve => this.#connectedResolver = resolve);
	}

	static defaultAttributeValue (name) {
		const schema = this.getSchemaEntry(name);
		if (typeof schema.default !== 'undefined') {
			return schema.default;
		}
	}

	async attributeChangedCallback(attr, oldValue, newValue) {
		// if nothing changes then do nothing.
		if (oldValue === newValue) return;

		const schema = this.constructor.shortHandSchema.get(attr);
		const {stage, property, needsUpdate} = this.#parseSchema(attr, newValue);
		newValue = newValue || null;

		if (newValue === 'none' && typeof schema?.map?.none === "undefined") newValue = null;

		// If attributes are changed in between it being constructed and added to then add them to the list
		if (!this.ready
			&& oldValue === null &&
			newValue !== null
		) {
			if (stage & ASSIGNED_AFTER_CONSTRUCTION) {
				this.#waitingForPost.add(attr);
			} else {
				this.#waitingForBuild.add(attr);
			}
		}
		const symbol = Symbol('Intention to update ' + attr);
		this.#constructorHelperSymbolStore.set(attr, symbol);

		await this.#connectedPromise;

		if (newValue === null) newValue = this.constructor.defaultAttributeValue(attr);
		
		// The value has been removed and there is no default value so bail
		if (newValue === undefined) return;

		let parsedOldValue;
		const type = schema.type || typeof schema.default;
		if (attr && this.properties.transition && this.properties.transition.has(attr) && lerpable.includes(type)) {
			let object = STORED_ON_EL & stage ? this.properties : this.object;
			let oldPropertyValue;
			if (this.#transitionTargets[attr]) {
				oldPropertyValue =  this.#transitionTargets[attr][3];
			} else {
				if (property.includes('.')) {
					const path = property.split('.');
					while (object && path.length > 1) {
						object = object[path.shift()];
					}
					if (object) {
						oldPropertyValue = object[path.pop()];
					}
				} else {
					oldPropertyValue = object[property];
				}
			}
			parsedOldValue = oldPropertyValue?.clone ? oldPropertyValue.clone() : oldPropertyValue;
		}

		let value = this.stringToValue(attr, newValue);
		
		if (value instanceof Promise) {
			this.#promiseCache.set(attr, value);
			const result = await value;
			if (this.#promiseCache.get(attr) === value) {
				value = result;
			} else {
				// This was invalidated before it could resolve
				return;
			}
		} else {
			this.#promiseCache.set(attr, null);
		}

		// The value can be undefined here if it was trying to find an element and none matched
		if (typeof value !== 'undefined') {
			if (this.#constructorHelperSymbolStore.get(attr) === symbol) {
				this.populateConstructorHelper(attr, value);
			}
		}
		this.#waitingForBuild.delete(attr);
		this.#waitingForPost.delete(attr);

		if (this.#waitingForPost.size === 0 && this.#waitingForBuild.size === 0) {
			this.#hasAllAttributesResolver();
		}

		if (this.ready && typeof value !== 'undefined') {

			// If a rebuild is needed then trigger rebuild
			if (stage & REQUIRES_RECONSTRUCT) {
				// Trigger a rebuild of the constructor
				this.ready = false;
				if (
					!(this.object instanceof Promise) &&
					(typeof this.object.dispose === "function")
				) {
					this.object.dispose();
				}
				this.object = new Promise(resolve => this.#objectResolver = resolve);
			} else {

				// if it's assigned in the constructor set that value
				if (STORED_ON_EL & stage) {
					const oldValue = this.properties[property];
					if (typeof oldValue.dispose === 'function' && !oldValue.el) {
						oldValue.dispose();
					}
					const type = schema.type || typeof schema.default;
					if ((parsedOldValue !== undefined) && this.properties.transition && this.properties.transition.has(attr) && lerpable.includes(type)) {
						const object = this.properties;
						this.#transitionTargets[attr] = [object, property, parsedOldValue, value.clone ? value.clone() : value, type];
						this.#t[attr] = 0;
						this.#tEase[attr] = 0;
					} else {
						this.properties[property] = value;
					}
				} else {
					const object = await this.object;
					const multipartAs = schema.multipartAs;
					let o=object;
					if (multipartAs) for (let i=0, l=multipartAs.length; i<l; i++) {
						if (i===l-1) this.#updateProperty(o, multipartAs[i], parsedOldValue, value, needsUpdate, attr, schema);
						else o = o[multipartAs[i]];
					}
					else this.#updateProperty(object, property, parsedOldValue, value, needsUpdate, attr, schema);
				}
			}
		}
		
		if (!this.ready && !this.#awaitingAllAttributesChanged && this.#waitingForBuild.size === 0) {
			try {
				this.#awaitingAllAttributesChanged = true;
				await this.allAttributesChangedCallback();
				this.#awaitingAllAttributesChanged = false;
				this.ready = true;
			} catch (e) {
				console.error(prettyPrintElement(this), e);
			}
		}
	}

	#updateProperty(object, property, parsedOldValue, value, needsUpdate, attr, schema) {
		const type = attr ? schema.type || typeof schema.default : undefined;
		if (
			(object[property] !== null && typeof object[property] === "object") && typeof object[property].copy === 'function' &&
			!(value instanceof Texture || object[property] instanceof Texture) &&
			!(value instanceof BufferGeometry || object[property] instanceof BufferGeometry) &&
			!(value instanceof Material || object[property] instanceof Material) &&
			!(value instanceof Mesh || object[property] instanceof Mesh)
		) {
			if (attr && (parsedOldValue !== undefined) && this.properties.transition && this.properties.transition.has(attr) && lerpable.includes(type)) {
				this.#transitionTargets[attr] = [object, property, parsedOldValue, value.clone(), (schema.type || typeof schema.default)];
				this.#t[attr] = 0;
				this.#tEase[attr] = 0;
			} else {
				object[property].copy(value);
			}
		} else {
			if (attr && (parsedOldValue !== undefined) && this.properties.transition && this.properties.transition.has(attr) && lerpable.includes(type)) {
				this.#transitionTargets[attr] = [object, property, parsedOldValue, value, (schema.type || typeof schema.default)];
				this.#t[attr] = 0;
				this.#tEase[attr] = 0;
			} else {
				object[property] = value;
			}
		}
		if (needsUpdate) object.needsUpdate = true;
	}

	static getSchemaEntry(name) {
		return this.shortHandSchema.get(name);
	}

	#parseSchema (attr) {
		const schemaEntry = this.constructor.getSchemaEntry(attr);

		const property = schemaEntry.as || attr;

		const needsUpdate = schemaEntry.needsUpdate === true;

		// By default properties are assigned in constructor but can then be hot changed later
		const stage = this.constructor.shortHandSchema.get(attr).stage || ASSIGNED_IN_CONSTRUCTOR;
		const constructorArgument = this.constructor.shortHandSchema.get(attr).constructorArgument;

		return {
			stage,
			constructorArgument,
			property,
			needsUpdate
		};
	}

	// This gets called each time an attribute is changed the first time
	async allAttributesChangedCallback() {

		let object;
		if (this.constructorArguments.length) {
			object = new this.constructor.THREEClass(...this.constructorArguments);
		} else {
			object = new this.constructor.THREEClass(this.#onConstruct);
		}

		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}

	async assignPostConstructAttributes(object) {
		await this.#hasAllAttributesPromise;
		for (const [property, value] of this.postConstruct.entries()) {
			if (typeof value !== 'undefined') {
				if (property instanceof Array) {
					let o=object;
					for (let i=0, l=property.length; i<l; i++) {
						if (i===l-1) this.#updateProperty(o, property[i], null, value);
						else o = o[property[i]];
					}
				} else {
					this.#updateProperty(object, property, null, value);
				}
			}
		}
	}

	/**
	 * Sets el on the object
	 * Cleans up previously existing objects
	 * Sets this.object to that object
	 * 
	 * @param {any} 
	 * @param  {...Function} additionalDisposalObjects 
	 */
	updateObject(object, ...additionalDisposalObjects) {

		// Clean up the previous object
		if (typeof this.#toCleanUp !== 'undefined') {
			for (const o of this.#toCleanUp) o.dispose();
		}

		if (this.id && Object.prototype.hasOwnProperty.call(object, 'name') && !object.name) {
			object.name = this.id;
		}

		const el = new WeakRef(this);
		Object.defineProperty(object, 'el', { get () { return el.deref(); }, configurable: true });
		object.self = object;
		this.#objectResolver(object);
		this.object = object;

		const disposals = additionalDisposalObjects;
		this.#toCleanUp = disposals;
		if (typeof object.dispose === "function") {
			disposals.push(object);
		}
		registry.register(this, disposals);
	}

	emit(name, detail, bubbles=true, suppressWarnings = false, cancelable = false) {
		if (!suppressWarnings && !(this.constructor?.shortHandEventNames?.has(name))) {
			console.warn(`${prettyPrintElement(this)} fired event "${name}" but it is not documented from any mixin.`);
		}
		const event = new ShortHandCustomEvent(name, Object.assign({detail}, {bubbles, composed: true, cancelable}));
		this.dispatchEvent(event);
		return event;
	}

	/**
	 * This is called when an element is assigned to one of it's parameters
	 * @param {string} attr Attribute assigned to
	 * @param {HTMLElement} el element used
	 */
	objectAssigned(attr, el) {
		const registry = this.#staleAttributeRegistry;
		registry.register(el, attr);
	}

	/**
	 * called when this element is used as a property
	 * @param {string} attr 
	 * @param {WeakRef<HTMLElement>} el 
	 */
	// eslint-disable-next-line no-unused-vars
	onAssign(attr, el) {}


	/**
	 * Gets replaced in schema-type-parsing.js
	 * @param {string} attr 
	 * @param {WeakRef<HTMLElement>} el 
	 */
	// eslint-disable-next-line no-unused-vars
	stringToValue(attr, value) {}
};
