import { Object3D, Vector3 } from 'three';
import { defaultDocumentationMessage } from '../strings.js';
import { shortHandSchema } from '../utils/utils.js';

let documentation = defaultDocumentationMessage;
documentation: {

	// Add any documentation for the README in here perhaps describe what attributes are optional
	// or how to use it.
	documentation = `plane-constraint is designed to place the element it's attached to 
as close as possible to the target element whilst being restrained along a plane
defined by the \`y-axis\` of the element.`;
}

export function register (registerShortHandElement,  schema) {
	const schemas = schema.schemas;
	const tempVector3A = new Vector3();
	const tempVector3B = new Vector3();
	const normal = new Vector3();
	const defaultLimits = [-1, -1, 0];
	const defaultStep = new Vector3();
	schemas.get(Object3D).get('mixins').push(baseclass => class extends baseclass {
		static shortHandSchema = shortHandSchema({
			'plane-constraint-target': { as: 'planeConstraintTarget', type: 'Elements', default: [], stage: schema.STORED_ON_EL },
			'plane-constraint-limit': { as: 'planeConstraintLimit', type: 'string', stage: schema.STORED_ON_EL, notes: "Format: Radius limit, Height Limit, Out of range behaviour (One of stop, follow, origin), negative values count as no-limit. " },
			'plane-constraint-step': { as: 'planeConstraintStep', type: 'Vector3', stage: schema.STORED_ON_EL },
			'plane-constraint-latch': {as: 'planeConstraintLatch', type: 'boolean', stage: schema.STORED_ON_EL, notes: 'whether to stay attached to the current element even if another is closer.'}
		});
		static name = 'PlaneConstraint';
		static documentation=documentation;

		#originalOffset;

		#isActive = null;
		#currentTarget = null;
		#markActive(el) {
			if (this.#isActive !== true) {
				this.#currentTarget = el;
				this.#isActive = true;
				if (this.getRootNode().host) this.part.add('plane-constraint-active');
				this.classList.add('plane-constraint-active');
			}
		}

		#markInactive() {
			if (this.#isActive !== false) {
				this.#currentTarget = null;
				this.#isActive = false;
				if (this.getRootNode().host) this.part.remove('plane-constraint-active');
				this.classList.remove('plane-constraint-active');
			}
		}

		stringToValue(attr, value) {
			// parse linear-constraint-options
			if (attr === 'plane-constraint-limit') {
				if (!value) return null;
				const parse = value.trim().match(/^([-\d.]+)?(?:\s+([-\d.]+))?(?:\s+(stop|follow|origin))?$/);
				if (!parse) {
					return null;
				} else {
					let type = 0; // stop
					if (parse[3] === 'stop') type = 0;
					if (parse[3] === 'follow') type = 1;
					if (parse[3] === 'origin') type = 2;

					let height = parse[2] ? parseFloat(parse[2]) : -1;
					return [parseFloat(parse[1]), height, type];
				}
			} else {
				return super.stringToValue(attr, value);
			}
		}
	
		tick(time, delta, frame, renderer, session) {
			super.tick(time, delta, frame, renderer, session);
			const object = this.object;
			if (
				!object || object instanceof Promise ||
				!this.properties.planeConstraintTarget ||
				this.properties.planeConstraintTarget.length === 0
			) return this.#markInactive();

			if (!this.#originalOffset) this.#originalOffset = new Vector3().copy(object.position);

			const n = normal.set(0,1,0);
			const p0 = tempVector3A;
			const [radius, height, type] = this.properties.planeConstraintLimit || defaultLimits;
			const step = this.properties.planeConstraintStep || defaultStep;
			let targetEl;

			// For the case of multiple targets pick the closest point.
			let closestD = Infinity;
			const testPoint = tempVector3B;
			if (
				this.properties.planeConstraintLatch === true &&
				this.#currentTarget &&
				this.properties.planeConstraintTarget.includes(this.#currentTarget)
			) {
				const target = this.#currentTarget;
				if (target.parent && target.parent === object.parent) {
					testPoint.copy(target.object.position);
				} else {
					target.object.getWorldPosition(testPoint);
					object.parent.worldToLocal(testPoint);
				}
				testPoint.sub(this.#originalOffset);
				p0.copy(testPoint);
				targetEl = target;
			} else {
				for (const target of this.properties.planeConstraintTarget) {
					if (target.object instanceof Object3D) {
						if (target.parent && target.parent === object.parent) {
							testPoint.copy(target.object.position);
						} else {
							target.object.getWorldPosition(testPoint);
							object.parent.worldToLocal(testPoint);
						}
						testPoint.sub(this.#originalOffset);
						const distance = testPoint.length();
						if (distance < closestD) {
							closestD = distance;
							p0.copy(testPoint);
							targetEl = target;
						}
					}
				}
			}

			if (step.x) p0.x = step.x * Math.round( p0.x / step.x);
			if (step.y) p0.y = step.y * Math.round( p0.y / step.y);
			if (step.z) p0.z = step.z * Math.round( p0.z / step.z);

			let t = p0.dot(n);
			const r = p0.addScaledVector(n ,-t).length();
			const outOfRadius = radius > 0 && r > radius;
			const outOfHeight = height > 0 && Math.abs(t) > (height - this.#originalOffset.y);

			if (outOfRadius || outOfHeight) {
				if (type === 0) return this.#markInactive();
				if (type === 1) {
					this.#markActive(targetEl);
					if (outOfRadius) p0.multiplyScalar(radius/r);
				}
				if (type === 2) {
					this.#markInactive();
					p0.set(0,0,0);
				}
			} else {
				this.#markActive(targetEl);
			}

			object.position.copy(p0).add(this.#originalOffset);
		}
	});
}

