import { Color, Material, ShaderMaterial, UniformsLib } from "three";
import { shortHandSchema } from "../utils/utils";
import { Mesh } from "three";
import { Vector2 } from "three";


const vertexShader = `
#include <common>
#include <shadowmap_pars_vertex>
#include <color_pars_vertex>
#include <fog_pars_vertex>

varying vec3 vNormal;
varying vec3 vFaceNormal;
varying vec3 vViewDir;
varying vec4 myObjectPosition;
varying vec2 vUv;

#ifdef USE_SHADOWMAP
#else
varying vec4 vDirectionalShadowCoord[1];
#endif

void main() {
    #include <beginnormal_vertex>
    #include <defaultnormal_vertex>

    #include <begin_vertex>

    #include <worldpos_vertex>
    #include <shadowmap_vertex>
    #include <color_vertex>

	vec4 mvPosition = vec4(position, 1.0 );

	#ifdef USE_INSTANCING
		mvPosition = instanceMatrix * vec4(position, 1.);
	#endif

	myObjectPosition = mvPosition;
    vec4 viewPosition = modelViewMatrix * mvPosition;
    vec4 clipPosition = projectionMatrix * viewPosition;

    vNormal = normalize(normalMatrix * normal);
	vFaceNormal = vec3(normal);

	#ifdef USE_INSTANCING
		// this is in lieu of a per-instance normal-matrix
		// shear transforms in the instance matrix are not supported
		mat3 m1 = mat3( instanceMatrix );
		vNormal /= vec3( dot( m1[ 0 ], m1[ 0 ] ), dot( m1[ 1 ], m1[ 1 ] ), dot( m1[ 2 ], m1[ 2 ] ) );
		vNormal = m1 * vNormal;
	#endif

    vViewDir = normalize(-viewPosition.xyz);

	vUv = vec3( uv, 1 ).xy;

    gl_Position = clipPosition;

	#include <fog_vertex>
}
`;

const fragmentShader = `
#define USE_SHADOWMAP
#include <common>
#include <packing>
#include <lights_pars_begin>
#include <shadowmap_pars_fragment>
#include <shadowmask_pars_fragment>
#include <color_pars_fragment>
#include <fog_pars_fragment>
#include <dithering_pars_fragment>

uniform vec3 colorU;
uniform float glossiness;
uniform float rimThreshold;
uniform float points;
uniform float ditherRate;
uniform vec2 ssSize;
uniform bool objectSpace;
uniform int mode;
uniform mat4 modelViewMatrix;
uniform mat4 projectionMatrix;

vec2 rotate(vec2 v, float a) {
	float s = sin(a);
	float c = cos(a);
	mat2 m = mat2(c, -s, s, c);
	return m * v;
}

varying vec3 vNormal;
varying vec3 vFaceNormal;
varying vec3 vViewDir;
varying vec4 myObjectPosition;
varying vec2 vUv;
const float dithers[72] = float[72](0.0, 48.0, 12.0, 60.0, 3.0, 51.0, 15.0, 61.0, 32.0, 16.0, 44.0, 28.0, 35.0, 19.0, 47.0, 31.0, 8.0, 56.0, 4.0, 52.0, 11.0, 59.0, 7.0, 55.0, 40.0, 24.0, 36.0, 20.0, 43.0, 27.0, 39.0, 23.0, 2.0, 50.0, 14.0, 62.0, 1.0, 49.0, 13.0, 61.0, 34.0, 18.0, 46.0, 30.0, 33.0, 17.0, 45.0, 29.0, 10.0, 58.0, 6.0, 54.0, 9.0, 57.0, 5.0, 53.0, 42.0, 26.0, 38.0, 22.0, 41.0, 25.0, 37.0, 21.0, 0.0, 48.0, 12.0, 60.0, 3.0, 51.0, 15.0, 61.0);
const float hatch[32] = float[32](${new Array(32).fill(1).map((v,i) => i*3).sort(()=>Math.random()-0.5).map(v=>v.toFixed(1)).toString()});
void main() {
	vec4 diffuseColor = vec4(colorU, 1.0);
	#include <color_fragment>


	// shadow map
	DirectionalLightShadow directionalShadow = directionalLightShadows[0];
	
	float shadow = 1.0;
	#if defined( USE_SHADOWMAP )
	shadow = getShadow(
		directionalShadowMap[0],
		directionalShadow.shadowMapSize,
		directionalShadow.shadowBias,
		directionalShadow.shadowRadius,
		vDirectionalShadowCoord[0]
	);
	#endif

	// directional light
	float NdotL = dot(vNormal, directionalLights[0].direction);
	float lightIntensity = floor(smoothstep(0.0, 0.8, NdotL) * 4.) * 0.25 * mix(shadow, 1., 0.5);
	vec3 directionalLight = directionalLights[0].color * lightIntensity;

	// specular reflection
	vec3 halfVector = normalize(directionalLights[0].direction + vViewDir);
	float NdotH = dot(vNormal, halfVector);

	float specularIntensity = pow(NdotH * lightIntensity, 1000.0 / glossiness);
	float specularIntensitySmooth = smoothstep(0.0, 0.6, specularIntensity);

	vec3 specular = specularIntensitySmooth * directionalLights[0].color;

	// rim lighting
	float rimDot = 1.0 - dot(vViewDir, vNormal);

	float rimAmount = 0.6;
	// float rimThreshold = 0.2;
	float rimIntensity = rimDot * pow(NdotL, rimThreshold);
	rimIntensity = smoothstep(rimAmount - 0.01, rimAmount + 0.01, rimIntensity);

	vec3 rim = rimIntensity * directionalLights[0].color;

	vec3 lightTotal = (ambientLightColor + directionalLight + specular + rim) * 0.33;
	vec2 rMyObjectPosition;

	float isLines = float(mode==1||mode==2);
	float sampleWidth = 8. + isLines * 24.;

	float aX = abs(vFaceNormal.x);
	float aY = abs(vFaceNormal.y);
	float aZ = abs(vFaceNormal.z);
	float max = max(max(aX, aY),aZ);
	if (max == aX) rMyObjectPosition = myObjectPosition.yz;
	if (max == aY) rMyObjectPosition = myObjectPosition.xz;
	if (max == aZ) rMyObjectPosition = myObjectPosition.xy;
	
	rMyObjectPosition = rotate(rMyObjectPosition,isLines*PI*0.33);
	vec2 newUV;
	if (mode == 3) {
		vec4 viewPosition = modelViewMatrix * myObjectPosition;
		vec4 clipPosition = projectionMatrix * viewPosition;
		vec2 ss = clipPosition.xy * 0.5 + .5;
		newUV = mod(ss * ssSize * points*0.01, sampleWidth);
	} else {
		newUV = objectSpace ? mod(rMyObjectPosition * points, sampleWidth) : mod(rotate(vUv,isLines*PI*0.33) * points, sampleWidth);
	}
	int x = int(newUV.x);
	int y = int(newUV.y);

	float weight;
	float dither;
	if (mode == 0 || mode == 3) {
		weight = smoothstep(0. , 0.7, 1.-clamp(length(mod(newUV, 1.) - 0.5)*1.8, 0., 1.));
		int index = (x * 8) + y;
		dither = ditherRate * (dithers[index] / 64.0);
	}
	if (mode == 1) {
		weight = float(dithers[y+x] < hatch[x]) * smoothstep(0.5 , 1.0, pow(2. * (0.5 - abs(0.5 - mod(newUV.x, 1.))), 2.));
		dither = ditherRate * (hatch[x] / 64.0);
	}
	if (mode == 2) {
		weight = float(dithers[x] < hatch[x]) * smoothstep(0.5 , 1.0, pow(2. * (0.5 - abs(0.5 - mod(newUV.y, 1.))), 2.)) +
			float(dithers[y+x] < hatch[y]) * smoothstep(0.5 , 1.0, pow(2. * (0.5 - abs(0.5 - mod(newUV.x, 1.))), 2.));
		dither = ditherRate * ((hatch[x] + hatch[y]) / 128.0);
	}

	float grey = 0.2126 * lightTotal.r + 0.7152 * lightTotal.g + 0.0722 * lightTotal.b;
	grey = grey / 0.039;
	grey = floor(grey + 0.5);
	grey = grey * 0.039;
	grey = grey * 1.5;

	gl_FragColor = vec4(
		mix(
			diffuseColor.rgb * (mix(
					lightTotal*0.7 + 0.3,
					lightTotal*0.6 + 0.1,
					float((grey * length(diffuseColor.rgb)) < dither) * weight
				)
			),
			directionalLights[0].color,
			clamp(length(rim) + length(specular),0.,1.)
		)
	, diffuseColor.a);

	gl_FragColor.rgb = toneMapping( gl_FragColor.rgb );

	#include <fog_fragment>
	#include <dithering_fragment>
}
`;

export const name = 'GraphicToonShader';
export const type = Material;
/** @param {typeof HTMLElement} baseClass */
export const mixin = (baseClass) => class extends baseClass {
	static name = name;

	static shortHandSchema = shortHandSchema({
		mixins: [],
		glossiness: {default: 4},
		"rim-threshold": {as: "uniforms.rimThreshold.value", default: 0.2},
		"object-space-points": {as: 'uniforms.objectSpace.value', default: false},
		points: {as: 'uniforms.points.value', default: 75},
		color: {as: 'uniforms.colorU.value', type: 'Color', default: 'white'},
		"dither-rate": {as: 'uniforms.ditherRate.value', default: 1.3},
		mode: {as:'uniforms.mode.value', type:'number', default: 'hatching', map: {
			dots: 0,
			hatching: 1,
			'cross-hatching': 2,
			ssdots: 3
		} }
	});

	async attributeChangedCallback(attr, oldValue, newValue, fromStyleChange) {
		await super.attributeChangedCallback(attr, oldValue, newValue, fromStyleChange);
	}

	#oldMesh;
	#oldOnBeforeRender;
	async onAssign(attr, elRef) {
		if (this.#oldMesh) this.#oldMesh.onBeforeRender = this.#oldOnBeforeRender;
		const mesh = await elRef.deref().object;

		if (mesh instanceof Mesh) {
			this.#oldOnBeforeRender = mesh.onBeforeRender;
			this.#oldMesh = mesh;
			mesh.onBeforeRender = renderer => renderer.getSize(this.object.uniforms.ssSize.value);
		}
	}

	async allAttributesChangedCallback() { 

		const object = new ShaderMaterial({
			lights: true,
			vertexColors: true,
			fog: true,
			uniforms: { ...UniformsLib.lights,
				colorU: { value: new Color('white') },
				glossiness: { value: 0 },
				rimThreshold: { value: 0 },
				points: { value: 0 },
				ditherRate: { value: 0 },
				mode: { value: 0 },
				objectSpace: { value: false },
				fogColor: {value: new Color('white')},
				fogDensity: { value: 0 },
				ssSize: { value: new Vector2(100, 100) },
			},
			vertexShader,
			fragmentShader
		});

		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
};
