import { Vector2 } from "three";

// Adapted from https://github.com/gilmoreorless/css-background-parser/blob/master/index.js (MIT LICENSE)
class Background {
	constructor (props) {
		props = props || {};
		const bg = this;

		function defprop(name, defaultValue) {
			bg[name] = (name in props) ? props[name] : defaultValue;
		}

		// http://www.w3.org/TR/css3-background/#backgrounds
		defprop('color', '');
		defprop('image', 'none');
		defprop('attachment', 'scroll');
		defprop('clip', 'border-box');
		defprop('origin', 'padding-box');
		defprop('position', '0% 0%');
		defprop('repeat', 'repeat');
		defprop('size', 'auto');
	}

	toString () {
		const list = [
			this.image,
			this.repeat,
			this.attachment,
			this.position + ' / ' + this.size,
			this.origin,
			this.clip
		];
		if (this.color) {
			list.unshift(this.color);
		}
		return list.join(' ');
	}
}

function parseImages(cssText) {
	const images = [];
	const tokens = /[,()]/;
	let parens = 0;
	let buffer = '';

	if (cssText == null) {
		return images;
	}

	while (cssText.length) {
		const match = tokens.exec(cssText);
		if (!match) {
			break;
		}
		const char = match[0];
		let ignoreChar = false;
		switch (char) {
		case ',':
			if (!parens) {
				images.push(buffer.trim());
				buffer = '';
				ignoreChar = true;
			}
			break;
		case '(':
			parens++;
			break;
		case ')':
			parens--;
			break;
		}

		const index = match.index + 1;
		buffer += cssText.slice(0, ignoreChar ? index - 1 : index);
		cssText = cssText.slice(index);
	}

	if (buffer.length || cssText.length) {
		images.push((buffer + cssText).trim());
	}

	return images;
}

// Helper for .map()
function trim(str) {
	return str.trim();
}

function parseSimpleList(cssText) {
	return (cssText || '').split(',').map(trim);
}

const parseElementStyle = function (styleObject) {
	const list = [];
	if (styleObject == null) {
		return list;
	}

	const bgImage = parseImages(styleObject.backgroundImage);
	const bgColor = styleObject.backgroundColor;
	const bgAttachment = parseSimpleList(styleObject.backgroundAttachment);
	const bgClip       = parseSimpleList(styleObject.backgroundClip);
	const bgOrigin     = parseSimpleList(styleObject.backgroundOrigin);
	const bgPosition   = parseSimpleList(styleObject.backgroundPosition);
	const bgRepeat     = parseSimpleList(styleObject.backgroundRepeat);
	const bgSize       = parseSimpleList(styleObject.backgroundSize);
	let background;

	for (let i = 0, ii = bgImage.length; i < ii; i++) {
		background = new Background({
			image:      bgImage[i],
			attachment: bgAttachment[i % bgAttachment.length],
			clip:       bgClip[i % bgClip.length],
			origin:     bgOrigin[i % bgOrigin.length],
			position:   bgPosition[i % bgPosition.length],
			repeat:     bgRepeat[i % bgRepeat.length],
			size:       bgSize[i % bgSize.length]
		});
		if (i === ii - 1) {
			background.color = bgColor;
		}
		list.push(background);
	}

	return list;
};

/**
 * Turns a string number into a length in pixels
 * @param {string} number 
 * @param {string} unit 
 * @param {number} canvasWidth 
 * @param {number} canvasHeight 
 * @param {number} hundredPercent 
 * @returns {number} Size in pixels
 */
function parseLength(number, unit, canvasWidth, canvasHeight, hundredPercent) {
	if (unit === '%') return hundredPercent * parseFloat(number) * 0.01;
	if (unit === 'vw') return canvasWidth * parseFloat(number) * 0.01;
	if (unit === 'vh') return canvasHeight * parseFloat(number) * 0.01;
	if (unit === 'vmax') return Math.max(canvasWidth, canvasHeight) * parseFloat(number) * 0.01;
	if (unit === 'vmin') return Math.min(canvasWidth, canvasHeight) * parseFloat(number) * 0.01;
	if (unit === 'em' || unit === 'rem' || unit === 'cap' || unit === 'ch' || unit === 'ex' || unit === 'ic' || unit === 'lh') return parseFloat(number) * 16;
	if (unit === 'px') return parseFloat(number);
}

const div = document.createElement('div');
div.style.display = 'none';
const divStyles = window.getComputedStyle(div); 
function getBackgrounds(string) {
	document.body.appendChild(div);
	div.style.background = string;
	const styles = parseElementStyle(divStyles);
	document.body.removeChild(div);
	return styles;
}

const tileCanvas = document.createElement('canvas');
function parseSize(sizeString, canvasWidth, canvasHeight, target, intrinsicWidth=canvasWidth, intrinsicHeight=canvasHeight) {
	if(sizeString === 'auto') {
		target.width = intrinsicWidth;
		target.height = canvasHeight;
		return;
	}

	if (sizeString === 'contain') {
		if (intrinsicWidth < intrinsicHeight) {
			target.width = intrinsicWidth;
			target.height = canvasHeight;
		} else {
			target.width = canvasWidth;
			target.height = intrinsicHeight;
		}
		return;
	}
	if (sizeString === 'cover') {
		if (intrinsicWidth < intrinsicHeight) {
			target.width = canvasWidth;
			target.height = canvasWidth * intrinsicHeight/intrinsicWidth;
		} else {
			target.height = canvasHeight;
			target.width = canvasHeight * intrinsicWidth/intrinsicHeight;
		}
		return;
	}
	
	const fixedMatch = sizeString.trim().match(/^(auto|([\d.]+)([^\s]+))\s*(|auto|([\d.]+)([^\s]+))$/);
	if (fixedMatch) {
		let [, xAuto, x, xUnit, yAuto, y, yUnit] = fixedMatch;
		xAuto = xAuto === 'auto';
		yAuto = yAuto === 'auto' || yAuto === '';
		if (!xAuto) target.width = parseLength(x,xUnit,canvasWidth,canvasHeight,intrinsicWidth);
		if (!yAuto) target.height = parseLength(y,yUnit,canvasWidth,canvasHeight,intrinsicHeight);

		if (yAuto && xAuto) {
			target.width = intrinsicWidth;
			target.height = intrinsicHeight;
		} else if (xAuto) {
			target.width = target.height * intrinsicWidth/intrinsicHeight;
		} else if (yAuto) {
			target.height = target.width * intrinsicHeight/intrinsicWidth;
		}

		return;
	}
}

/**
 * Parse an angle string into an angle in radians
 * @param {string} value 
 * @param {string} unit 
 * @returns {number}
 */
function parseAngle(value, unit) {
	if (unit === 'deg') return parseFloat(value) * Math.PI/180;
	if (unit === 'rad') return parseFloat(value);
	if (unit === 'grad') return parseFloat(value) * Math.PI/200;
	if (unit === 'turn') return parseFloat(value) * Math.PI * 2;
	throw Error("Unrecognised angle unit: " + unit);
}

const positionRegex = /^(left|top|right|bottom|center)?\s*(([\d.]+)([^\s]+))?\s*(left|top|right|bottom|center)?\s*(([\d.]+)([^\s]+))?$/;
function parsePosition(positionString, canvasWidth, canvasHeight, objectWidth, objectHeight) {
	let [, originA, , a, aUnit, originB, , b, bUnit] = positionString.trim().match(positionRegex);
	const leftOffset = 0;
	const rightOffset = canvasWidth - objectWidth;
	const topOffset = 0;
	const bottomOffset = canvasHeight - objectHeight;

	if (originA && a && originB && b) {
		// do nothing everythign is populated
	}

	// Only one origin is named
	else if (originA && !a && !originB && !b) {
		a = 0;
		aUnit = 'px';
		b = 0;
		bUnit = 'px';
		if (originA === 'center') originB = 'center';
		else originB = 'top';
	}

	// Both origins are named
	else if (originA && !a && originB && !b) {
		a = 0;
		aUnit = 'px';
		b = 0;
		bUnit = 'px';
	}

	// An origin and a size are named
	else if (originA && a && !originB && !b) {
		b = a;
		bUnit = aUnit;
		originB = 'top';
		a = 0;
		aUnit = 'px';
	}

	/* Two origins but only one size */
	else if (originA && a && originB && !b) {
		b = 0;
		bUnit = 'px';
	}

	/* Two origins but only one size */
	else if (originA && !a && originB && b) {
		a = 0;
		aUnit = 'px';
	}

	// If only sizes are named
	else if (!originA && a && !originB && b) {
		originA = 'left';
		originB = 'top';
	}

	// fill in the remainder with defaults
	if (aUnit === undefined) aUnit = 'px';
	if (bUnit === undefined) bUnit = 'px';
	if (a === undefined) a = 0;
	if (b === undefined) b = 0;

	const ef = [undefined, undefined];
	for (const [origin, value, unit] of [[originA, a, aUnit],[originB, b, bUnit]]) {

		let size, direction, target;
		if (origin === 'left') {
			size = rightOffset;
			direction = 1;
			target = 0;
		} else if (origin === 'right') {
			size = rightOffset;
			direction = -1;
			target = 0;
		} else if (origin === 'top') {
			size = bottomOffset;
			direction = 1;
			target = 1;
		} else if (origin === 'bottom') {
			size = bottomOffset;
			direction = -1;
			target = 1;
		} else {
			// it's center so continue
			continue;
		}
		ef[target] = parseLength(value, unit, canvasWidth, canvasHeight, size);
		ef[target] *= direction;
		if (origin === 'left') ef[target] += leftOffset;
		if (origin === 'top') ef[target] += topOffset;
		if (origin === 'right') ef[target] += rightOffset;
		if (origin === 'bottom') ef[target] += bottomOffset;
	}
	if (originA === 'center') {
		const index = ef.indexOf(undefined);
		ef[index] = (index ? bottomOffset : rightOffset) * 0.5;
	}
	if (originB === 'center') {
		const index = ef.indexOf(undefined);
		ef[index] = (index ? bottomOffset : rightOffset) * 0.5;
	}
	return ef;
}

function addColorStop(gradient, stop, color, colors, lastStop) {
	if (colors && colors.length) {
		for (let i=1;i<=colors.length;i++) {
			gradient.addColorStop(lastStop + i*(stop - lastStop)/(colors.length + 1), colors[i-1]);
			// console.log(lastStop + i*(stop - lastStop)/(colors.length + 1), colors[i-1]);
		}
	}
	if (stop <= 1) {
		gradient.addColorStop(stop, color);
		// console.log(stop, color);
	}
	return stop;
}

const centerPoint = new Vector2();
const gradientVector = new Vector2();
const zeroVector = new Vector2(0,0);
const testPoint = new Vector2();
const corner = new Vector2();
const radialGradientConfigRegex = /^((?<shape>circle|ellipse)\s*)?(?<sizeConfig>((?<ellipseX>[\d.]+)%\s+(?<ellipseY>[\d.]+)%)|(?<circleSizeValue>[\d.]+)(?<circleSizeUnit>[^0-9\s]+)|closest-side|closest-corner|farthest-side|farthest-corner)?\s*(at\s+(?<position>.+))?$/;
export async function drawBackground(canvas, backgroundString) {
	const backgrounds = getBackgrounds(backgroundString);
	const width = canvas.width;
	const height = canvas.height;

	/**
	 * @type {CanvasRenderingContext2D}
	 */
	const context = canvas.getContext("2d");
	for (const bg of backgrounds) {
		if (bg.color) {
			context.fillStyle = bg.color;
			context.fillRect(0,0,canvas.width, canvas.height);
		}
		if (bg.image !== 'none') {
			let pattern;
			let success = true;
			let [,repeating,type,details] = bg.image.trim().match(/^(repeating-)?(\s*[^(]+)\(\s*(.+)\s*\)$/);
			type = type.trim().toLowerCase();
			details = details.trim();
			if (type === 'url') {
				pattern = await new Promise(resolve => {
					const img = new Image();
					img.src = details.split('"').join('');
					img.addEventListener('load', () => {
						if (bg.size === 'auto') {
							tileCanvas.width = canvas.width;
							tileCanvas.height = canvas.height;
							resolve(context.createPattern(img, bg.repeat));
						} else {
							parseSize(bg.size, width, height, tileCanvas, img.width, img.height);
							tileCanvas.getContext('2d').drawImage(img, 0, 0, tileCanvas.width, tileCanvas.height);
							resolve(context.createPattern(tileCanvas, bg.repeat));
						}
					});
				});
			} else if (type === 'linear-gradient' || type === 'conic-gradient' || type === 'radial-gradient') {
				parseSize(bg.size, width, height, tileCanvas);
				const tileContext = tileCanvas.getContext('2d');
				const data = details.split(/,(?![^(]*\))/).map(s => s.trim());
				let invScaleX = 1;
				let invScaleY = 1;
				centerPoint.set(tileCanvas.width * 0.5, tileCanvas.height * 0.5);

				let gradient;
				if (type === 'linear-gradient') {

					let angle = 0;
					const angleMatch = data[0].match(/^(([\d.]+)(.+))|(to\s+([^\s]+)\s*([^\s]+)?)$/);
					if (angleMatch) {
						data.shift();
						// todo parse data
						if (angleMatch[5]) {
							if (!angleMatch[6]) {
								if (angleMatch[5] === 'top') angle = 0;
								if (angleMatch[5] === 'left') angle = 3*Math.PI/2;
								if (angleMatch[5] === 'bottom') angle = Math.PI;
								if (angleMatch[5] === 'right') angle = Math.PI/2;
							} else {
								angle = Math.atan(tileCanvas.width/tileCanvas.height);
								if (angleMatch[5] === 'right' || angleMatch[6] === 'right') {
									if (angleMatch[5] === 'bottom' || angleMatch[6] === 'bottom') {
										angle = Math.PI - angle;
									}
								}
								if (angleMatch[5] === 'left' || angleMatch[6] === 'left') {
									if (angleMatch[5] === 'bottom' || angleMatch[6] === 'bottom') {
										angle = Math.PI + angle;
									}
									if (angleMatch[5] === 'top' || angleMatch[6] === 'top') {
										angle = 2*Math.PI - angle;
									}
								}
							}
						}

						if (angleMatch[2] && angleMatch[3]) angle = parseAngle(angleMatch[2], angleMatch[3]);
					}

					gradientVector.set(0,-1).rotateAround(zeroVector, angle);

					let minT = Infinity;
					let maxT = -Infinity;
					[0,1,2,3].map(i => {
						testPoint.set(tileCanvas.width * (1-!(i&1)), tileCanvas.height * (1-!(i&2)));
						testPoint.subVectors(centerPoint, testPoint);
						const t = testPoint.dot(gradientVector);
						if (t < minT) minT = t;
						if (t > maxT) maxT = t;
					});

					const args = [];
					testPoint.copy(gradientVector).multiplyScalar(minT).add(centerPoint);
					args[0] = testPoint.x;
					args[1] = testPoint.y;
					testPoint.copy(gradientVector).multiplyScalar(maxT).add(centerPoint);
					args[2] = testPoint.x;
					args[3] = testPoint.y;

					// Add three color stops
					gradient = tileContext.createLinearGradient(...args);
				} else if (type === 'radial-gradient') {
					let configMatch = data[0].match(radialGradientConfigRegex);

					if (configMatch) data.shift();
					else  configMatch = {groups:{}};

					const positionString = configMatch.groups.position || 'center center';
					let isEllipse = configMatch.groups.shape !== 'circle';
					if (configMatch.groups.circleSizeUnit) isEllipse = false;
					let ellipseX, ellipseY;
					if (configMatch.groups.ellipseX) {
						isEllipse = true;
						ellipseX = parseFloat(configMatch.groups.ellipseX)*0.01;
						ellipseY = parseFloat(configMatch.groups.ellipseY)*0.01;
					}

					if (isEllipse) {
						const max = Math.max(tileCanvas.width, tileCanvas.height);
						const scaleX = (ellipseX || 1) * tileCanvas.width/max;
						const scaleY = (ellipseY || 1) * tileCanvas.height/max;
						invScaleX = max/tileCanvas.width;
						invScaleY = max/tileCanvas.height;
						tileContext.setTransform(scaleX,0,0,scaleY,0,0);
					}
					const position = parsePosition(positionString, tileCanvas.width * invScaleX, tileCanvas.height * invScaleY, 0, 0);

					let sizeConfig = configMatch.groups.sizeConfig || 'farthest-corner';
					if (configMatch.groups.circleSizeUnit) {
						const radius = parseLength(configMatch.groups.circleSizeValue, configMatch.groups.circleSizeUnit, tileCanvas.width, tileCanvas.height, tileCanvas.width);
						gradient = tileContext.createRadialGradient(...position, 0, ...position, radius);
					} else {
						const d = [position[0], position[1], tileCanvas.width * invScaleX - position[0], tileCanvas.height * invScaleY - position[1]];
						testPoint.set(...position);
						const dc = [
							corner.set(0, 0).sub(testPoint).length(), // topleft then clockwise
							corner.set(0, tileCanvas.width * invScaleX).sub(testPoint).length(),
							corner.set(tileCanvas.height * invScaleY, tileCanvas.width * invScaleX).sub(testPoint).length(), 
							corner.set(tileCanvas.height * invScaleY, 0).sub(testPoint).length(),
						];
						if (sizeConfig === 'closest-side') gradient = tileContext.createRadialGradient(...position, 0, ...position, Math.min(...d));
						else if (sizeConfig === 'farthest-side') gradient = tileContext.createRadialGradient(...position, 0, ...position, Math.max(...d));
						else if (sizeConfig === 'closest-corner') gradient = tileContext.createRadialGradient(...position, 0, ...position, Math.min(...dc));
						else if (sizeConfig === 'farthest-corner') gradient = tileContext.createRadialGradient(...position, 0, ...position, Math.max(...dc));
						else console.log('Oh dear please report as a bug');
					}
				} else if (type === 'conic-gradient') {
					let configMatch = data[0].match(/^(?<angle>from\s+(?<angleValue>[\d.]+)(?<angleUnit>[^\s]+))?\s*(at\s+(?<position>.+))?$/);

					if (configMatch) data.shift();
					else  configMatch = {groups:{}};

					let angle = 0;
					let position = parsePosition(configMatch.groups.position || 'center center', tileCanvas.width, tileCanvas.height, 0, 0);
					if (configMatch.groups.angle) angle = parseAngle(configMatch.groups.angleValue, configMatch.groups.angleUnit);

					angle -= Math.PI/2;

					gradient = tileContext.createConicGradient(angle, ...position);
				}

				let lastLoopStop = 0;
				let lastStop = 0;
				let lastColor = '';
				let count = 0;
				const todo = [];
				do {
					for (let i=0; i<data.length; i++) {
						const stopString = data[i];
						const hint = stopString.match(/^([\d.]+)%|0$/);
						const angle = stopString.match(/^([\d.]+)(turn|deg|rad|grad)|0$/);
						const length = stopString.match(/^([\d.]+)([^\s]+)|0$/);
						if (hint) {
							lastStop = addColorStop(gradient, lastLoopStop + parseFloat(hint[1] || 0)*0.01, lastColor, todo.splice(0), lastStop);
						} else if (angle) {
							lastStop = addColorStop(gradient, lastLoopStop + parseAngle(angle[1],angle[2])/(Math.PI*2), lastColor, todo.splice(0), lastStop);
						} else if (length) {
							// this should really be proportional to the angle of the linear-gradient so it won't actually be accurate to the pixel
							lastStop = addColorStop(gradient, lastLoopStop + parseLength(length[1], length[2], tileCanvas.width, tileCanvas.height, tileCanvas.width)/tileCanvas.width, lastColor, todo.splice(0), lastStop);
						} else {
							const stopData = stopString.split(/\s+(?![^(]*\))/);
							let stops = [];
							for (const part of stopData) {
								const percent = part.match(/^([\d.]+)%$|0$/);
								const angle = part.match(/^([\d.]+)(turn|deg|rad|grad)$|0$/);
								const length = part.match(/^([\d.]+)([^\s]+)$|0$/);
								if (percent) stops.push(lastLoopStop + parseFloat(percent[1] || 0)*0.01);
								else if (angle) stops.push(lastLoopStop + parseAngle(angle[1],angle[2])/(Math.PI*2));
								else if (length) stops.push(lastLoopStop + parseLength(length[1], length[2], tileCanvas.width, tileCanvas.height, tileCanvas.width)/tileCanvas.width);
								else lastColor = part;
							}
	
							if (i === 0) lastStop = addColorStop(gradient, lastLoopStop, lastColor);
	
							if (stops.length) {
								for (const stop of stops) {
									lastStop = addColorStop(gradient, stop, lastColor, todo.splice(0), lastStop);
								} 
							} else if (i !== 0) {
								todo.push(lastColor);
							}
						}
					}
					lastLoopStop = lastStop;
				} while (repeating && lastLoopStop < 1 && (count++<200));
				if (!repeating) lastStop = addColorStop(gradient, 1, lastColor, todo.splice(0), lastStop);

				// Set the fill style and draw a rectangle
				tileContext.fillStyle = gradient;
				tileContext.fillRect(0, 0, tileCanvas.width * invScaleX, tileCanvas.height * invScaleY);
				pattern = context.createPattern(tileCanvas, bg.repeat);
			} else {
				success = false;
				console.warn(this, `${type} is unsupported`);
			}
			if (success) {

				const ef = parsePosition(bg.position, canvas.width, canvas.height, tileCanvas.width, tileCanvas.height);
				context.setTransform(1, 0, 0, 1, ...ef);
				context.fillStyle = pattern;
				context.fillRect(-width, -height, width*3, height*3);
			}
		}
	}
}
