import { Box3, Object3D, Vector2, Vector3 } from 'three';
import { defaultDocumentationMessage } from '../strings.js';
import { clamp } from '../utils/utils.js';

let documentation = defaultDocumentationMessage;

const html = String.raw;
let css = window.document.styleSheets[0];
if (!css) {
	document.head.appendChild(document.createElement('style'));
	css = window.document.styleSheets[0];
}
const style = html`<style>

sh-scene a, .clickable {
	position: absolute;
	contain: strict;
	cursor: pointer;
	border-radius: 1em;
}

@media (any-pointer: fine) {
	sh-scene a, .clickable {
		pointer-events: none;
	}
}

</style>`;

for (const rule of style.split('\n\n').slice(1,-1)) {
	css.insertRule(rule, css.cssRules.length);
}

const name = 'DomHitboxes';
documentation: {
	documentation = `If this element is clickable such as by being in an \`<a>\` element or having the \`clickable\` CSS class then the DOM Element's position in the page will match the WebGL rendered size and position.`;
}

export function register (registerShortHandElement,  schema) {
	const schemas = schema.schemas;
	const bbox = new Box3();
	const point = new Vector3();
	const min = new Vector2();
	const max = new Vector2();
	const temp = new Vector2();

	schemas.get(Object3D).get('mixins').push(baseclass => class extends baseclass {

		#hasProps=false;
		#deferEl;
		#keyup;
	
		static name = name;
		static documentation=documentation;
	
		constructor() {
			super();
			this.#keyup = function keyUp(e) {
				if (e.keyCode === 13) {
					this.click();
				}
			}.bind(this);
		}
	
		tick(time, delta, frame, renderer, session) {
			super.tick(time, delta, frame, renderer, session);
			if (this.object instanceof Object3D && this.matches(`a > *, .clickable`)) {
				const camera = renderer.properties.camera;
				bbox.setFromObject(this.object);
				min.set(1, 1);
				max.set(-1, -1);
				let z = Infinity;
				for (let i=0;i<8;i++) {
					point.x = (i&1?bbox.min:bbox.max).x;
					point.y = (i&2?bbox.min:bbox.max).y;
					point.z = (i&4?bbox.min:bbox.max).z;
					point.project(camera);
					if (point.z < 1) {
						point.x = clamp(point.x, -1, 1);
						point.y = clamp(point.y, -1, 1);
						if (point.x < min.x) min.x = point.x;
						if (point.y < min.y) min.y = point.y;
						if (point.x > max.x) max.x = point.x;
						if (point.y > max.y) max.y = point.y;
						if (point.z < z) z = point.z;
					}
				}

				temp.set(renderer.width/2, -renderer.height/2);
				min.multiply(temp);
				max.multiply(temp);
				temp.set(renderer.width/2, renderer.height/2);
				min.add(temp);
				max.add(temp);

				let el;
				if (!this.#hasProps) {
					this.#hasProps = true;
					if (this.matches(`a ${this.tagName.toLowerCase()}`)) {
						this.#deferEl = this.closest('a');
					} else {
						this.addEventListener('keyup', this.#keyup);
					}
					el = this.#deferEl || this;
					el.setAttribute('tabindex', '0');
					el.setAttribute('draggable', 'false');
				} else {
					el = this.#deferEl || this;
				}
				const width = (max.x - min.x);
				const height = (min.y - max.y);
				if (height && width) {
					el.style.left = min.x + 'px';
					el.style.top = max.y + 'px';
					el.style.width = width + 'px';
					el.style.height = height + 'px';
					el.style.display = 'block';
					el.style.zIndex = Math.floor(Math.log(1-z)*100)+1000;
				}
			} else {
				if (this.#hasProps) {
					const el = this.#deferEl || this;
					this.#deferEl = null;
					this.removeEventListener('keyup', this.#keyup);
					el.removeAttribute('tabindex');
					el.removeAttribute('draggable');
					el.style.removeProperty('width');
					el.style.removeProperty('height');
					el.style.removeProperty('top');
					el.style.removeProperty('left');
					el.style.removeProperty('z-index');
				}
			}
		}
	});
}
