// https://github.com/thednp/svg-path-commander/blob/master/src/util/shapeToPathArray.ts#L137
export const getRectanglePath = (attr) => {
	const x = +attr.x || 0;
	const y = +attr.y || 0;
	const w = +attr.width || 0.5;
	const h = +attr.height || 0.5;
	let rx = +(attr.rx || 0);
	let ry = +(attr.ry || rx);
	if (rx || ry) {

		if (rx * 2 > w) rx -= (rx * 2 - w) / 2;
		if (ry * 2 > h) ry -= (ry * 2 - h) / 2;

		return [
			['M', x + rx, y],
			['h', w - rx * 2],
			['s', rx, 0, rx, ry],
			['v', h - ry * 2],
			['s', 0, ry, -rx, ry],
			['h', -w + rx * 2],
			['s', -rx, 0, -rx, -ry],
			['v', -h + ry * 2],
			['s', 0, -ry, rx, -ry],
		].flat().join(' ');
	}

	return [['M', x, y], ['h', w], ['v', h], ['H', x], ['Z']].flat().join(' ');
};
