import { STORED_ON_EL } from '../schema.js';
import { Group, Mesh, Vector3, Object3D, MeshBasicMaterial, Plane, PlaneGeometry, BackSide, Material } from 'three';
import { defaultDocumentationMessage } from '../strings.js';
import { IterableWeakMap } from '../utils/utils.js';

let documentation = defaultDocumentationMessage;
documentation: {
	documentation = `This is used to define a window, any materials defined as children of this element are constrained to the window.`;
}

function roundedRectPath(width, height, radius=0.1, offsetY=0) {
	const halfHeight = height/2;
	const halfWidth = width/2;
	const x0 = radius - halfWidth;
	const y0 = offsetY - halfHeight;
	const h0 = halfWidth * 2 - radius * 2;
	const v1 = halfHeight * 2 - radius * 2;
	const h2 = -1 * (halfWidth * 2 - radius * 2);
	const v3 = -1 * (halfHeight * 2 - radius * 2);
	return `path(M ${x0.toFixed(4)} ${y0.toFixed(4)} h ${h0.toFixed(4)} q ${radius.toFixed(4)} 0 ${radius.toFixed(4)} ${radius.toFixed(4)} v ${v1.toFixed(4)} q 0 ${radius.toFixed(4)} -${radius.toFixed(4)} ${radius.toFixed(4)} h ${h2.toFixed(4)} q ${-radius.toFixed(4)} 0 -${radius.toFixed(4)} -${radius.toFixed(4)} v ${v3.toFixed(4)} q 0 ${-radius.toFixed(4)} ${radius.toFixed(4)} ${-radius.toFixed(4)}) `;
}

export const worldClippingPlanes = [];
export const worldInverseClippingPlanes = [];
export function register (registerShortHandElement,  schema) {
	const dioramas = new IterableWeakMap();

	const schemas = schema.schemas;
	const tempA = new Vector3();
	const tempB = new Vector3();
	const pos = new Vector3();
	const type = Object3D;
	const name = 'Diorama';
	const mixin = (baseClass) => class SHDiorama extends baseClass {
		static name = name;
		static documentation = documentation;
		static documentationPriority = -1;
		isSHDiorama=true;
		#clippingPlanes=[];
		#inverseClippingPlanes=[];
		#corners;
		#clipTicker;
		static shortHandSchema = new Map([
			['width', { default: 0.5, stage: STORED_ON_EL, example: 0.5 }],
			['height', { default: 0.3, stage: STORED_ON_EL, example: 0.3 }],
		]);
		constructor () {
			super();
			for (let i = 0; i < 4; i++) this.#clippingPlanes.push(new Plane());
			for (let i = 0; i < 4; i++) this.#inverseClippingPlanes.push(new Plane());
			dioramas.set(this, [this.#clippingPlanes, this.#inverseClippingPlanes]);
			worldClippingPlanes.splice(0);
			worldClippingPlanes.push(...Array.from(dioramas.values()).flatMap(o => o[0]));
			worldInverseClippingPlanes.splice(0);
			worldInverseClippingPlanes.push(...Array.from(dioramas.values()).flatMap(o => o[1]));

			this.#corners = [];
			for (let i = 0; i < 4; i++) {
				const object3d = new Object3D();
				this.#corners.push(object3d);
			}

			this.#clipTicker = new Mesh(
				new PlaneGeometry(1,1),
				new MeshBasicMaterial({ color: 'black', side: BackSide})
			);
			this.#clipTicker.onBeforeRender = (renderer, scene, camera /*, geo, group */) => {
				pos.setFromMatrixPosition(camera.matrixWorld);
				this.#updateClipPositions(pos);
			};
			this.#clipTicker.scale.set(this.properties.width, this.properties.height, 0.01);

			for (let i = 0; i < 4; i++) {
				const object3d = this.#corners[i];
				const theta = (i / 4 + 0.125) * 2 * Math.PI;
				object3d.position.set(this.properties.width * 0.5 * Math.sin(theta), this.properties.height * 0.5 * Math.cos(theta), 0).multiplyScalar(1.39502);
			}
		}
		async attributeChangedCallback(attr, oldValue, newValue, fromStyleChange) {
			await super.attributeChangedCallback(attr, oldValue, newValue, fromStyleChange);
			if (attr === 'width' || attr === 'height') {
				for (let i = 0; i < 4; i++) {
					const object3d = this.#corners[i];
					const theta = (i / 4 + 0.125) * 2 * Math.PI;
					object3d.position.set(this.properties.width * 0.5 * Math.sin(theta), this.properties.height * 0.5 * Math.cos(theta), 0).multiplyScalar(1.39502);
				}
				const r = 0.007;
				const b = 0.007;
				this.style.setProperty('--frame-geometry', `${roundedRectPath(this.properties.width+b, this.properties.height+b, r*2)} / ${roundedRectPath(this.properties.width-b, this.properties.height-b, r)}, ${roundedRectPath(this.properties.width*0.8, r, r/2, -this.properties.height/2-b*2)}`);
			}
		}
		async allAttributesChangedCallback() {
			const object = new Group();
			object.add(this.#clipTicker);
			for (const corner of this.#corners) {
				object.add(corner);
			}

			await this.assignPostConstructAttributes(object);
			this.updateObject(object);
		}
		#updateClipPositions(pos) {
			for (var i = 0; i < 4; i++) {
				this.#clippingPlanes[i].setFromCoplanarPoints(
					pos,
					this.#corners[(i + 1) % 4].getWorldPosition(tempA),
					this.#corners[(i + 2) % 4].getWorldPosition(tempB)
				);
				this.#inverseClippingPlanes[i].setFromCoplanarPoints(
					pos,
					this.#corners[(i + 2) % 4].getWorldPosition(tempB),
					this.#corners[(i + 1) % 4].getWorldPosition(tempA)
				);
			}
		}
	};

	registerShortHandElement('sh-diorama', {
		mixin, type, name
	});

	schemas.get(Material).get('mixins').push((baseClass) => class extends baseClass {
		static name = 'ClippingPlanes';
		async connectedCallback() {
			await super.connectedCallback();
			const object = await this.object;
			object.clipIntersection = true;
			object.clippingPlanes = worldInverseClippingPlanes;
			
			let parent = this.parentNode;
			while (parent) {
				if (parent.isSHDiorama) {
					object.clipIntersection = false;
					object.clippingPlanes = worldClippingPlanes;
				}

				// break out of shadowDom
				if (parent.getRootNode().host && parent.getRootNode() === parent) {
					parent = parent.getRootNode().host;
				} else {
					parent = parent.parentNode;
				}
			}
		}
	});
}
