import { Group } from 'three';
import { defaultDocumentationMessage } from '../strings.js';
import { shortHandSchema } from '../utils/utils.js';
import { STORED_ON_EL } from '../schema.js';

let documentation = defaultDocumentationMessage;
documentation: {
	documentation = `This is designed to be placed in sh-user so that it receives events and uses them to show a useful teleporting ray.`;
}

export const name = 'Teleporter';
export const type = Group; // Replace with what ever THREE object this is 
/** @param {typeof HTMLElement} baseClass */
export const mixin = (baseClass) => class extends baseClass {
	static shortHandSchema = shortHandSchema({
		'enabled': { default: true, stage: STORED_ON_EL }
	});

	static name = name;
	async handleEvent(e) {
		const details = e.detail;
		console.log(details);
		if (e.type === 'selectstart') {
			// Do nothing
		}
	}

	#user;
	static documentation=documentation;
	async connectedCallback() {
		this.#user = this.closest('sh-user');
		if (this.#user) {
			this.#user.addEventListener('selectstart', this);
		}
		await super.connectedCallback();
	}

	tick(time, delta, frame, renderer, session) {
		super.tick(time, delta, frame, renderer, session);
	}

};
