import { CanvasTexture } from 'three';

export const type = CanvasTexture;
export const name = 'CanvasTexture';
export const native =  {class: HTMLCanvasElement, tagName: 'canvas'};
/** @param {typeof HTMLElement} baseClass */
export const mixin = (baseClass) => class SHCanvasTexture extends baseClass {
	static name = name;
	constructor() { 
		super();
		// this.style.display = 'none';
		let canvasCtx;
		const self = this;
		const oldFn = this.getContext;
		this.getContext = function getContext(type, options) {
			if (type !== "2d") throw Error('Non 2D canvas not supported yet');
			canvasCtx = oldFn.call(this, '2d', options);
			return new Proxy(canvasCtx, {
				get(target, propertyKey) {
					const val = canvasCtx[propertyKey];
					if (val.bind) {
						if (self.ready) self.object.needsUpdate = true;
						return val.bind(canvasCtx);
					}
					return val;
				},
				set(target, propertyKey, value) {
					return canvasCtx[propertyKey] = value;
				}
			});
		};
	}
	async allAttributesChangedCallback() {
		const object = new CanvasTexture(this);
		object.needsUpdate = this.true;
		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
};
