import { Object3D } from "three";
import { markAsDirty } from "./style-attributes";

/**
 * 
 * @param {HTMLElement} trackedElement 
 * @param {Function} callback 
 */

export function register (registerShortHandElement, schema) {
	const schemas = schema.schemas;
	const name = 'AddToParent';

	/**
	 * 
	 * @param {HTMLElement} baseClass 
	 * @returns {HTMLElement}
	 */
	const addToParentMixin = (baseClass) => class extends baseClass {
		static name = name;
		async connectedCallback() {
			await super.connectedCallback();
			await this.#addToParent(this.#hasBeenPlacedBefore);
			// startParentChangeObserver(this, () => this.#addToParent(true));
		}
		shReparent(newParent) {
			/**
			 * Use this to change an element's object3D's parent without changing the DOM structure.
			 * This also keeps the element in place in the 3D space.
			 */
			const object = this.object;
			newParent.attach(object);
			this.style.setProperty('--location', `${object.position.x} ${object.position.y} ${object.position.z}`);
			this.style.setProperty('--scale', `${object.scale.x} ${object.scale.y} ${object.scale.z}`);
			this.style.setProperty('--quaternion', `${object.quaternion.x} ${object.quaternion.y} ${object.quaternion.z} ${object.quaternion.w}`);
			if (this.postConstruct.has('quaternion')) this.postConstruct.get('quaternion').copy(object.quaternion);
			else this.postConstruct.set('quaternion', object.quaternion.clone());
			if (this.postConstruct.has('position')) this.postConstruct.get('position').copy(object.position);
			else this.postConstruct.set('position', object.position.clone());
			if (this.postConstruct.has('scale')) this.postConstruct.get('scale').copy(object.scale);
			else this.postConstruct.set('scale', object.scale.clone());
		}
		#hasBeenPlacedBefore=false;
		async #addToParent(reparent=false) {
			if (!this.isConnected) return;
			this.#hasBeenPlacedBefore = true;
			let parentElement = this.parentElement || this.getRootNode().host;
			if (parentElement.isShortHandElement && !parentElement.ready) await parentElement.object;
			if (this.assignedSlot) {
				let finalSlot = this;
				while (finalSlot.assignedSlot) finalSlot = finalSlot.assignedSlot;
				parentElement = finalSlot.parentElement || finalSlot.getRootNode().host;
			}
			let done = false;
			while (!done && parentElement) {
				while (parentElement && !parentElement.isShortHandElement) {
					parentElement = parentElement.parentElement || parentElement.getRootNode().host;
				}
				if (parentElement) {
					const parentObject = await parentElement.object;
					if (parentObject instanceof Object3D) {
						// await reflectObjectFromEl(this) - Can't use this because things which try to get private fields on this then fail
						if (reparent) {
							await this.object;
							this.shReparent(parentObject);
						}
						else parentObject.add(await this.object);
						done = true;
					} else {
						const newParentElement = parentElement.parentElement || parentElement.getRootNode().host;
						if (newParentElement.isShortHandElement && !newParentElement.ready) await newParentElement.object;
						if (parentElement.assignedSlot) {
							let finalSlot = this;
							while (finalSlot.assignedSlot) finalSlot = finalSlot.assignedSlot;
							let newParentElement = finalSlot.parentElement || finalSlot.getRootNode().host;
							if (newParentElement === parentElement) parentElement = newParentElement.parentElement;
							else parentElement = newParentElement;
						}
						else parentElement = newParentElement;
					}
				}
			}
			if (this.ready) markAsDirty(this);
		}
		async disconnectedCallback() {
			const object3D = await this.object;
			object3D.removeFromParent();
		}
	};

	schemas.get(Object3D).get('mixins').unshift(addToParentMixin);
}
