import {
	SphereGeometry,
	PlaneGeometry,
	BoxGeometry,
	RingGeometry,
	TubeGeometry,
	ConeGeometry,
	TorusGeometry,
	CircleGeometry,
	MeshBasicMaterial,
	MeshPhongMaterial,
	ShadowMaterial,
	MeshLambertMaterial,
	MeshStandardMaterial,
	MeshPhysicalMaterial,
	AmbientLight,
	Scene,
	Group,
	PerspectiveCamera,
	OrthographicCamera,
	CubeCamera,
	Mesh,
	MeshToonMaterial,
	CylinderGeometry,
	GridHelper,
	PolarGridHelper,
	LineBasicMaterial,
	LineDashedMaterial,
	Line,
	PointLight,
	MeshDepthMaterial} from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';

import {
	GroundedSkybox
} from 'three/examples/jsm/objects/GroundedSkybox.js';

import {Text} from 'troika-three-text';
import * as renderer from './components/renderer.js';
import * as model from './components/model.js';
import * as directionalLight from './components/directionalLight.js';
import * as orbitControls from './components/orbitControls.js';
import * as imageTexture from './components/imageTexture.js';
import * as videoTexture from './components/videoTexture.js';
import * as instancedMesh from './components/instancedMesh.js';
import * as canvasTexture from "./components/canvasTexture.js";
import * as user from './components/user.js';
import * as use from './components/use.js';
import * as xrSession from './components/xrSession.js';
import * as grab from './components/select-grab.js';
import * as materialToon from './components/material-graphic-toon.js';
import * as spotlight from './components/spotLight.js';
import * as textInput from './components/text-input.js';
import * as audio from './components/audio.js';
import * as audioListener from './components/audioListener.js';
import * as teleporter from './components/teleporter.js';
import {
	objectProxyMixin, objectProxyType, 
	animationProxyMixin, animationProxyType,
	materialProxyMixin, materialProxyType,
	lightProxyMixin, lightProxyType,
	instancedProxyMixin, instancedProxyType
} from './components/proxies.js';
import * as batchedMesh from './components/batchedMesh.js';
import * as batchedMeshItem from './components/batchedMeshItem.js';
import { html } from './utils/utils.js';
// import * as materialXLoader from './components/material-x.js';

export const registerTemplateToElement = use.registerTemplateToElement;
export function register(registerShortHandElement, schema) {
	const _schemas = schema.schemas;
	registerShortHandElement('sh-xr-session', xrSession);
	registerShortHandElement('sh-renderer-webgl', renderer);
	registerShortHandElement('sh-model', model);
	registerShortHandElement('sh-orbit-controls', orbitControls);
	registerShortHandElement('sh-light-directional', directionalLight);
	registerShortHandElement('sh-light-spot', spotlight);
	registerShortHandElement('sh-texture-image', imageTexture);
	registerShortHandElement('sh-texture-video', videoTexture);
	registerShortHandElement('sh-texture-canvas', canvasTexture);
	registerShortHandElement('sh-mesh-instanced', instancedMesh);
	registerShortHandElement('sh-user', user);
	registerShortHandElement('sh-select-grab', grab);
	registerShortHandElement('sh-use', use);
	registerShortHandElement('sh-material-toon-dither', materialToon);
	registerShortHandElement('sh-text-input', textInput);

	registerShortHandElement('sh-audio', audio);
	registerShortHandElement('sh-audio-listener', audioListener);
	
	registerShortHandElement('sh-teleporter', teleporter);

	registerShortHandElement('sh-mesh-batched', batchedMesh);
	registerShortHandElement('sh-mesh-batched-item', batchedMeshItem);


	// registerShortHandElement('sh-material-x', materialXLoader); // Doesn't work yet (THREE 154)

	registerShortHandElement('sh-material-proxy', {type: materialProxyType, mixin: materialProxyMixin});
	registerShortHandElement('sh-object-proxy', {type: objectProxyType, mixin: objectProxyMixin});
	registerShortHandElement('sh-animation-proxy', {type: animationProxyType, mixin: animationProxyMixin});
	registerShortHandElement('sh-light-proxy', {type: lightProxyType, mixin: lightProxyMixin});
	registerShortHandElement('sh-instance-proxy', {type: instancedProxyType, mixin: instancedProxyMixin});
	

	for (const [elementName, Class] of [
		['sh-geometry-sphere', SphereGeometry],
		['sh-geometry-cylinder', CylinderGeometry],
		['sh-geometry-circle', CircleGeometry],
		['sh-geometry-plane', PlaneGeometry],
		['sh-geometry-box', BoxGeometry],
		['sh-geometry-box-rounded', RoundedBoxGeometry],
		['sh-geometry-ring', RingGeometry],
		['sh-geometry-tube', TubeGeometry],
		['sh-geometry-cone', ConeGeometry],
		['sh-geometry-torus', TorusGeometry],

		['sh-material-basic', MeshBasicMaterial],
		['sh-material-phong', MeshPhongMaterial],
		['sh-material-shadow', ShadowMaterial],
		['sh-material-lambert', MeshLambertMaterial],
		['sh-material-standard', MeshStandardMaterial],
		['sh-material-physical', MeshPhysicalMaterial],
		['sh-material-toon', MeshToonMaterial],
		['sh-material-depth', MeshDepthMaterial],

		['sh-material-line', LineBasicMaterial],
		['sh-material-line-dashed', LineDashedMaterial],
		['sh-line', Line],

		['sh-environment', GroundedSkybox],

		['sh-light-ambient', AmbientLight],
		['sh-light-point', PointLight],
		['sh-scene', Scene],
		['sh-group', Group],
		['sh-camera-perspective', PerspectiveCamera],
		['sh-camera-orthographic', OrthographicCamera],
		['sh-camera-cube', CubeCamera],
		['sh-mesh', Mesh],
		['sh-grid', GridHelper],
		['sh-grid-polar', PolarGridHelper],
		['sh-text', Text]
	]) {
		registerShortHandElement(elementName, { type: Class });
	}

	const webxrTemplate = document.createElement('template');
	webxrTemplate.innerHTML = html`
	<style>
		sh-renderer-webgl {
			min-width: 100%;
			min-height: 100%;
		}
	</style>
	<sh-xr-session part="xrsession" id="xrsession" optional-features="\${optional-features|}"></sh-xr-session>
	<sh-geometry-cylinder id="pointer" height="2" radius-bottom="0.001" radius-top="0.001" location="0 1 0" rotate="-90 0 0"></sh-geometry-cylinder>
	<sh-material-basic color="red" id="red" visibility="hidden"></sh-material-basic>
	<sh-renderer-webgl shadow-type="\${shadow-type|soft}" scene="sh-scene" id="renderer" part="renderer" exposure="\${exposure|1}">
		<sh-scene part="scene" background-image="\${background-image|none}" slot="scene" environment="\${environment|linear-gradient(0deg, rgba(9,18,3,1) 0%, rgba(9,43,22,0.86) 46.18%, rgba(4,53,17,0) 52.43%) 0px 0px, radial-gradient(ellipse at 50% 50%, rgba(237,241,201,1) 0%, rgba(69,168,255,0) 63.19%) 30px 5px / 430px 438px no-repeat no-repeat, linear-gradient(0deg, rgba(19,38,27,1) 50%, rgba(35,107,170,1) 51.39%, rgba(8,5,49,1) 100%)}">
			<sh-user>
				<sh-mesh slot="left-ray" part="debug-ray" pointer-events="none" geometry="#pointer" material="#red" cast-shadow="false"></sh-mesh>
				<sh-mesh slot="right-ray" part="debug-ray" pointer-events="none" geometry="#pointer" material="#red" cast-shadow="false"></sh-mesh>
	
				<sh-select-grab part="grabber left-grip" slot="left-grip"></sh-select-grab>
				<sh-select-grab part="grabber right-grip" slot="right-grip"></sh-select-grab>
				<sh-select-grab part="grabber none-grip" slot="none-grip"></sh-select-grab>
				<sh-select-grab part="grabber transient-pointer-grip-0"  slot="transient-pointer-grip-0"></sh-select-grab>
				<sh-select-grab part="grabber transient-pointer-grip-1"  slot="transient-pointer-grip-1"></sh-select-grab>
				
				${user.slotNames.map(name => `<slot data-name="${name}" name="${name}" slot="${name}"></slot>`).join('\n')}
			</sh-user>
			<slot></slot>
		</sh-scene>
		<button class="enter-vr" data-action="enter-vr">Start VR</button>
		<button class="enter-ar" data-action="enter-ar">Start AR</button>
		<button class="enter-inline-xr" data-action="enter-inline">Start Inline</button>
		<button class="end-session" data-action="end-xr">Exit XR</button>
		<slot name="content"></slot>
	</sh-renderer-webgl>
	`;
	use.standardTemplates.set('webxr', webxrTemplate);
	registerTemplateToElement('sh-quickstart', 'std:webxr');
}
