import { SpotLight, SpotLightHelper } from 'three';
import { STORED_ON_EL } from '../schema.js';
import { shortHandSchema } from '../utils/utils.js';

export const type = SpotLight;
export const name = 'SpotLight';
export const mixin = (baseClass) => class SHDirectionalLight extends baseClass {
	static name = name;
	#helper;
	static shortHandSchema = shortHandSchema({
		'spot-helper': {as: 'spotHelper', default: false,stage: STORED_ON_EL},
		decay: {type: 'number'},
		target: {type: 'Object3D'},
		penumbra: {type: 'number'},
		distance: {type: 'number'},
		angle: {type: 'angle'},
		map: {type: 'Texture'}
	});
	tick(time, delta, frame, renderer, session) {
		super.tick(time, delta, frame, renderer, session);
		if ( !this.ready ) return;

		if (this.properties.spotHelper && this.object.parent) {
			if (!this.#helper) this.#helper = new SpotLightHelper(this.object);
			this.object.parent.add(this.#helper);
			this.#helper.visible = true;
			this.#helper.update();
		} else {
			if (this.#helper) {
				this.#helper.visible = false;
			}
			this.object.target.updateWorldMatrix( true, false );
		}
	}
};
