import { STORED_ON_EL, REQUIRES_RECONSTRUCT } from "../schema.js";
import { Object3D, AnimationMixer, Group, MeshStandardMaterial, MeshPhysicalMaterial, BatchedMesh, Matrix4 } from "three";
import { filenameFromURL, html } from '../utils/utils.js';

import {
	standardTemplates
} from "./use.js";
import { schemaReference } from "../customElementRegistration.js";
import { refreshTransform } from "../features/transform.js";
import { gltfLoader, ktxSupportDetectionPromise, usdzLoader } from "../utils/model-loaders.js";


const style = html`<style>

@keyframes object-animation {
	0% {--t: 0;}
	100% {--t: 1;}
}

</style>`;

let css = window.document.styleSheets[0];
if (!css) {
	document.head.appendChild(document.createElement('style'));
	css = window.document.styleSheets[0];
}
for (const rule of style.split('\n\n').slice(1,-1)) {
	css.insertRule(rule, css.cssRules.length);
}


function nameCleaner(inStr) {
	return inStr.toLowerCase().replace(/[\s.#[\]]/g, '-');
}

function loadGLTF(url) {
	return new Promise (function (resolve, reject) {
		gltfLoader.load(url, resolve, function(xhr){
			console.log( url + " " + ( xhr.loaded / xhr.total * 100 ).toFixed(1) + "% loaded" );
		}, reject);
	});
}

function loadUSDZ(url) {
	return new Promise (function (resolve, reject) {
		usdzLoader.load(url, resolve, function(xhr){
			console.log( url + " " + ( xhr.loaded / xhr.total * 100 ).toFixed(1) + "% loaded" );
		}, reject);
	});

}

let tRegistered = false;
function registerCSSAnimationProperties() {
	if (tRegistered) return;
	tRegistered = true;
}

const standaloneModelTemplate = document.createElement('template');
standaloneModelTemplate.innerHTML = html`
<style>
	sh-renderer-webgl {
		min-width: 100%;
		min-height: 100%;
	}
</style>
<sh-renderer-webgl scene="sh-scene" id="renderer" part="renderer" exposure="\${exposure|2.5}">
	<sh-scene slot="scene">
		<sh-model part="model" src="\${src}" scale="\${scale|none}" location="\${location|none}" rotate="\${rotate|none}" transform="\${transform|none}"></sh-model>
		<sh-mesh part="floor-shadow" material="shadow" geometry="floor" receive-shadow="true" cast-shadow="false" pointer-events="none"></sh-mesh>
		<sh-light-ambient color="\${ambient-light|#2e2e40}" intensity="1"></sh-light-ambient>
		<sh-light-directional part="directional-light" location="1 1 1" color="\${directional-light|#fcf8d9}" intensity="0.8"></sh-light-directional>
		<sh-orbit-controls camera="sh-camera-perspective" scroll-action="\${scroll-action|zoom}" pivot="\${camera-pivot|0 0.2 0}"></sh-orbit-controls>
		<sh-camera-perspective location="\${camera-position|0 0.6 0.8}" part="camera"></sh-camera-perspective>
		<slot name="scene"></slot>
	</sh-scene>
	<slot></slot>
</sh-renderer-webgl>
`;
standardTemplates.set('model', standaloneModelTemplate);

const tempMatrix = new Matrix4();

export const type = Group;
export const name = 'Model';
export const mixin = (baseClass) => class SHModel extends baseClass {
	static name = name;
	static shortHandSchema = new Map([
		["src", {type: "url", stage: STORED_ON_EL | REQUIRES_RECONSTRUCT, example: "./my-model.usdz"}],
		["instance-proxy-limit", {as: 'modelCreateInstancesLimit', type: "number", stage: STORED_ON_EL | REQUIRES_RECONSTRUCT }],
		["batches", {default: false, stage: STORED_ON_EL | REQUIRES_RECONSTRUCT }],
	]);
	#animMixer;
	#meshToBatchedMap;
	objectMaterials = new Map();
	objectsByName = new Map();
	constructor() {
		super();
		this.attachShadow({mode: 'open'});
	}
	async allAttributesChangedCallback() {
		const exportparts = [ "material", "hover", "mesh", "group"];
		await ktxSupportDetectionPromise;

		if (!this.properties.src) {
			throw "No src provided";
		}

		let loadResult;
		const fileName = filenameFromURL(this.properties.src).toLowerCase();
		if (fileName.endsWith('.glb') || fileName.endsWith('.gltf')) {
			loadResult = (await loadGLTF(this.properties.src));
		} else if (fileName.endsWith('.usd') || fileName.endsWith('.usdz')) {
			const usdzOutput = (await loadUSDZ(this.properties.src));
			loadResult = {
				scene: usdzOutput,
				animations: usdzOutput.animations
			};
		} else {
			throw Error('Unrecognised format');
		}
		const mainRootObject = loadResult.scene;
		
		this.#animMixer = new AnimationMixer( loadResult.scene );
		this.objectAnimations = new Map(loadResult.animations.map(anim => [anim.name, this.#animMixer.clipAction(anim)]) || []);

		if (this.shAddShadowDom !== false) {
			let html = "";
			let style = "";
			const  willChangeProperty = this.attributes.getNamedItem("will-change")?.value || "";
			if (loadResult.animations.length) {
				if (window.CSS.registerProperty) registerCSSAnimationProperties();
				style += `
					@keyframes object-animation {
						from {--t: 0.0;}
						to {--t: 1.0;}
					}
					:host {
						animation-timing-function: linear;
						animation-iteration-count: infinite;
						${
	loadResult.animations.map((anim, index) => {
		const animName = nameCleaner(anim.name);
		return `--animation-${animName}-duration: ${anim.duration}s;\n--animation-${animName}-weight: ${index===0?1:0};`;
	}).join("\n")}
					}
				`;
			}
			let isFirstAnimation = true;
			for (const anim of loadResult.animations) {
				const uuid = crypto.randomUUID();
				const animName = nameCleaner(anim.name);
	
				if (window.CSS.registerProperty) window.CSS.registerProperty({
					name: "--" + uuid,
					syntax: "<number>",
					inherits: true,
					initialValue: "0",
				});
	
				exportparts.push(animName);
				html += `<sh-animation-proxy will-change="t weight ${willChangeProperty}" t="0" paused="${isFirstAnimation?false:true}" weight="${isFirstAnimation?1:0}" target="${anim.name}" part="animation ${animName}"></sh-animation-proxy>${"\n"}`;
	
				let css = window.document.styleSheets[0];
				if (!css) {
					document.head.appendChild(document.createElement('style'));
					css = window.document.styleSheets[0];
				}
				css.insertRule(`
				@keyframes object-animation-${animName} {
					0% {--${uuid}: 0.0;}
					100% {--${uuid}: 1.0;}
				}`, css.cssRules.length);
				
				style += `
				[part~="${animName}"] {
					--weight: var(--animation-${animName}-weight, ${isFirstAnimation?1:0});
					--t: var(--${uuid});
					animation-duration: var(--animation-${animName}-duration);
					animation-timing-function: linear;
					animation-iteration-count: infinite;
				}`;
	
				isFirstAnimation = false;
			}

			const materialCounter = new Map();
			const materialReplacementMap = new Map();
			const materialProxyEls = [];
			let i=0;
			let j=0;
			mainRootObject.traverse(obj => {

				if (obj.material) {
					if (!materialCounter.has(obj.material)) {
						if (!obj.material.name) obj.material.name = 'material-' + i++;

						// This seems like a weird hack, remove?
						if (obj.material.transmission === 0 && obj.material instanceof MeshPhysicalMaterial) {
							const oldMat = obj.material;
							obj.material = materialReplacementMap.get(oldMat) || new MeshStandardMaterial().copy(oldMat);
							materialReplacementMap.set(oldMat, obj.material);
						}

						this.objectMaterials.set(obj.material.name, obj.material);
						const matName = nameCleaner(obj.material.name);
						exportparts.push(matName);
						let constructorName = "";
						if (obj.isMeshPhysicalMaterial) constructorName = "physical";
						else if (obj.isMeshSimpleMaterial) constructorName = "simple";

						const el = document.createElement('sh-material-proxy');
						if (willChangeProperty) el.setAttribute('will-change', willChangeProperty);
						el.setAttribute('target', obj.material.name);
						el.setAttribute('id', matName + '-proxy');
						el.setAttribute('part', `material ${obj?.userData?.part || ''} ${constructorName} ${matName}`);
						materialProxyEls.push(el);
					}	

					let counter = 0;
					if (materialCounter.has(obj.material)) {
						counter = materialCounter.get(obj.material);
					}
					materialCounter.set(obj.material, counter + 1);
				}
			});

			if (this.properties.batches) {
				this.#meshToBatchedMap = new Map();
			}

			const batchSetup = new Map();
			for (const [material, count] of materialCounter.entries()) {
				if (count > 1) {
					batchSetup.set(material, {
						count: 0,
						maxIndex: 0,
						maxVertex: 0,
						objects: [],
					});
				}
			}

			const objectProxyMap = new Map();
			const instanceProxyEls = [];
			const objectsToReplaceWithDummyForBatches = new Map();
			mainRootObject.traverse(obj => {
				if (obj === mainRootObject) {
					objectProxyMap.set(obj, this);
					return;
				}
	
				if (obj instanceof Object3D) {
	
					if (!obj.name) {
						obj.name = 'unamed-object-' + j++;
					}
	
					// Can't use constructor.name because the names get mangled by terser
					let constructorName = "";
					if (obj.isMesh) constructorName = "mesh";
					if (obj.isInstancedMesh) constructorName = "mesh instanced-mesh";
					else if (obj.isGroup) constructorName = "group";
					else if (obj.isLight) constructorName = "light";
					const el = obj.isLight ? document.createElement("sh-light-proxy") : document.createElement("sh-object-proxy");
					if (willChangeProperty) el.setAttribute('will-change', willChangeProperty);
					el.setAttribute('target', obj.name);

					let isPartofBatch = false;
					if (obj.isMesh) {
						const materialCount = materialCounter.get(obj.material);
						if (this.properties.batches && materialCount>1) {
							isPartofBatch = true;

							const batchConfig = batchSetup.get(obj.material);
							batchConfig.count += 1;
							batchConfig.objects.push(obj);
							batchConfig.maxIndex += obj.geometry.index.count;
							batchConfig.maxVertex += obj.geometry.attributes.position.count;
						}
						el.setAttribute('material', '#' + nameCleaner(obj.material.name) + '-proxy');
					}
					const objName = nameCleaner(obj.name);

					if (!isPartofBatch) {
						this.objectsByName.set(obj.name, obj);
						objectProxyMap.set(obj, el);
					} else {
						const g = new Group();
						g.dummyGeometry = obj.geometry;
						objectsToReplaceWithDummyForBatches.set(obj, g);
						this.objectsByName.set(obj.name, g);
						objectProxyMap.set(g, el);
					}

					exportparts.push(objName);
					el.id = objName;
					for (const [name, value] of Object.entries(obj.userData)) {
						if (schemaReference.get('sh-object-proxy').has(name)) {
							el.setAttribute(name, value);
						}
					}
					el.setAttribute('part', `object ${obj?.userData?.part || ''} ${constructorName} ${objName}`);

					const instanceLimit = this.properties.modelCreateInstancesLimit === undefined ? 16 : this.properties.modelCreateInstancesLimit;
					if (obj.isInstancedMesh && obj.count < instanceLimit) {
						for (let i=0;i<obj.count;i++) {
							const instanceEl = document.createElement('sh-instance-proxy');
							instanceEl.setAttribute('target', '#' + objName);
							instanceEl.setAttribute('index', i);
							instanceEl.setAttribute('part', `instance ${objName}-instance instance-${i}`);
							el.appendChild(instanceEl);
							instanceProxyEls.push(instanceEl);
						}
					}
				}
	
			});
	
			for (const [obj, g] of objectsToReplaceWithDummyForBatches) {
				g.visible = obj.visible;
				g.name = obj.name + '_dummy';
				g.isDummyForBatchedMesh = true;

				obj.parent.add(g);
				obj.removeFromParent();
				for (const c of obj.children) {
					g.add(c);
				}
			}

			const elements = [...instanceProxyEls, ...Array.from(objectProxyMap.values())];
			mainRootObject.raycast = function (raycaster, intersects) {
				for (const el of elements) {
					if (el.isBatchedMesh) {
						el.raycast(raycaster, intersects);
						for (const intersect of intersects) {
							if (intersect.object === el) {
								intersect.object = objectsToReplaceWithDummyForBatches.get(batchSetup.get(intersect.object.material).objects[intersect.batchId]);
							}
						}
					} else {
						const o = el.object;
						if (o === mainRootObject) continue;
						if (o && !(o instanceof Promise) && !o.isDummyForBatchedMesh) {
							if (o.visible && o.el.properties.pointerEvents !== 0) {
								o.raycast(raycaster, intersects);
							}
						}
					}
				}
			};
	
			// The export parts need to be set before the html is added so that the 
			// CSS is correctly set when onconnected is called.
			if (this.getRootNode().host) this.setAttribute('exportparts', exportparts.join(', '));
			this.shadowRoot.innerHTML = `<style>
				:host {
					position: absolute;
				}
				${style}
			</style>
			${html}
			<slot></slot>
	`;
			mainRootObject.traverse(obj => {
				if (obj === mainRootObject) return;
				if (obj instanceof Object3D) {
					const el = objectProxyMap.get(obj);
					if (obj.parent === mainRootObject) {
						this.shadowRoot.appendChild(el);
					} else {
						objectProxyMap.get(obj.parent).appendChild(el);
					}
				}
			});

			for (const [material, {
				count,
				maxIndex: indexCount,
				maxVertex: vertexCount,
				objects: geometryObjects
			}] of batchSetup.entries()) {
				const batchedMesh = new BatchedMesh(count, vertexCount, indexCount, material);
				batchedMesh.name = material.name + '_batched_mesh';
				elements.unshift(batchedMesh);
				for (const object of geometryObjects) {
					const index = batchedMesh.addGeometry(object.geometry);
					const dummyObject = objectsToReplaceWithDummyForBatches.get(object);
					const tempIntersectionArray = [];
					dummyObject.raycast = function (raycaster, intersects) {
						object.matrixWorld.copy(dummyObject.matrixWorld);
						object.raycast(raycaster, tempIntersectionArray);
						if (tempIntersectionArray.length) {
							tempIntersectionArray[0].object = dummyObject;
						}
						intersects.push(...tempIntersectionArray);
						tempIntersectionArray.splice(0);
					};
					this.#meshToBatchedMap.set(
						dummyObject,
						{
							index,
							batchedMesh
						}
					);
				}
				mainRootObject.add(batchedMesh);
			}
	
			for (const el of materialProxyEls) this.shadowRoot.appendChild(el);
		}
		this.updateObject(mainRootObject);
		refreshTransform(this);
		await this.assignPostConstructAttributes(this.object);
	}
	tick(time, delta, frame, renderer, session) {
		if (this.#meshToBatchedMap) {
			for (const [dummy, {index, batchedMesh}] of this.#meshToBatchedMap) {
				tempMatrix.copy(this.object.matrixWorld).invert().multiply(dummy.matrixWorld);
				batchedMesh.castShadow = dummy.castShadow;
				batchedMesh.receiveShadow = dummy.receiveShadow;
				batchedMesh.setMatrixAt(index, tempMatrix);
				batchedMesh.setVisibleAt ( index, dummy.visible );
			}
		}
		if (this.#animMixer) {
			this.#animMixer.update(delta);
		}

		// Fire tick events on children
		if (this.shadowRoot) for (const child of this.shadowRoot.children) {
			if (child.tick) child.tick(time, delta, frame, renderer, session);
		}

		super.tick(time, delta, frame, renderer, session);
	}
};
