import { Object3D, Vector3 } from 'three';
import { defaultDocumentationMessage } from '../strings.js';
import { clamp } from '../utils/utils.js';

let documentation = defaultDocumentationMessage;
documentation: {

	// Add any documentation for the README in here perhaps describe what attributes are optional
	// or how to use it.
	documentation = `linear-constraint is designed to place the element it's attached to 
place elements as close as possible to the target element whilst being restrained along a line
defined by the \`axis\`, between the \`min\` and \`max\` on either side of the original position
of the object when this component is first run.`;
}

export function register (registerShortHandElement,  schema) {
	const schemas = schema.schemas;
	const tempVector3A = new Vector3();
	const tempVector3B = new Vector3();
	const normal = new Vector3();
	schemas.get(Object3D).get('mixins').push(baseclass => class extends baseclass {
		static shortHandSchema = new Map([
			["mixins", []],
			['linear-constraint-axis', { as: 'linearConstraintAxis', type: 'Vector3', stage: schema.STORED_ON_EL }],
			['linear-constraint-target', { as: 'linearConstraintTarget', type: 'Elements', default: [], stage: schema.STORED_ON_EL }],
			['linear-constraint-options', { as: 'linearConstraintOptions', type: 'string', stage: schema.STORED_ON_EL, notes: "The format is: `[min] [max] [step] [radius limit] [downEventThreshold] [upEventThreshold] [default value if outside of radius]`" }]
		]); 
		static name = 'LinearConstraint';
		static documentation=documentation;
		
		static shortHandEventDescriptions = {
			'linearConstraintDown': 'Object being depressed passes down threshold',
			'linearConstraintUp': 'Object being raised passes up threshold',
		};

		#originalOffset;
		#oldT;
		#linearConstraintOptions = {
			min: -Infinity,
			max: Infinity,
			step: 0,
			downEventThreshold: -Infinity,
			upEventThreshold: Infinity,
			radius: 0,
			valueIfOutsideOfRadius: null
		};

		#isActive = null;
		#markActive() {
			if (this.#isActive !== true) {
				this.#isActive = true;
				if (this.getRootNode().host) this.part.add('linear-constraint-active');
				this.classList.add('linear-constraint-active');
			}
		}

		#markInactive() {
			if (this.#isActive !== false) {
				this.#isActive = false;
				if (this.getRootNode().host) this.part.remove('linear-constraint-active');
				this.classList.remove('linear-constraint-active');
			}
		}
	
		tick(time, delta, frame, renderer, session) {
			super.tick(time, delta, frame, renderer, session);
			let length;
			if (
				this.object instanceof Promise ||
				!this.properties.linearConstraintTarget ||
				this.properties.linearConstraintTarget.length === 0 ||
				!this.properties.linearConstraintAxis ||
				(length = this.properties.linearConstraintAxis.length()) === 0
			) {
				return this.#markInactive();
			}

			const object = this.object;
			const step = this.#linearConstraintOptions.step;
			if (!object) return;
			if (!this.#originalOffset) this.#originalOffset = new Vector3().copy(object.position);
			const n = normal.copy(this.properties.linearConstraintAxis).multiplyScalar(1/length);
			const p0 = tempVector3A;
			const min = this.#linearConstraintOptions.min;
			const max = this.#linearConstraintOptions.max;
			const radius = this.#linearConstraintOptions.radius;
			const valueIfOutsideOfRadius = this.#linearConstraintOptions.valueIfOutsideOfRadius;
			const useFixedValueIfOutOfRange = valueIfOutsideOfRadius !== null;
			const upEventThreshold = this.#linearConstraintOptions.upEventThreshold;
			const downEventThreshold = this.#linearConstraintOptions.downEventThreshold;
			const upEventName = 'linearConstraintUp';
			const downEventName = 'linearConstraintDown';
	
			// For the case of multiple targets pick the closest point.
			let closestD = Infinity;
			const testPoint = tempVector3B;
			for (const target of this.properties.linearConstraintTarget) {
				if (target.object instanceof Object3D) {
					if (target.parent && target.parent === object.parent) {
						testPoint.copy(target.object.position);
					} else {
						target.object.getWorldPosition(testPoint);
						object.parent.worldToLocal(testPoint);
					}
					testPoint.sub(this.#originalOffset);
					const distance = testPoint.length();
					if (distance < closestD) {
						closestD = distance;
						p0.copy(testPoint);
					}
				}
			}
	
			// We have a plane with normal n that contains p0
			// We want to place the object where a vector n from the origin intersects the plane
			// n.x x + n.y y + n.z z = p0.n
			// Sub in vector equation p=tn
			// t * n.x * n.x + t * n.y * n.y + t * n.z * n.z = p0.n
			// equivalent to  t * n.length() = p0.n
			// n has been normalised so n.length() = 1
			let t = p0.dot(n);
			const r = p0.addScaledVector(n ,-t).length();
			t = clamp(t, min, max);
			if (step>0) t = step*Math.round(t/step);
			if (radius && r > radius) {
				this.#markInactive();
				if (useFixedValueIfOutOfRange) {
					t = valueIfOutsideOfRadius;
				} else {
	
					// Out of range so just stop.
					return;
				}
			} else {
				this.#markActive();
			}
	
			if (this.#oldT !== null) {
				if (
					upEventName &&
					t >= upEventThreshold &&
					this.#oldT < upEventThreshold
				) {
					this.emit(upEventName);
				}
				
				if (
					downEventName &&
					t <= downEventThreshold &&
					this.#oldT > downEventThreshold
				) {
					this.emit(downEventName);
				}
			}
			
			object.position.copy(n).multiplyScalar(t).add(this.#originalOffset);
			this.#oldT = t;
		}
	
		stringToValue(attr, value) {
			// parse linear-constraint-options
			if (attr === 'linear-constraint-options') {
				if (!value) return null;
				// '[min] [max] [step] [radius limit] [downEventThreshold] [upEventThreshold] [default value if outside of radius]';
				const parsed = value.trim().split(/\s+/).map(v => {
					if (v === 'x' || v === null) return null;
					return parseFloat(v);
				});
				this.#linearConstraintOptions.min = Number.isFinite(parsed[0]) ? parsed[0] : -Infinity;
				this.#linearConstraintOptions.max = Number.isFinite(parsed[1]) ? parsed[1] : Infinity;
				this.#linearConstraintOptions.step = Number.isFinite(parsed[2]) ? parsed[2] : 0;
				this.#linearConstraintOptions.radius = Number.isFinite(parsed[3]) ? parsed[3] : 0;
				this.#linearConstraintOptions.downEventThreshold = Number.isFinite(parsed[4]) ? parsed[4] : -Infinity;
				this.#linearConstraintOptions.upEventThreshold = Number.isFinite(parsed[5]) ? parsed[5] : Infinity;
				this.#linearConstraintOptions.valueIfOutsideOfRadius = Number.isFinite(parsed[6]) ? parsed[6] : null;
				return Object.assign({}, this.#linearConstraintOptions);
			} else {
				return super.stringToValue(attr, value);
			}
		}
	});
}

