import { ShortHandCustomEvent, shortHandSchema } from '../utils/utils';
import { Text } from 'troika-three-text';

export const type = Text;
export const name = 'TextInput';
export const native = {class: HTMLInputElement, tagName: 'input'};

/**
 * @param {HTMLInputElement} baseClass 
 * @returns 
 */
export const mixin = (baseClass) => class SHTextInput extends baseClass {
	static name = name;
	static shortHandSchema = shortHandSchema();
	static template = false;
	constructor () {
		super();
		this.addEventListener('click', () => this.focus());
		window.addEventListener('click', e => {
			if (e instanceof ShortHandCustomEvent && e.target !== this) this.blur();
		});
	}
	getStringContent() {
		return this.value;
	}
};
