import { MeshPhysicalMaterial, Mesh, Light, Matrix4, LoopRepeat } from 'three';
import { STORED_ON_EL, REQUIRES_RECONSTRUCT, AnimationActionSymbol, materialMap, ASSIGNED_AFTER_CONSTRUCTION } from '../schema.js';
import { defaultDocumentationMessage } from '../strings.js';
import { shortHandSchema } from '../utils/utils.js';
import { InstancedMeshProxy } from './instancedMesh.js';

let documentationObject = defaultDocumentationMessage;
let documentationAnimation = defaultDocumentationMessage;
let documentationMaterial = defaultDocumentationMessage;
documentation:
{
	const documentation = `
The proxy objects are produced programmatically by \`sh-mesh\`, they are avaialble in the shadow dom for controlling different parts of the parent element.

Set the \`will-change\` property on the parent node and it will be inherited by child proxy objects for animation.

You can use the \`::part(name)\` CSS property to control these children. Explore the shadow-dom of the loaded mesh in your browsers devtools to see how the parts are exposed.
	`;

	documentationObject = documentation;
	documentationMaterial = documentation + `
You can update the color and map dynamically.
`;

	documentationAnimation = documentation + `
This is for controlling animations, set the \`t\` property to control the position in the animation between 0-1. You can animate this property to move the animation forwards or backwards.

It also predefines some CSS keyframes and custom properties to asist with this. If you set \`animation-name\` to \`object-animation\` then it will run the animation. The duration and easing has been set for you.
but you can configure them to adjust the animation.

The animation duration is available as the custom property \`--animation-[ animation name in lower case with spaces replaced by dashes ]-duration\` e.g. \`--animation-dance-duration\`

\`\`\`css
sh-model#robot::part(running) {
	animation-name: object-animation;
	--weight: 0.5;
}
\`\`\`

Also additional keyframe animations are defined so that you can run the animation by name on the parent, in this case you need to tell it the animation duration by referencing the custom property:

\`\`\`css
sh-model#robot {
	animation-duration: var(--animation-dance-duration);
	animation-name: object-animation-dance;
	--animation-dance-weight: 1;
}
\`\`\`
	`;
}
export const objectProxyType = Mesh;
export const objectProxyMixin = (baseClass) => class SHObjectProxy extends baseClass {
	static name = 'ObjectProxy';
	static shortHandSchema = shortHandSchema({
		target: {type: 'string', stage: STORED_ON_EL | REQUIRES_RECONSTRUCT },
		material: { type: 'Material', map: materialMap },
		geometry: undefined,
	});
	static documentation = documentationObject;
	addToParent(){}
	async allAttributesChangedCallback() {
		if (!this.properties.target) throw Error('This proxy does not have a target: ', this);
		const el = this.getRootNode().host;
		const object = el.objectsByName.get(this.properties.target);
		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
	tick (time, delta, frame, renderer, session) {
		super.tick(time, delta, frame, renderer, session);
		if (this.getRootNode().host) {
			for (const child of this.children) child.tick(time, delta, frame, renderer, session);
		}
	}
};

export const lightProxyType = Light;
export const lightProxyMixin = (baseClass) => class SHLightProxy extends objectProxyMixin(baseClass) {
	static name = 'LightProxy';
	static shortHandSchema = new Map([
		['target', {type: 'string', stage: STORED_ON_EL | REQUIRES_RECONSTRUCT }],
		['color', {type: 'Color'}],
		['intensity', {type: 'number'}]
	]);
};

export const materialProxyType = MeshPhysicalMaterial;
export const materialProxyMixin = (baseClass) => class SHMaterialProxy extends objectProxyMixin(baseClass) {
	static name = 'MaterialProxy';
	static shortHandSchema = new Map([
		['target', {type: 'string', stage: STORED_ON_EL | REQUIRES_RECONSTRUCT }],
	]);
	static documentation = documentationMaterial;
	async allAttributesChangedCallback() {
		if (!this.properties.target) throw Error('This proxy does not have a target: ', this);

		let object;
		const el = this.getRootNode().host;
		if (!el || !el.object) {
			return console.warn('Proxy could not find object in parent');
		} else {
			object = el.objectMaterials.get(this.properties.target);
		}

		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
};

export const animationProxyType = AnimationActionSymbol;
export const animationProxyMixin = (baseClass) => class SHAnimationProxy extends objectProxyMixin(baseClass) {
	static name = 'AnimationProxy';
	static shortHandSchema = shortHandSchema({
		'target': {type: 'string', stage: STORED_ON_EL | REQUIRES_RECONSTRUCT },
		'time-scale': {as: 'timeScale', stage: ASSIGNED_AFTER_CONSTRUCTION},
		'weight': {type: 'number', stage: ASSIGNED_AFTER_CONSTRUCTION},
		'paused': {default: true, stage: ASSIGNED_AFTER_CONSTRUCTION},
		't': {default: null, type: 'number', stage: STORED_ON_EL},
	});
	static documentation = documentationAnimation;
	async attributeChangedCallback(attr, oldValue, newValue, styleAttributeChange) {
		await super.attributeChangedCallback(attr, oldValue, newValue, styleAttributeChange);
		if (attr === 't') {
			if (newValue === null || newValue === undefined) {
				this.properties.t = null;
			}
			this.updateT();
		}
	}
	updateT() {
		if (this.object instanceof Promise) return;
		if (typeof this.properties.t === 'number') {
			this.object.play();
			this.object.time = this.properties.t * this.object._clip.duration;
		} else {
			this.object.stop();
		}
	}
	async allAttributesChangedCallback() {
		if (!this.properties.target) throw Error('This proxy does not have a target: ', this);
		const el = this.getRootNode().host;
		let object;
		if (el && el.object) {
			await el.object;
			object = el.objectAnimations.get(this.properties.target);
		}
		object.loop = LoopRepeat;
		object.play();
		this.updateT();
		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
};

export const instancedProxyType = InstancedMeshProxy;
const tempMatrix = new Matrix4();
export const instancedProxyMixin = (baseClass) => class SHInstancedProxy extends objectProxyMixin(baseClass) {
	static name = 'InstancedProxy';
	static shortHandSchema = new Map([
		['target', {type: 'InstancedMesh', stage: STORED_ON_EL | REQUIRES_RECONSTRUCT }],
		['index', {type: 'number', stage: STORED_ON_EL | REQUIRES_RECONSTRUCT }],
		['color', {type: 'Color'}],
	]);
	static documentation = documentationObject;
	async allAttributesChangedCallback() {
		if (!this.properties.target) throw Error('This proxy does not have a target: ', this);
		const instancedMesh = this.properties.target;
		const object = new InstancedMeshProxy({instancedMesh, instancedMeshInHeirarchy: true}, this.properties.index);
		instancedMesh.getMatrixAt(this.properties.index, tempMatrix);
		tempMatrix.decompose(object.position, object.quaternion, object.scale);
		object.matrix.copy(tempMatrix);
		await this.assignPostConstructAttributes(object);
		object.syncVectorChanges();
		object.updateMatrixWorld();
		this.updateObject(object);
	}
	tick(time, delta, frame, renderer, session) {
		super.tick(time, delta, frame, renderer, session);
		if (this.object.syncVectorChanges) this.object.syncVectorChanges();
	}
};
