// For supporting custom-elements that extend DOM elements in safari
import '@ungap/custom-elements';

import * as three from "./threebits.js";

import {
	registerShortHandElement,
	registeredElements,
	documentation,
	elementRegistry,
	patchElement
} from './customElementRegistration.js';

import {
	queryParts
} from './utils/utils.js';

import {
	register as registerMain
} from './core.js';

import {
	register as registerAddToParent
} from './features/addToParent.js';

import {
	register as registerHitTest
} from './features/hit-test.js';

import {
	register as registerStyleAttributeFeature,
	markAsDirty
} from "./features/style-attributes.js";

import {
	register as registerLinearConstraint
} from "./features/linear-constraint.js";

import {
	register as registerPlaneConstraint
} from "./features/plane-constraint.js";

import {
	register as registerDomHitboxes
} from "./features/dom-hitboxes.js";

import {
	register as registerBackgroundTexture
} from "./features/background-for-texture.js";

import {
	register as registerFog
} from "./features/fog.js";

import { register as registerDiorama } from './features/diorama.js';
import { register as registerMagnetConstraint } from './features/magnet-constraint.js';

import {
	register as registerPaths
} from "./features/paths/index.js";

import { register as registerHandGrab } from './features/hand-grab.js';

import { register as registerTransform, refreshTransform } from './features/transform.js';

import * as schema from './schema.js';
import { prettyPrintElement } from './utils/utils.js';

import { registerTemplateToElement } from "./components/use.js";
import { setDracoPath } from './utils/model-loaders.js';

function printDocs() {
	for (const {name, example, schema, className, documentation: docString} of documentation) {
		console.log('%c'+name, "font-size: 1.5em; font-weight: bold; font-decoration: underline;");
		console.log('%c'+example, "font-family: courier;");
		console.log(`This uses ${className} under the hood. ${docString || ''}`);
		console.table(schema);
	}
}

function elementCheck () {
	for (const el of document.querySelectorAll('*')) {
		const name = el.tagName.toLowerCase();
		if (name.indexOf('sh-') === 0) {
			if (!registeredElements.has(name)) {
				console.warn(`Element ${prettyPrintElement(el)} begins with "sh-" but is not defined by shorthand`);
			}
		}
	}
}

registerAddToParent(registerShortHandElement, schema);
registerFog(registerShortHandElement, schema);
registerTransform(registerShortHandElement, schema);
registerStyleAttributeFeature(registerShortHandElement, schema);
registerHitTest(registerShortHandElement, schema);
registerLinearConstraint(registerShortHandElement, schema);
registerPlaneConstraint(registerShortHandElement, schema);
registerMagnetConstraint(registerShortHandElement, schema);
registerDomHitboxes(registerShortHandElement, schema);
registerBackgroundTexture(registerShortHandElement, schema);
registerDiorama(registerShortHandElement, schema);
registerPaths(registerShortHandElement, schema);
registerHandGrab(registerShortHandElement, schema);

// Allow $0.dispatchEvent(new Event('click')) to trigger links in Chrome and Firefox
window.addEventListener('click', e=>e.target.closest('a')?.click());

let threeParts = {};
standalone: {
	registerMain(registerShortHandElement, schema); // do last
	elementCheck();
	threeParts = three;
}

export {
	ASSIGNED_AFTER_CONSTRUCTION,
	ASSIGNED_IN_CONSTRUCTOR,
	REQUIRES_RECONSTRUCT,
	STORED_ON_EL
} from "./schema.js";

export {
	registerMain as register,
	elementRegistry,
	schema,
	registeredElements,
	documentation,
	patchElement,
	registerShortHandElement,
	setDracoPath,
	printDocs,
	queryParts,
	elementCheck,
	markAsDirty,
	refreshTransform,
	registerTemplateToElement,
	threeParts,
	prettyPrintElement,
};
