const elementsToUpdate = [];

const observerA = new MutationObserver((mutations) => {
	for (const mutation of mutations) {
		const el = mutation.target;
		if (el.isShortHandElement) dirtyMap.set(el, true);
		for (const child$ of elementsToUpdate) {
			const child = child$.deref();
			if (child && child.isShortHandElement && el.contains(child)) {
				dirtyMap.set(child, true);
			}
		}
	}
});

const attributeFilter = ['class', 'slot', 'part', 'style'];
observerA.observe(document.firstElementChild, {
	attributes: true, subtree: true, attributeFilter
});

const unhandledAnimations = new WeakMap();
document.addEventListener('animationstart', (event) => {
	if (!event.shIsHandled) {
		if (unhandledAnimations.has(event.target)) {
			const oldValue = unhandledAnimations.get(event.target);
			oldValue[event.animationName] = (oldValue[event.animationName] || 0) + 1;
			unhandledAnimations.set(event.target, oldValue);
		} else {
			unhandledAnimations.set(event.target, {[event.animationName]:1});
		}
	}
});

// Will change isn't registered as an attribute because it is handled specially
window.CSS.registerProperty({
	name: '--will-change',
	syntax: '<custom-ident>+|none',
	inherits: false,
	initialValue: "none"
});

const dirtyMap = new WeakMap();
export function markAsDirty(el) {
	dirtyMap.set(el, true);

	// Trigger a style recalculation
	if (!el.ready) el.tick.call(el);
}

export function register (registerShortHandElement,  __schema) {
	const schemas = __schema.schemas;
	schemas.get(Object).get('mixins').push(baseclass => class extends baseclass {
		static name = 'StyleAttributes';
		static markAsDirty = markAsDirty;
		#styleAttributes = new Map();
		__shTrackedAttributes = new Set();
		#activelyTracked = [];
		#computedStyle = window.getComputedStyle(this);
		#currentlyAnimatingAttributes = new Map();

		constructor() {
			super();

			elementsToUpdate.push(new WeakRef(this));

			this.addEventListener('animationstart', (event) => {
				event.shIsHandled = true;
				if (event.target === this) {
					this.#updateCurrentlyAnimatingAttributeCount(event.animationName, +1);
				}
			}, {capture: true});

			if (unhandledAnimations.has(this)) for (const [animName, count] of Object.entries(unhandledAnimations.get(this))) {
				console.log('Adding unhandled animation: ', animName);
				this.#updateCurrentlyAnimatingAttributeCount(animName, count);
			}

			this.addEventListener('animationend', (event) => {
				if (event.target === this) {
					this.#updateCurrentlyAnimatingAttributeCount(event.animationName, -1);
				}
			});
			this.addEventListener('transitionstart', (event) => {
				if (event.target === this) {
					this.#updateCurrentlyTransitioningAttributeCount(event.propertyName, +1);
				}
			});
			this.addEventListener('transitionend', (event) => {
				if (event.target === this) {
					this.#updateCurrentlyTransitioningAttributeCount(event.propertyName, -1);
				}
			});

			if (this.shadowRoot) {
				observerA.observe(this.shadowRoot, {
					attributes: true, subtree: true, attributeFilter
				});
			} else {
				if (this.object instanceof Promise) this.object.then(() => {
					if (this.shadowRoot) {
						observerA.observe(this.shadowRoot, {
							attributes: true, subtree: true, attributeFilter
						});
					}
				});
			}
		}

		#updateCurrentlyTransitioningAttributeCount(attr, amount) {
			const name = attr.slice(2);
			if (this.constructor.observedAttributes.includes(name)) {
				const value = (this.#currentlyAnimatingAttributes.get(name) || 0) + amount;
				if (value > 0) {
					this.#currentlyAnimatingAttributes.set(name, value);
				} else if (value === 0) {
					this.#currentlyAnimatingAttributes.delete(name);
				} else {
					console.warn('Something has gone wrong lost count of animating attributes!');
					this.#currentlyAnimatingAttributes.delete(name);
				}
				this.#activelyTracked = [...this.__shTrackedAttributes, ...this.#currentlyAnimatingAttributes.keys()];
			}
		}

		// Cache this?
		#updateCurrentlyAnimatingAttributeCount(name, amount) {
			for (const style of [...this.getRootNode().styleSheets]) {
				const keyframeRules = Array.from(style.cssRules).filter(o => o instanceof CSSKeyframesRule);
				for (const keyframes of keyframeRules) {
					if (keyframes.name === name) {
						for (const keyframe of keyframes.cssRules) {
							for (const prop of keyframe.style) {
								this.#updateCurrentlyTransitioningAttributeCount(prop, amount);
							}
						}
					}
				}
			}
		}

		tick (time, delta, frame, renderer, session) {
			super.tick(time, delta, frame, renderer, session);
			this.#checkForStyleAttributeChange();
		}

		async attributeChangedCallback(attr, oldValue, newValue, fromStyleChange) {

			if (attr === 'will-change') {
				this.#updateStyleAttributes(newValue || '');
				this.#checkForStyleAttributeChange();
				return;
			}
	
			// If it's updated make sure it's not overriden in the stylesheet
			if (this.isConnected && fromStyleChange !== true) {
				const schema = this.constructor.shortHandSchema.get(attr);
				let valueFromCSS = this.#computedStyle.getPropertyValue('--' + attr)?.trim() || null;
				if (valueFromCSS === 'none' && typeof schema?.map?.none === "undefined") valueFromCSS = null;
				if (valueFromCSS) newValue = valueFromCSS;
			}

			if (fromStyleChange) {
				if (newValue === null) newValue = this.getAttribute(attr) || null;
				if (oldValue === newValue) return;
			}

			return super.attributeChangedCallback(attr, oldValue, newValue);
		}

		async connectedCallback() {

			for (const attr of this.constructor.observedAttributes) this.#styleAttributes.set(attr, this.getAttribute(attr) || null);
			this.#updateStyleAttributes(this.#computedStyle.getPropertyValue('--' + 'will-change') || this.getAttribute('will-change')?.trim() || '');
			for (const [attr, schemaEntry] of this.constructor.shortHandSchema.entries()) {
				let valueFromCSS = this.#computedStyle.getPropertyValue('--' + attr)?.trim() || null;
				if (valueFromCSS === 'none' && typeof schemaEntry?.map?.none === "undefined") valueFromCSS = null;
				if (valueFromCSS) {
					this.#styleAttributes.set(attr, valueFromCSS);
					if (this.ready) {
						this.attributeChangedCallback(attr, null, valueFromCSS, true);
					} else {
						let value = this.stringToValue(attr, valueFromCSS);
						if (value instanceof Promise) value = await value;
						if (this.ready) {
							this.attributeChangedCallback(attr, null, valueFromCSS, true);
						} else {
							this.populateConstructorHelper(attr, value);
						}
					}
				}
			}
			await super.connectedCallback();
		}

		#checkForStyleAttributeChange() {
			for (const attr of (dirtyMap.get(this) ? this.constructor.shortHandAttributes : this.#activelyTracked)) {
				if (!this.constructor.shortHandSchema.has(attr)) continue;
				let newValue = this.#computedStyle.getPropertyValue('--' + attr)?.trim() || null;

				const oldValue = this.#styleAttributes.get(attr);
				if (newValue !== oldValue) {
					this.#styleAttributes.set(attr, newValue);

					// If the CSS is set to 'none' and there is no override for that then
					// set it to null so that when it is handled by the HTML attribute change callback
					// it can fallback to the html attribute if there is one.
					if (newValue === 'none') {
						const schema = this.constructor.shortHandSchema.get(attr);
						if (typeof schema?.map?.none === "undefined") newValue = null;
					}
					this.attributeChangedCallback(attr, oldValue, newValue, true);
				}
			}
			dirtyMap.set(this, false);
		}

		#updateStyleAttributes(string) {
			if (string === 'none') string = '';
			this.__shTrackedAttributes.clear();
			for (const attr of string.split(/\s+/g).filter(b => !!b)) {
				this.__shTrackedAttributes.add(attr);
			}
			if (this.__shTrackedAttributes.has('all')) {
				this.__shTrackedAttributes.length = 0;
				for (const attr of this.constructor.shortHandAttributes) this.__shTrackedAttributes.add(attr);
			}
			this.#activelyTracked = [...this.__shTrackedAttributes, ...this.#currentlyAnimatingAttributes.keys()];
		}
	});
}

