import { CanvasTexture, EquirectangularReflectionMapping, Material, Scene, } from 'three';
import { defaultDocumentationMessage } from '../strings';
import { drawBackground } from '../utils/canvas-draw-background';
import { GroundedSkybox } from 'three/examples/jsm/objects/GroundedSkybox.js';

let documentation = defaultDocumentationMessage;
documentation: {
	documentation = `You can use things like linear-gradient or other CSS background properties for anything which take a texture`;
}

export function register (registerShortHandElement,  schema) {
	const schemas = schema.schemas;

	// Create new mixins
	const mixin = baseclass => class extends baseclass {
		static name = 'BackgroundTextures';
		static documentation = documentation;

		#canvasTexturesByAttribute = new Map();

		/**
		 * @param {string} attr 
		 * @returns {CanvasTexture}
		 */
		#getCanvasTexture(attr) {
			if (this.#canvasTexturesByAttribute.has(attr)) return this.#canvasTexturesByAttribute.get(attr);

			const canvas = document.createElement('canvas');
			canvas.width = 256;
			canvas.height = 256;
			const canvasTexture = new CanvasTexture(canvas);
			this.#canvasTexturesByAttribute.set(attr, canvasTexture);
			return canvasTexture;
		}

		stringToValue(attr, value) {
			const schemaEntry = this.constructor.getSchemaEntry(attr);
			const type = schemaEntry.type || typeof schemaEntry.default;
			let outValue = super.stringToValue(attr, value);

			if (type === 'Texture') {
				if (!outValue || outValue instanceof Promise) {
					return Promise.resolve(outValue).then(async outValue => {
						if (!outValue && attr) {
							const canvasTexture = this.#getCanvasTexture(attr);

							/** @type {CanvasTexture} */
							const canvas = canvasTexture.source.data;
							/** @type {CanvasRenderingContext2D} */
							const ctx = canvas.getContext('2d');
							ctx.fillStyle = 'white';
							ctx.fillRect(0,0,canvas.width, canvas.height);
							await drawBackground(canvas, value);
							canvasTexture.needsUpdate = true;

							if (attr === 'background-image' || attr === 'environment' || attr === 'environment-map') {
								canvasTexture.mapping = EquirectangularReflectionMapping;
							}

							return canvasTexture;
						} else {
							return outValue;
						}
					});
				}
				return outValue;
			} else {
				return outValue;
			}
		}
	};

	schemas.get(Material).get('mixins').push(mixin);
	schemas.get(Scene).get('mixins').push(mixin);
	schemas.get(GroundedSkybox).get('mixins').push(mixin);
}

