import { VideoTexture } from 'three';
export const type = VideoTexture;
export const name = 'VideoTexture';
export const native = {class: HTMLVideoElement, tagName: 'video'};
export const mixin = (baseClass) => class SHVideoTexture extends baseClass {
	static name = name;
	static canProxy = false;
	#metadataLoaded;
	constructor () {
		super();
		this.style.display = 'none';
		this.#metadataLoaded = new Promise(resolve => this.addEventListener('loadedmetadata', resolve, {once: true}));
	}
	async allAttributesChangedCallback() {
		await this.#metadataLoaded;
		const object = new VideoTexture(this);
		object.needsUpdate = true;
		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
};
