import { BufferAttribute, Vector2, Vector3 } from "three";
import { random8 } from "../../utils/utils";
/**
 * 
 * @param {BufferGeometry} geometry 
 * @returns 
 */
export function buildIndex( geometry , name = 'ExtrudedGeometry-' + random8() , inefficient = false) {
	if (geometry.index) return geometry;
	const posAttr = geometry.attributes.position;
	const normalAttr = geometry.attributes.normal;
	const colorAttr = geometry.attributes.color;
	const uvAttr = geometry.attributes.uv;

	if (inefficient) {
		const indices = new Array(posAttr.count).fill(1).map((i, j) => j);
		geometry.setIndex( indices );
		return geometry;
	}

	const hashMultiplier = ( 1 + 1e-10 ) * 1e2;
	const tempVertex = new Vector3();
	const normVector = new Vector3();

	// hashes a vector
	function hashVertex( v, n ) {

		const x = ~ ~ ( v.x * hashMultiplier );
		const y = ~ ~ ( v.y * hashMultiplier );
		const z = ~ ~ ( v.z * hashMultiplier );
		const xn = ~ ~ ( n.x * hashMultiplier );
		const yn = ~ ~ ( n.y * hashMultiplier );
		const zn = ~ ~ ( n.z * hashMultiplier );
		return `${x},${y},${z},${xn},${yn},${zn}`;

	}
	const vertices = [];
	const normals = [];
	const uvs = [];
	const colors = [];
	const indices = [];
	const vertexMap = {};

	for ( let i = 0, l = posAttr.count; i < l; i ++ ) {

		tempVertex.fromBufferAttribute( posAttr, i );
		
		if (normalAttr) {
			normVector.fromBufferAttribute( posAttr, i );
		} else {
			normVector.set(0,0,0);
		}

		const hash = hashVertex( tempVertex, normVector);
		if ( !( hash in vertexMap ) ) {
			const l = vertices.length;
			vertexMap[hash] = l;
			vertices[l] = new Vector3().fromBufferAttribute( posAttr, i );
			if (normalAttr) normals[l] = new Vector3().fromBufferAttribute(normalAttr, i);
			if (colorAttr) colors[l] = new Vector3().fromBufferAttribute(colorAttr, i);
			if (uvAttr) uvs[l] = new Vector2().fromBufferAttribute(uvAttr, i);
		}
		indices.push(vertexMap[hash]);
	}

	geometry.setIndex( indices );

	const positionBuffer = new Float32Array(vertices.length * 3);
	for ( let i = 0, l = vertices.length; i < l; i ++ ) {
		vertices[i].toArray(positionBuffer, i*3);
	}
	geometry.setAttribute( 'position', new BufferAttribute( positionBuffer, 3 ) );
	
	if (normalAttr) {
		const normalBuffer = new Float32Array(vertices.length * 3);
		for ( let i = 0, l = vertices.length; i < l; i ++ ) {
			normals[i].toArray(normalBuffer, i*3);
		}
		geometry.setAttribute( 'normal', new BufferAttribute( normalBuffer, 3 ) );
	}
	if (colorAttr) {
		const colorBuffer = new Float32Array(vertices.length * 3);
		for ( let i = 0, l = vertices.length; i < l; i ++ ) {
			colors[i].toArray(colorBuffer, i*3);
		}
		geometry.setAttribute( 'color', new BufferAttribute( colorBuffer, 3 ) );
	}
	if (uvAttr) {
		const uvBuffer = new Float32Array(vertices.length * 2);
		for ( let i = 0, l = vertices.length; i < l; i ++ ) {
			uvs[i].toArray(uvBuffer, i*2);
		}
		geometry.setAttribute( 'uv', new BufferAttribute( uvBuffer, 2 ) );
	}
	geometry.name = geometry.name || name;
	return geometry;
}
