import { Mesh, Raycaster, Vector3, Object3D, Quaternion } from 'three';
import { MeshBVH, acceleratedRaycast } from 'three-mesh-bvh';
import { STORED_ON_EL } from '../schema.js';
import { iteratorIncludes } from '../utils/utils.js';
import { mixins } from '../components/renderer.js';

export const POINTER_EVENTS_NONE = 0;
export const POINTER_EVENTS_VISIBLE = 1;
export const POINTER_EVENTS_ALL = 2;

export const pointerEventSchema = {as: 'pointerEvents', type: 'number', stage: STORED_ON_EL, map: {
	auto: POINTER_EVENTS_VISIBLE,
	visible: POINTER_EVENTS_VISIBLE,
	none: POINTER_EVENTS_NONE,
	all: POINTER_EVENTS_ALL
}};

export function register (registerShortHandElement,  schema) {
	const schemas = schema.schemas;
	const raycaster = new Raycaster();
	// raycaster.firstHitOnly = true;
	const tempQuaternion = new Quaternion();
	const raycastResults = [];

	const direction = new Vector3();
	const origin = new Vector3();

	const rendererMixin = baseclass => class extends baseclass {
		static shortHandSchema = new Map([
			['hit-test-enabled', {as: 'hitTestEnabled', default: true, stage: schema.STORED_ON_EL }]
		]);

		static shortHandEventDescriptions = {
			'renderer-mousedown': 'Fired when a 2d pointer starts a click-like activity',
			'renderer-mouseup': 'Fired when a 2d pointer ends a click-like activity',
			'renderer-mousemove': 'Fired when a 2d pointer moves over the canvas',
			'renderer-mousecancel': 'Fired when a 2d pointer leaves the canvas during an event',
		};

		static name = 'HitTest&Raycasting';
		#pointerDetails=new Map();


		constructor() {
			super();
			this.addEventListener('pointerenter', e => {
				if (e.target !== this) return;
				let detail = this.#pointerDetails.get(e.pointerId);
				if (!detail) {
					this.#pointerDetails.set(e.pointerId, this.#createScreenPointerDetails(e));
				}
			});
			this.addEventListener('pointerdown', e => {
				if (e.target !== this) return;

				const detail = this.#pointerDetails.get(e.pointerId) || this.#createScreenPointerDetails(e);
				this.#pointerDetails.set(e.pointerId, detail);
				if (detail) {
					detail.lastClickTime = Date.now();
					detail.clickStartX = detail.x;
					detail.clickStartY = detail.y;
					detail.button = e.button;
					let event;
					if (detail.el) event = detail.el.emit('shpointerdown', detail, true, false, true);
					if (!event || !event.defaultPrevented) this.emit('renderer-mousedown', detail);
				}
			}, {capture: true});
			this.addEventListener('pointermove', e => {
				const left = e.clientX - this.left;
				const top = e.clientY - this.top;
				const detail = this.#pointerDetails.get(e.pointerId) || this.#createScreenPointerDetails(e);
				if (detail) {
					detail.x = (left / this.width) * 2 - 1;
					detail.y = -(top / this.height) * 2 + 1;
					this.emit('renderer-mousemove', detail);
				}
			}, {capture: true});
			this.addEventListener('pointerup', e => {
				const detail = this.#pointerDetails.get(e.pointerId);
				if (detail) {
					if (detail.el) detail.el.emit('shpointerup', detail);
					this.emit('renderer-mouseup', detail);
					detail.button = null;
					if (Date.now() - detail.lastClickTime < 200 && detail.lastElementHovered) {
						detail.lastElementHovered.emit('click', detail);
					}
					detail.clickStartX = null;
					detail.clickStartY = null;
					// this.#pointerDetails.delete(e.pointerId);
				}
			});
			this.addEventListener('pointerleave', e => {
				const detail = this.#pointerDetails.get(e.pointerId);
				if (detail) {
					this.emit('renderer-mousecancel', detail);
					// this.#pointerDetails.delete(e.pointerId);
				}
			}, {capture: true});
			this.addEventListener('pointercancel', e => {
				const detail = this.#pointerDetails.get(e.pointerId);
				if (detail) {
					this.emit('renderer-mousecancel', detail);
					// this.#pointerDetails.delete(e.pointerId);
				}
			});

			this.addEventListener('selectstart', e => {
				if (!e.detail) return;
				const renderer = this.object;
				const referenceSpace = renderer.xr.getReferenceSpace();
				const {inputSource, frame} = e.detail;
				const targetRayPose = frame.getPose(inputSource.targetRaySpace, referenceSpace);
				if (!targetRayPose) return;
				origin.copy(targetRayPose.transform.position);
				direction.set(0, 0, -1).applyQuaternion(tempQuaternion.copy(targetRayPose.transform.orientation));
				raycaster.set(origin, direction);
				this.#raycastSceneChildren();
				const { object } = this.#getObjectFromRaycastResults();
				if (object) {
					const el = object.el;
					// console.log(`selectstart on ${prettyPrintElement(el)}`);
					const detail = {
						el,
						inputSource,
						isXRPointer: true,
						get lastElementHovered() {
							return this.lastElementHoveredRef?.deref() || null;
						},
						type: inputSource.targetRayMode,
						targetRayPose
					};
					el.emit('shpointerdown', detail);
					this.#pointerDetails.set(inputSource, detail);
				}
			});

			this.addEventListener('selectend', e => {
				const {inputSource, frame} = e.detail;
				if (this.#pointerDetails.has(inputSource)) {
					const renderer = this.object;
					const referenceSpace = renderer.xr.getReferenceSpace();
					const detail = this.#pointerDetails.get(inputSource);
					this.#pointerDetails.delete(inputSource);
					const targetRayPose = frame.getPose(inputSource.targetRaySpace, referenceSpace);
					if (targetRayPose) {
						origin.copy(targetRayPose.transform.position);
						direction.set(0, 0, -1).applyQuaternion(tempQuaternion.copy(targetRayPose.transform.orientation));
						raycaster.set(origin, direction);
						this.#raycastSceneChildren(detail.el.object);
						const { object } = this.#getObjectFromRaycastResults();
						if (object) {
							const el = object.el;
							el.classList.remove('hover');
							el.part.remove('hover');
							const host = el.getRootNode().host;
							if (host) {
								host.classList.remove('hover');
								host.part.remove('hover');
							}
							el.emit('shpointerup', detail);
							// console.log(`selectend on ${prettyPrintElement(el)}`);
							if (el === detail.el) {
								el.emit('click', detail);
							} else {
								// console.log('Element changed between selectstart and selectend');
							}
						}
					}
				}
			});
		}

		#createScreenPointerDetails(e) {
			const left = e.clientX - this.left;
			const top = e.clientY - this.top;
			const x = (left / this.width) * 2 - 1;
			const y = -(top / this.height) * 2 + 1;
			const camera = this.properties.camera;
			if (camera && camera.isPerspectiveCamera) {
				origin.setFromMatrixPosition(camera.matrixWorld);
				direction.set(x, y, 0.5).unproject(camera).sub(origin).normalize();
			} else if (camera && camera.isOrthographicCamera) {
				origin.set(x, y, (camera.near + camera.far) / (camera.near - camera.far)).unproject(camera); // set origin in plane of camera
				direction.set(0, 0, -1).transformDirection(camera.matrixWorld);
			}
			raycaster.set(origin, direction);
			this.#raycastSceneChildren();
			const out = {
				inputSource: Symbol(e.pointerId),
				identifier: e.pointerId,
				x,y,
				clickStartX: null,
				clickStartY: null,
				get lastElementHovered() {
					return this.lastElementHoveredRef?.deref() || null;
				},
				lastClickTime: 0,
				type: e.pointerType,
			};
			const { object } = this.#getObjectFromRaycastResults();
			if (object) {
				const el = object.el;
				out.el = el;
			}
			return out;
		}

		#raycastSceneChildren(priorityObject) {
			if (priorityObject) {
				raycastResults.length = 0;
				raycaster.intersectObject(priorityObject, false, raycastResults);
				if (raycastResults.length) return;
			}

			raycastResults.length = 0;
			for (const el of this.sceneChildren) {
				if (!el.object || typeof el.object.raycast !== 'function') continue;
				if (el.properties?.pointerEvents === POINTER_EVENTS_NONE) continue;
				if (el.properties?.pointerEvents === POINTER_EVENTS_VISIBLE && el.object.visible === false) continue;
				raycaster.intersectObject(el.object, false, raycastResults);
				if (raycastResults.length) return;
			}
		}

		#getObjectFromRaycastResults() {
			if (!raycastResults.length) return {};
			const result = raycastResults.find(result => {
				const object = result.object;
				let material = object.material;
				if (typeof result.face?.materialIndex === 'number' && material instanceof Array) {
					material = material[result.face.materialIndex];
				}

				if (material.visible === false) return false;

				// The material has clipping planes so make sure the point is in all of them
				const clippingPlanes = material.clippingPlanes;
				if (clippingPlanes) {
					return clippingPlanes.every(function (plane) {
						return plane.distanceToPoint(result.point) > 0;
					});
				}

				return true;
			});

			if (!result) return {};

			let object = result.object;
			while (object) {
				if (object.el) {
					break;
				} else {
					object = object.parent;
				}
			}
			return {object, result};
		}

		tick(time, delta, frame, renderer, session) {
			if (!this.properties.hitTestEnabled) {
				super.tick(time, delta, frame, renderer, session);
				return;
			}
			if (this.properties.scene.object && !(this.properties.scene.object instanceof Promise) && this.properties.camera) {
				for (const pointerDetail of this.#pointerDetails.values()) {
					let pointerRayHitEl=null;
					let shouldRayCast = false;
					const renderer = this.object;
					if (pointerDetail.isXRPointer) {
						if (frame) {
							const referenceSpace = renderer.xr.getReferenceSpace();
							const inputSource = pointerDetail.inputSource;
							const targetRayPose = frame.getPose(inputSource.targetRaySpace, referenceSpace);
							if (targetRayPose) {
								origin.copy(targetRayPose.transform.position);
								direction.set(0, 0, -1).applyQuaternion(tempQuaternion.copy(targetRayPose.transform.orientation));
								raycaster.set(origin, direction);
								shouldRayCast = true;
							} else {
								continue;
							}
						}
					} else if (!renderer.xr.isPresenting) {
						if (this.properties.camera && this.properties.camera.isPerspectiveCamera) {
							origin.setFromMatrixPosition(this.properties.camera.matrixWorld);
							direction.set(pointerDetail.x, pointerDetail.y, 0.5).unproject(this.properties.camera).sub(origin).normalize();
							shouldRayCast = true;
						} else if (this.properties.camera && this.properties.camera.isOrthographicCamera) {
							origin.set(pointerDetail.x, pointerDetail.y, (this.properties.camera.near + this.properties.camera.far) / (this.properties.camera.near - this.properties.camera.far)).unproject(this.properties.camera); // set origin in plane of camera
							direction.set(0, 0, -1).transformDirection(this.properties.camera.matrixWorld);
							shouldRayCast = true;
						}
					}

					if (shouldRayCast) {
						raycaster.set(origin, direction);
						this.#raycastSceneChildren();
						if (raycastResults.length) {
							const {object, result} = this.#getObjectFromRaycastResults();
							if (object) {
								const el = object.el;
								const host = object.el.getRootNode().host;
								if (el && iteratorIncludes(this.sceneChildren, host || el)) {
									pointerRayHitEl = el;
									pointerDetail.pointerRayHitPosition = result.point;
									if (pointerRayHitEl === pointerDetail.lastElementHovered) {
										pointerRayHitEl.emit('shpointermove', pointerDetail, true);
									}
								}
							}
						}
					}

					if (pointerRayHitEl !== pointerDetail.lastElementHovered) {
						const lastElementHoveredHost = pointerDetail.lastElementHovered?.getRootNode()?.host;
						const host = pointerRayHitEl?.getRootNode()?.host;
						if (pointerRayHitEl !== null) {
							pointerRayHitEl.emit('shpointerenter', pointerDetail);
							pointerRayHitEl.emit('shpointermove', pointerDetail, true);
							if (host) { // in shadow dom
								host.classList.add('hover');
								pointerRayHitEl.part.add('hover');
							} else { // in regular dom
								pointerRayHitEl.classList.add('hover');
							}
						}
						for (const child of this.sceneChildren) {
							if (child === lastElementHoveredHost || child === pointerDetail.lastElementHovered) {
								if (lastElementHoveredHost) { // in shadow dom
									if (lastElementHoveredHost !== host) lastElementHoveredHost.classList.remove('hover');
									pointerDetail.lastElementHovered.part.remove('hover');
									pointerDetail.lastElementHovered.emit('shpointerleave', pointerDetail);
								} else { // in regular dom
									child.classList.remove('hover');
									child.emit('shpointerleave', pointerDetail);
								}
							}
						}
						pointerDetail.lastElementHoveredRef = pointerRayHitEl ? new WeakRef(pointerRayHitEl) : null;
					}
				}
			}
			super.tick(time, delta, frame, renderer, session);
		}
	};

	const calcQueue = [];
	let isProcessing = false;
	Mesh.prototype.raycast = acceleratedRaycast;
	mixins.push(rendererMixin);
	schemas.get(Mesh).get('mixins').push(baseclass => class extends baseclass {
		static name='GeometryBVH';

		updateObject(...args) {
			super.updateObject(...args);
			const geom = (this.object.geometry || this.object.dummyGeometry );
			if (this.properties.pointerEvents !== 0 && !(this.noGeometryBVH) && geom && !geom.boundsTree && !geom.awaitingBoundsTree) {
				geom.awaitingBoundsTree = true;
				calcQueue.push(geom);
				if (!isProcessing) startProcessing();
			}
		}
	});

	function startProcessing() {
		isProcessing = true;
		if (calcQueue.length) {
			const geom = calcQueue.shift();
			geom.boundsTree = new MeshBVH( geom.el ? geom.el.object : geom, {});
			setTimeout(startProcessing, 50);
		} else {
			isProcessing = false;
		}
	}
	schemas.get(Object3D).get('mixins').push(baseclass => class extends baseclass {
		static name='HitTestEventDescriptions';
		static shortHandEventDescriptions = {
			'shpointerdown': 'Fired when a 2D or 3D pointer starts starts selecting over this element.',
			'shpointerup': 'Fired when a 2D or 3D pointer stops selecting over this element.',
			'shpointerenter': 'Fired when a 2D or 3D pointer starts hovering over this element.',
			'shpointerleave': 'Fired when a 2D or 3D pointer leaves hovering over this element.',
			'shpointermove': 'Fired eachframe while a 2D or 3D pointer starts hovering over this element.',
			'click': 'Fired when a 2D or 3D pointer does a selcet type action on an element'
		};
	});

	schemas.get(Object3D).set('pointer-events', pointerEventSchema);
}
