import { Matrix4, Box3, Vector3, Sphere, DirectionalLight, CameraHelper } from 'three';
import { STORED_ON_EL } from '../schema.js';
import { distanceOfPointFromPlane, nearestPointInPlane, querySelectorAllWithPartsLive } from '../utils/utils.js';

const bbox = new Box3();
const normal = new Vector3();
const cameraWorldPosition = new Vector3();
const tempMat = new Matrix4();
const sphere = new Sphere();
const tempVector = new Vector3();
export const type = DirectionalLight;
export const name = 'DirectionalLight';
export const mixin = (baseClass) => class SHDirectionalLight extends baseClass {
	static name = name;
	#shadowCameraAutomaticEls;
	#helper;
	static shortHandSchema = new Map([
		['shadow-radius', {as: 'shadow.radius', default: 2 }],
		['auto-shadow-focus', {as: 'autoShadow', default: true, stage: STORED_ON_EL}],
		['shadow-focus', {as: 'shadowCameraFocus', default: 'sh-object-proxy,sh-mesh:not([cast-shadow="false"]),sh-model:not([cast-shadow="false"])', stage: STORED_ON_EL}],
		['shadow-helper', {as: 'shadowCameraHelper', default: false,stage: STORED_ON_EL}],
	]);
	tick(time, delta, frame, renderer, session) {
		super.tick(time, delta, frame, renderer, session);
		if ( !this.ready || !this.properties.autoShadow ) return;

		const camera = this.object.shadow.camera;
		camera.getWorldDirection(normal);
		camera.getWorldPosition(cameraWorldPosition);
		tempMat.copy(camera.matrixWorld);
		tempMat.invert();

		if (this.properties.shadowCameraHelper) {
			if (!this.#helper) {
				this.#helper = new CameraHelper(this.object.shadow.camera);
				this.object.add(this.#helper);
			}
			this.#helper.visible = true;
		} else {
			if (this.#helper) {
				this.#helper.visible = false;
			}
		}

		camera.near = 1;
		camera.far = 5;
		camera.left = 100000;
		camera.right = -100000;
		camera.top = -100000;
		camera.bottom = 100000;
		this.#shadowCameraAutomaticEls.forEach(function (el) {
			if (!el.object || el.object instanceof Promise) return;
			bbox.setFromObject(el.object);
			bbox.getBoundingSphere(sphere);
			const distanceToPlane = distanceOfPointFromPlane(cameraWorldPosition, normal, sphere.center);
			const pointOnCameraPlane = nearestPointInPlane(cameraWorldPosition, normal, sphere.center, tempVector);

			const pointInXYPlane = pointOnCameraPlane.applyMatrix4(tempMat);
			camera.near = Math.min(-distanceToPlane - sphere.radius - 0.5, camera.near);
			camera.far = Math.max(-distanceToPlane + sphere.radius + 0.5, camera.far);
			camera.left = Math.min(-sphere.radius + pointInXYPlane.x, camera.left);
			camera.right = Math.max(sphere.radius + pointInXYPlane.x, camera.right);
			camera.top = Math.max(sphere.radius + pointInXYPlane.y, camera.top);
			camera.bottom = Math.min(-sphere.radius + pointInXYPlane.y, camera.bottom);
		});
		camera.updateProjectionMatrix();
		if (this.#helper) this.#helper.update();
	}
	async allAttributesChangedCallback() {
		await super.allAttributesChangedCallback();
		if (this.#shadowCameraAutomaticEls) this.#shadowCameraAutomaticEls.dispose();

		this.#shadowCameraAutomaticEls = querySelectorAllWithPartsLive(
			this.getRootNode().host?.shadowRoot || this.closest('sh-scene') || document,
			this.properties.shadowCameraFocus
		);
	}
};
