// Parts adapted from https://github.com/hughsk/svg-path-parser
import { parse as parse2d } from "./path2d.js";
import { parse as parse3d } from "./path3d.js";
import { CurvePath, LineCurve3, Vector3, CubicBezierCurve3, QuadraticBezierCurve3, EllipseCurve, Vector2, Shape } from "three";

// http://www.w3.org/TR/SVG11/implnote.html#PathElementImplementationNotes
function getReflection( a, b ) {
	return a - ( b - a );
}

function reflectVector(v, v0) {
	v.x = getReflection(v0.x, v.x);
	v.y = getReflection(v0.y, v.y);
	v.z = getReflection(v0.z, v.z);
	return v;
}


/**
 * https://github.com/mrdoob/three.js/blob/master/examples/jsm/loaders/SVGLoader.js#L700
 * https://www.w3.org/TR/SVG/implnote.html#ArcImplementationNotes
 * https://mortoray.com/2017/02/16/rendering-an-svg-elliptical-arc-as-bezier-curves/ Appendix: Endpoint to center arc conversion
 * From
 * rx ry x-axis-rotation large-arc-flag sweep-flag x y
 * To
 * aX, aY, xRadius, yRadius, aStartAngle, aEndAngle, aClockwise, aRotation
 */

function parseArcCommand( rx, ry, x_axis_rotation, large_arc_flag, sweep_flag, start, end ) {

	x_axis_rotation = x_axis_rotation * Math.PI / 180;

	// Ensure radii are positive
	rx = Math.abs( rx );
	ry = Math.abs( ry );

	// Compute (x1', y1')
	const dx2 = ( start.x - end.x ) / 2.0;
	const dy2 = ( start.y - end.y ) / 2.0;
	const x1p = Math.cos( x_axis_rotation ) * dx2 + Math.sin( x_axis_rotation ) * dy2;
	const y1p = - Math.sin( x_axis_rotation ) * dx2 + Math.cos( x_axis_rotation ) * dy2;

	// Compute (cx', cy')
	let rxs = rx * rx;
	let rys = ry * ry;
	const x1ps = x1p * x1p;
	const y1ps = y1p * y1p;

	// Ensure radii are large enough
	const cr = x1ps / rxs + y1ps / rys;

	if ( cr > 1 ) {

		// scale up rx,ry equally so cr == 1
		const s = Math.sqrt( cr );
		rx = s * rx;
		ry = s * ry;
		rxs = rx * rx;
		rys = ry * ry;

	}

	const dq = ( rxs * y1ps + rys * x1ps );
	const pq = ( rxs * rys - dq ) / dq;
	let q = Math.sqrt( Math.max( 0, pq ) );
	if ( large_arc_flag === sweep_flag ) q = - q;
	const cxp = q * rx * y1p / ry;
	const cyp = - q * ry * x1p / rx;

	// Step 3: Compute (cx, cy) from (cx', cy')
	const cx = Math.cos( x_axis_rotation ) * cxp - Math.sin( x_axis_rotation ) * cyp + ( start.x + end.x ) / 2;
	const cy = Math.sin( x_axis_rotation ) * cxp + Math.cos( x_axis_rotation ) * cyp + ( start.y + end.y ) / 2;

	// Step 4: Compute θ1 and Δθ
	const theta = svgAngle( 1, 0, ( x1p - cxp ) / rx, ( y1p - cyp ) / ry );
	const delta = svgAngle( ( x1p - cxp ) / rx, ( y1p - cyp ) / ry, ( - x1p - cxp ) / rx, ( - y1p - cyp ) / ry ) % ( Math.PI * 2 );

	// path.currentPath.absellipse( cx, cy, rx, ry, theta, theta + delta, sweep_flag === 0, x_axis_rotation );
	return [cx, cy,theta, delta, sweep_flag, x_axis_rotation];
}

function svgAngle( ux, uy, vx, vy ) {

	const dot = ux * vx + uy * vy;
	const len = Math.sqrt( ux * ux + uy * uy ) * Math.sqrt( vx * vx + vy * vy );
	let ang = Math.acos( Math.max( - 1, Math.min( 1, dot / len ) ) ); // floating point precision, slightly over values appear
	if ( ( ux * vy - uy * vx ) < 0 ) ang = - ang;
	return ang;

}

const parser = [
	parse2d, parse3d
];

export function pathToCurvePath(str, is3d=false) {
	return pathTo(str, is3d, false);
}

export function pathToShape(str) {
	return pathTo(str, false, true);
}

export function pathTo(str, is3d=false, isShape=false) {
	let outPath;
	let outShape;
	if (isShape) {
		if (is3d) throw Error('Shapes can\'t be 3d.');
		outShape = new Shape();
	} else {
		outPath = new CurvePath();
	}
	const parsed = makeSVGPathCommandsAbsolute(parser[is3d?1:0](str));
	const cubicBezierCachedControl = new Vector3();
	let cubicBezierCachedControlValid = 0;
	const quadraticBezierCachedControl = new Vector3();
	let quadraticBezierCachedControlValid = 0;
	for (const {code,x,y,z=0,x0,y0,z0=0,x1,y1,z1,x2,y2,z2,largeArc,sweep,xAxisRotation,rx,ry} of parsed) {
		if (code === 'M') {
			if (outShape) outShape.moveTo(x, y);
		}
		if (code === 'L' || code === 'V' || code === 'H' || code === 'Z') {
			if (outPath) {
				const v0 = new Vector3(x0,y0,z0);
				const v = new Vector3(x,y,z);
				outPath.add(new LineCurve3(v0, v));
			}
			if (outShape) outShape.lineTo(x,y);
		}
		if (code === 'C') {
			if (outPath) {
				outPath.add(new CubicBezierCurve3(
					new Vector3(x0,y0,z0),
					new Vector3(x1,y1,z1),
					new Vector3(x2,y2,z2),
					new Vector3(x,y,z)
				));
			}
			if (outShape) {
				outShape.bezierCurveTo(x1,y1, x2,y2, x,y);
			}
			cubicBezierCachedControl.set(x2,y2,z2);
			cubicBezierCachedControlValid = 2;
		}
		if (code === 'S') {
			const v0 = new Vector3(x0,y0,z0);
			const v1 = cubicBezierCachedControlValid ? reflectVector(cubicBezierCachedControl.clone(),v0) : new Vector3(x0,y0,z0);
			if (outPath) {
				outPath.add(new CubicBezierCurve3(
					v0,
					v1,
					new Vector3(x2,y2,z2),
					new Vector3(x,y,z)
				));
			}
			if (outShape) {
				outShape.bezierCurveTo(v1.x,v1.y, x2,y2, x,y);
			}
			cubicBezierCachedControl.set(x2,y2,z2);
			cubicBezierCachedControlValid = 2;
		}
		if (code === 'Q') {
			quadraticBezierCachedControl.set(x1,y1,z1);
			quadraticBezierCachedControlValid = 2;
			if (outPath) {
				outPath.add(new QuadraticBezierCurve3(
					new Vector3(x0,y0,z0),
					new Vector3(x1,y1,z1),
					new Vector3(x,y,z)
				));
			}
			if (outShape) {
				outShape.quadraticCurveTo(x1,y1, x,y);
			}
		}
		if (code === 'T') {
			const v0 = new Vector3(x0,y0,z0);
			const v1 = quadraticBezierCachedControlValid ? reflectVector(quadraticBezierCachedControl.clone(),v0) : v0.copy();
			if (outPath) {
				const v = new Vector3(x,y,z);
				outPath.add(new QuadraticBezierCurve3( v0, v1, v));
			}
			if (outShape) {
				outShape.quadraticCurveTo(v1.x,v1.y, x,y);
			}
			quadraticBezierCachedControl.copy(v1);
			quadraticBezierCachedControlValid = 2;
		}
		if (code === 'A') {
			if (is3d) throw Error('A command is not valid in 3D path');
			if ( rx == 0 || ry == 0 ) {
				if (outPath) outPath.add(new LineCurve3(new Vector2(x0,y0,z0), new Vector2(x,y,z)));
				if (outShape) outShape.lineTo(x, y);
			} else {
				const [cx, cy, theta, delta, sweep_flag, x_axis_rotation] = parseArcCommand(rx, ry, xAxisRotation, largeArc, sweep, new Vector2(x0,y0), new Vector2(x,y));
				if (outPath) outPath.add(new EllipseCurve(cx, cy, rx, ry, theta, theta + delta, !sweep_flag, x_axis_rotation));
				if (outShape) outShape.absellipse(cx, cy, rx, ry, theta, theta + delta, !sweep_flag, x_axis_rotation);
			}
		}
		if (cubicBezierCachedControlValid > 0) cubicBezierCachedControlValid--;
		if (quadraticBezierCachedControlValid > 0) quadraticBezierCachedControlValid--;
	}
	return outPath || outShape;
}

function makeSVGPathCommandsAbsolute(commands) {
	var subpathStart, prevCmd={x:0,y:0};
	var attr = {x:'x0',y:'y0',z:'z0',x1:'x0',y1:'y0',z1:'z0',x2:'x0',y2:'y0',z2:'z0'};
	commands.forEach(function(cmd) {
		if (cmd.command==='moveto') subpathStart=cmd;
		cmd.x0=prevCmd.x; cmd.y0=prevCmd.y; cmd.z0=prevCmd.z || 0;
		for (var a in attr) if (a in cmd) cmd[a] += cmd.relative ? cmd[attr[a]] : 0;
		if (!('x' in cmd)) cmd.x = prevCmd.x;
		if (!('y' in cmd)) cmd.y = prevCmd.y;
		if (!('z' in cmd)) cmd.z = prevCmd.z || 0;
		cmd.relative = false;
		cmd.code = cmd.code.toUpperCase();
		if (cmd.command=='closepath') {
			cmd.x = subpathStart.x;
			cmd.y = subpathStart.y;
			cmd.z = subpathStart.z || 0;
		}
		prevCmd = cmd;
	});
	return commands;
}


