import { Object3D, Quaternion, Vector2, Vector3 } from 'three';
import { defaultDocumentationMessage } from '../strings.js';
import { clamp, shortHandSchema } from '../utils/utils.js';
import { refreshTransform } from './transform.js';

let documentation = defaultDocumentationMessage;
documentation: {

	// Add any documentation for the README in here perhaps describe what attributes are optional
	// or how to use it.
	documentation = `Magnet constraint changes the position and rotation of the object to move closer to the target when it approaches the target.`;
}

export function register (registerShortHandElement,  schema) {
	const schemas = schema.schemas;
	const tempVector3A = new Vector3();
	const tempVector3B = new Vector3();
	const shortestVector = new Vector3();
	const tempQuaternionA = new Quaternion();
	const tempQuaternionB = new Quaternion();
	const tempQuaternionC = new Quaternion();
	const defaultRange = new Vector2(0.1, 0);
	schemas.get(Object3D).get('mixins').push(baseclass => class extends baseclass {
		static shortHandSchema = shortHandSchema({
			'magnet-constraint-target': { as: 'magnetConstraintTarget', default: [], type: 'Elements', stage: schema.STORED_ON_EL },
			'magnet-constraint-range': { as: 'magnetConstraintRange', type: 'Vector2', stage: schema.STORED_ON_EL },
		});
		static name = 'MagnetConstraint';
		static documentation=documentation;

		static shortHandEventDescriptions = {
			'magnet-connect': 'Fired when the attracting object and the magnet object connect fully, this may not fire if the magnet behaviour is removed whilst they are not connected',
			'magnet-disconnect': 'Fired when the attracting object and the magnet are no longer fully connected, this may not fire if the magnet behaviour is removed whilst they are connecting',
		};
	
		#currentTarget = null;
		#isActive = false;
		#markTarget(el) {
			if (this.#isActive !== true) {
				this.#isActive = true;
				if (this.getRootNode().host) this.part.add('magnet-constraint-active');
				this.classList.add('magnet-constraint-active');
			}
			if (this.#currentTarget !== el) {
				this.#clearTarget();
				this.#currentTarget = el;
				if (el.getRootNode().host) el.part.add('magnet-constraint-target');
				el.classList.add('magnet-constraint-target');
			}
		}

		#clearTarget() {
			if (this.#isActive !== false) {
				this.#isActive = false;
				if (this.getRootNode().host) this.part.remove('magnet-constraint-active');
				this.classList.remove('magnet-constraint-active');
			}
			if (this.#currentTarget !== null) {
				const el = this.#currentTarget;
				this.#currentTarget = null;
				if (el.getRootNode().host) el.part.remove('magnet-constraint-target');
				el.classList.remove('magnet-constraint-target');
			}
		}

		#currentMagnetConstraintTarget;
		*#targets () {
			if (this.#currentMagnetConstraintTarget !== this.properties.magnetConstraintTarget) {
				this.#currentMagnetConstraintTarget = this.properties.magnetConstraintTarget;
				this.#currentTarget = null;
			}
			if (this.#currentTarget) yield this.#currentTarget;
			return yield * this.properties.magnetConstraintTarget;
		}

		#prevT;
		tick(time, delta, frame, renderer, session) {
			super.tick(time, delta, frame, renderer, session);
			
			const object = this.object;
			const {x:range,y:falloff} = (this.properties.magnetConstraintRange || defaultRange);
			if (
				!object || object instanceof Promise ||
				!this.properties.magnetConstraintTarget ||
				(!this.#currentTarget && this.properties.magnetConstraintTarget.length === 0)
			) return this.#clearTarget();

			refreshTransform(this);

			// For the case of multiple targets pick the closest point.
			let closestD = Infinity;
			let target;
			for (const testTarget of this.#targets()) {
				if (testTarget.object instanceof Object3D) {
					if (testTarget.parent && testTarget.parent === object.parent) {
						tempVector3B.copy(testTarget.object.position);
					} else {
						object.parent.worldToLocal(testTarget.object.getWorldPosition(tempVector3A));
						tempVector3B.copy(object.position);
					}
					const distance = tempVector3A.sub(tempVector3B).length();
					if (distance < closestD) {
						shortestVector.copy(tempVector3A);
						closestD = distance;
						target = testTarget.object;
					}
				}
			}

			if (closestD < range) {
				this.#markTarget(target.el);
				const p = object.parent;
				const t = clamp((1-(closestD/range))*(1/(1-clamp(falloff/range,0,0.9999))),0,1);
				if (t===1 && this.#prevT !== 1) {
					const el = target.el;
					this.emit('magnet-connect', {
						target: el,
						magnet: this
					});
					el.emit('magnet-connect', {
						target: el,
						magnet: this
					});
				}
				if (t!==1 && this.#prevT === 1) {
					const el = target.el;
					this.emit('magnet-disconnect', {
						target: el,
					});
					el.emit('magnet-disconnect', {
						target: el,
					});
				}
				this.#prevT = t;
				p.worldToLocal(target.getWorldPosition(tempVector3A));
				tempVector3B.copy(object.position);
				tempVector3A.lerp(tempVector3B, 1-t).sub(tempVector3B);
				
				p.getWorldQuaternion(tempQuaternionC).invert();
				target.getWorldQuaternion(tempQuaternionA).premultiply(tempQuaternionC);
				tempQuaternionB.copy(object.quaternion);
				tempQuaternionA.slerp(tempQuaternionB, 1-t).multiply(tempQuaternionB.invert());
				object.applyQuaternion(tempQuaternionA);
				object.position.add(tempVector3A);
			} else {
				this.#clearTarget();
			}
		}
	});
}

