/* This will behave like the regular <sh-mesh> except ones which share a geometry and a material will be instanced */
import { ASSIGNED_AFTER_CONSTRUCTION, REQUIRES_RECONSTRUCT, STORED_ON_EL, materialMap, schemas } from '../schema.js';
import { Matrix4, Quaternion, Vector3, InstancedMesh, Object3D, Color, Mesh } from 'three';
import { defaultDocumentationMessage } from '../strings.js';

const tempPosition = new Vector3();
const tempScale = new Vector3();
const tempMatrix = new Matrix4();
const tempMatrix2 = new Matrix4();
const tempQuaternion = new Quaternion();
const tempColor = new Color('white');
const tempColorA = new Color('white');
const tempColorB = new Color('white');
const raycastResults = [];

// Map <Geometry, Map <Material, InstancedMesh>>
const instanceMap = new Map();
export async function getNewInstancedMesh(geometry, material, scene) {
	let instancedMeshDescription, materialMap, index;
	let createNewMesh = false;
	materialMap = instanceMap.get(geometry);
	if (materialMap) {
		instancedMeshDescription = materialMap.get(material);
		if (!instancedMeshDescription) {
			createNewMesh = true;
		}
	} else {
		materialMap = new Map();
		instanceMap.set(geometry, materialMap);
		createNewMesh = true;
	}

	if (createNewMesh) {
		instancedMeshDescription = {
			instancedMesh: new InstancedMesh(geometry, material, 1),
			slots: [true]
		};
		tempPosition.set(0,0,0);
		tempMatrix.compose(tempPosition, tempQuaternion, tempPosition);
		instancedMeshDescription.instancedMesh.setMatrixAt(0, tempMatrix);
		instancedMeshDescription.instancedMesh.setColorAt(0, tempColor);
		index = 0;
		materialMap.set(material, instancedMeshDescription);
	} else {
		index = instancedMeshDescription.slots.indexOf(false);

		// If there are no empty slots then increase the size and make a new one
		if (index === -1) {
			index = instancedMeshDescription.slots.length;
			instancedMeshDescription.slots[index] = true;

			// Wait for all new elementst to do their things before generating the instanced mesh so that it doesn't
			// get done many times in a row which is expensive.
			await new Promise (r => queueMicrotask(() => {
				if (instancedMeshDescription.slots.length > instancedMeshDescription.instancedMesh.count ) {
					scene.remove(instancedMeshDescription.instancedMesh);
					const oldInstancedMesh = instancedMeshDescription.instancedMesh;
					const oldLength = oldInstancedMesh.count;
					instancedMeshDescription.instancedMesh = new InstancedMesh(geometry, material, instancedMeshDescription.slots.length);
					console.log(instancedMeshDescription.instancedMesh.count);
					instancedMeshDescription.instancedMesh.setColorAt(0, tempColor);
					// Copy the old array into the new one
					instancedMeshDescription.instancedMesh.instanceMatrix.array.set(oldInstancedMesh.instanceMatrix.array);
					instancedMeshDescription.instancedMesh.instanceColor.array.set(oldInstancedMesh.instanceColor.array);
					instancedMeshDescription.instancedMesh.receiveShadow = oldInstancedMesh.receiveShadow;
					instancedMeshDescription.instancedMesh.castShadow = oldInstancedMesh.castShadow;
					tempPosition.multiplyScalar(0);
					tempMatrix.compose(tempPosition, tempQuaternion, tempPosition);
					for (let i=oldLength;i<instancedMeshDescription.slots.length;i++) {
						instancedMeshDescription.instancedMesh.setMatrixAt(i, tempMatrix);
					}
					instancedMeshDescription.instancedMesh.instanceMatrix.needsUpdate = true;
					oldInstancedMesh.dispose();
				}
				r();
			}));
		}
	}

	scene.add(instancedMeshDescription.instancedMesh);

	return [instancedMeshDescription, index];
}

function clearInstancedMesh(scene, geometry, material, index) {
	let instancedMeshDescription, materialMap;
	materialMap = instanceMap.get(geometry);
	if (materialMap) {
		instancedMeshDescription = materialMap.get(material);
		if (instancedMeshDescription) {
			instancedMeshDescription.slots[index] = false;
			if (!instancedMeshDescription.slots.includes(true)) {
				materialMap.delete(material);
				scene.remove(instancedMeshDescription.instancedMesh);
				instancedMeshDescription.instancedMesh.dispose();
			} else {
				// There are other instances still around so just make this one invisible
				instancedMeshDescription.instancedMesh.getMatrixAt(index, tempMatrix);
				tempMatrix.decompose(tempPosition, tempQuaternion, tempScale);
				tempScale.set(0,0,0);
				tempMatrix.compose(tempPosition, tempQuaternion, tempScale);
				instancedMeshDescription.instancedMesh.setMatrixAt(index, tempMatrix);
				instancedMeshDescription.instancedMesh.instanceMatrix.needsUpdate = true;
			}
		}
	}
}

let documentation = defaultDocumentationMessage;
documentation:
{
	documentation = `This element is similar to sh-mesh but lets you reuse the same geometry and material many times, you can also set the color on the same mesh.`;
}

class ColorProxy {
	#instancedMeshDescription;
	#index;
	r=0;
	g=0;
	b=0;
	constructor(instancedMeshDescription, index) {
		this.#instancedMeshDescription = instancedMeshDescription;
		this.#index = index;
	}
	copy(color) {
		this.r = color.r;
		this.g = color.g;
		this.b = color.b;
		this.#instancedMeshDescription.instancedMesh.setColorAt(this.#index, color);
		this.#instancedMeshDescription.instancedMesh.instanceColor.needsUpdate = true;
	}
	lerpColors(color1, color2, alpha) {
		this.#instancedMeshDescription.instancedMesh.getColorAt(this.#index, tempColor);
		tempColor.lerpColors(tempColorA.copy(color1), tempColorB.copy(color2), alpha);
		this.copy(tempColor);
	}
}

export class InstancedMeshProxy extends Object3D {
	instancedMeshDescription;
	isInstancedMeshProxy = true;
	#index;
	#meshForHitTest;
	#previousMatrixWorld = new Matrix4();
	constructor (instancedMeshDescription, index, scene) {
		super();
		this.instancedMeshDescription = instancedMeshDescription;
		const color = new ColorProxy(instancedMeshDescription, index);
		this.material = instancedMeshDescription.instancedMesh.material;
		this.geometry = instancedMeshDescription.instancedMesh.geometry;
		this.#meshForHitTest = new Mesh(this.geometry, this.material);
		this.#index = index;
		this.scene = scene;
		Object.defineProperties( this, {
			color: {
				configurable: false,
				enumerable: true,
				value: color
			},
		});
	}
	add() {
		throw Error('This isn\'t a real mesh it cannot have child elements.');
	}
	removeFromParent() {
		// clearInstancedMesh(this.scene, this.geometry, this.material, this.#index);
	}
	dispose() {
		clearInstancedMesh(this.scene, this.geometry, this.material, this.#index);
	}
	set receiveShadow(value) {
		if (this.instancedMeshDescription) {
			this.instancedMeshDescription.instancedMesh.receiveShadow = value;
		}
	}
	set castShadow(value) {
		if (this.instancedMeshDescription) {
			this.instancedMeshDescription.instancedMesh.castShadow = value;
		}
	}
	raycast(raycaster, intersects) {
		// calculate the world matrix for each instance
		const instancedMesh = this.instancedMeshDescription.instancedMesh;

		if (this.instancedMeshDescription.instancedMeshInHeirarchy) {
			this.#meshForHitTest.matrixWorld.copy(this.matrixWorld);
		} else {
			instancedMesh.getMatrixAt( this.#index, this.#meshForHitTest.matrixWorld );
		}
		this.#meshForHitTest.raycast( raycaster, raycastResults );

		for ( let i = 0, l = raycastResults.length; i < l; i ++ ) {
			const intersect = raycastResults[ i ];
			intersect.object = this;
			intersects.push( intersect );
		}

		raycastResults.length = 0;
	}
	syncVectorChanges() {
		const im = this.instancedMeshDescription.instancedMesh;
		for (let i=0; i<16; i++) {
			if (this.#previousMatrixWorld.elements[i] !== this.matrixWorld.elements[i]) {
				let matrixToStore = tempMatrix;
				if (this.instancedMeshDescription.instancedMeshInHeirarchy) {
					if (this.parent.uuid === im.uuid) {
						matrixToStore = this.matrix;
					} else {
						tempMatrix.copy(this.matrixWorld).premultiply(tempMatrix2.copy(im.matrixWorld).invert());
					}
				} else {
					matrixToStore = this.matrixWorld;
				}
				im.setMatrixAt( this.#index, matrixToStore );
				im.instanceMatrix.needsUpdate = true;
				im.computeBoundingSphere();
				this.#previousMatrixWorld.copy(this.matrixWorld);
				break;
			}
		}
	}
}

export const type = Mesh;
export const name = 'InstancedMesh';
export const mixin = (baseClass) => class SHInstancedMesh extends baseClass {
	static name = name;
	static shortHandSchema = new Map([
		["color", {type: "Color", default: 'white', stage: ASSIGNED_AFTER_CONSTRUCTION }],
		["mesh", {type: "Mesh", stage: STORED_ON_EL | REQUIRES_RECONSTRUCT }],
		["geometry", {type: "BufferGeometry", stage: STORED_ON_EL | REQUIRES_RECONSTRUCT, map: schemas.get(Mesh).get('geometry').map }],
		["material", {type: "Material", stage: STORED_ON_EL | REQUIRES_RECONSTRUCT, map: materialMap }],
		["scene", {type: "Scene", stage: STORED_ON_EL | REQUIRES_RECONSTRUCT }],
	]);
	static documentation = documentation;
	tick(time, delta, frame, renderer, session) {
		super.tick(time, delta, frame, renderer, session);
		if (this.ready) this.object.syncVectorChanges();
	}
	async allAttributesChangedCallback() {
		let geometry, material;
		if (this.properties.mesh) {
			geometry = this.properties.mesh.geometry;
			material = this.properties.mesh.material;
		} else {
			geometry = this.properties.geometry;
			material = this.properties.material;
		}

		if (!geometry) {
			console.warn('Geometry is not defined');
			console.log(this);
			return;
		}

		const scene = this.properties.scene || await this.closest('sh-scene').object;
		const [instancedMeshDescription, index] = await getNewInstancedMesh(geometry, material, scene);
		const object = new InstancedMeshProxy(instancedMeshDescription, index, scene);

		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
		this.object.syncVectorChanges();
	}
};
