import { BufferGeometry, CylinderGeometry, Group, Line, LineBasicMaterial, Mesh, MeshPhongMaterial, Object3D, Quaternion, Vector3, WebGLRenderer } from 'three';
import { IterableWeakMap, shortHandSchema } from '../utils/utils.js';
import {held, grabbables} from '../components/select-grab.js';
export function register (registerShortHandElement,  schema) {
	const schemas = schema.schemas;
	const SHOW_DEBUG_LINES = false;

	const tempVector3A = new Vector3();
	const tempVector3B = new Vector3();
	const tempVector3C = new Vector3();
	const tempQuaternion = new Quaternion();
	const worldPosition = new Vector3();
	const worldQuaternion = new Quaternion();
	const zeroVector = new Vector3();

	const previewMaterial = new MeshPhongMaterial();
	const cylinderGeom = new CylinderGeometry(1,1,1,32,1,false);
	const yVector3 = new Vector3(0,1,0);

	const gripperVector = new Vector3();
	const grabbableCenter = new Vector3();
	const shortestPathVector = new Vector3();
	const n = new Vector3();
	const pMinusP = new Vector3();
	const d1 = new Vector3();
	const c1 = new Vector3();
	const c2 = new Vector3();

	const grippers = new IterableWeakMap();
	/**
	 @typedef HandHoldDetail
		@type {Object}
		@property {Vector3} worldPosA position of one gripper poing
		@property {Vector3} worldPosB position of second gripper point
		@property {Object3D} currentParent object which currently contains the held objectß
	*/

	/**
	 * @type {Map<HTMLElement, HandHoldDetail>} Element being held, Holding Element
	 */
	const detailMap = new IterableWeakMap();

	let comboCached = [];

	/*
	 * Creates an array of pairs of grippers so that it has a,b a,c b,c but not a,a or b,a
	 */
	function updateComboCache() {
		const array = Array.from(grippers.entries());
		comboCached = array.flatMap(([gripperA, positionA], i) => array.slice(i+1).map( ([gripperB, positionB]) => [positionA,positionB, gripperA, gripperB] ));
	}


	// https://en.wikipedia.org/wiki/Skew_lines#Nearest_Points
	// vectorA and vectorB are in world coordinates
	function intersects(el, vectors, pinchPointDest) {
		const vectorA = vectors[0];
		const vectorB = vectors[1];

		const radius = el.properties.grabRadius;
		const d2 = gripperVector.subVectors(vectorB, vectorA);
		const fingerDistance = d2.length();
		if (fingerDistance > radius) return false; // If the fingers are not close enough together to actually interact with el object then bail
		d2.normalize();
		
		el.object.updateWorldMatrix( true, false );
		el.object.matrixWorld.decompose(worldPosition, worldQuaternion, tempVector3A);

		if (SHOW_DEBUG_LINES) {
			hideLine(vectors, 'yellow');
			hideLine(vectors, 'green');
		}

		const length = el.properties.grabLength;
		d1.copy(el.properties.grabDirection).normalize().applyQuaternion(tempQuaternion.copy(worldQuaternion));
		const grabOffset = el.properties.grabOffset;

		shortestPathVector.crossVectors(d1, d2);

		const p1 = grabbableCenter.copy(grabOffset || zeroVector).applyMatrix4(el.object.matrixWorld);
		const p2 = vectorA;

		if (SHOW_DEBUG_LINES) {
			updateLine(el, 'red', tempVector3A.copy(p1).addScaledVector(d1, length/2), tempVector3B.copy(p1).addScaledVector(d1, -1 * length/2));
		}

		// working out c1 (point on cylinder)
		n.crossVectors(d2, shortestPathVector);
		if (!n.lengthSq()) return;
		pMinusP.subVectors(p2, p1);
		const t1 = pMinusP.dot(n)/d1.dot(n);
		c1.copy(p1).addScaledVector(d1, t1);

		// if it is vertically outside the cylinder return false
		if (Math.abs(t1) > length/2) return false;

		// working out c2 (point between fingers)
		n.crossVectors(d1, shortestPathVector);
		if (!n.lengthSq()) return;
		pMinusP.subVectors(p1, p2);
		const t2 = pMinusP.dot(n)/d2.dot(n);
		c2.copy(p2).addScaledVector(d2, t2);

		if (t2 < -radius || t2 > fingerDistance + radius) return false; 

		// if the line between the two fingers doesn't intersect the cylinder then bail
		const d = tempVector3A.subVectors(c1, c2).length();
		if (d > radius) return false;

		if (SHOW_DEBUG_LINES) {
			updateLine(vectors, 'green', c1, c2);
			updateLine(vectors, 'yellow', vectorA, vectorB);
		}

		if (pinchPointDest) el.object.worldToLocal(pinchPointDest.copy(c2));
		return true;
	}


	schemas.get(WebGLRenderer).get('mixins').push(baseclass => class extends baseclass {
		static name = 'GrabberSystem';
		tick(time, delta, frame, renderer, session) {
			super.tick(time, delta, frame, renderer, session);

			for (const [grabbable, oldParent] of held) {
				if (!detailMap.has(grabbable)) continue;
				const {worldPosA, worldPosB, currentParent} = detailMap.get(grabbable);

				// hideLine(grabbable, 'magenta');
				if (worldPosA.distanceTo(worldPosB) > grabbable.properties.grabRadius) {
					held.delete(grabbable);
					detailMap.delete(grabbable);
					grabbable.classList.remove('held');
					grabbable.part.remove('held');
					grabbable.shReparent(oldParent);
					currentParent.removeFromParent();
					grabbable.emit('grabend', { holdingParent: this.object, realParent: oldParent });
					if (grabbable.getRootNode().host) {
						grabbable.getRootNode().host.emit('grabend', { part: grabbable, holdingParent: this.object, realParent: oldParent });
					}
				} else {

					if (SHOW_DEBUG_LINES) {
						// This shows that using the comparitive position of the grip points to do rolling isn't really feasible.
						tempVector3C.subVectors(worldPosB, worldPosA).normalize();
						tempVector3A.copy(worldPosA).addScaledVector(tempVector3C, -0.05);
						tempVector3B.copy(worldPosB).addScaledVector(tempVector3C, 0.05);
						updateLine(grabbable, 'magenta', tempVector3A, tempVector3B );
					}
				}
			}

			for (const combo of comboCached) {
				for (const [grabbable, grabTarget] of grabbables) {
					if (grabTarget>=0 && grabbable.properties.grabOffset) {
						const worldPosA = combo[0];
						const worldPosB = combo[1];
						const gripperA = combo[2];
						const outValue = tempVector3A;
						if (!held.has(grabbable) && intersects(grabbable, combo, outValue)) {
							let el = grabbable;
							for (let i=0; i<grabbables.get(grabbable); i++) el=el.parentNode;
							const realParentObject = held.get(el) || el.object.parent;
	
							const holdingParent = new Group();
							gripperA.object.add(holdingParent);
							gripperA.object.worldToLocal(holdingParent.position.copy(outValue));

							const details =  { worldPosA, worldPosB, currentParent: holdingParent };
							held.set(el, realParentObject);
							detailMap.set(el, details);
							el.classList.add('held');
							el.shReparent(holdingParent);
							if (el.getRootNode().host) {
								el.part.add('held');
								el.getRootNode().host.emit('grabstart', { part: el, holdingParent: this.object, realParent: realParentObject });
							}
							el.emit('grabstart', { holdingParent: this.object, realParent: realParentObject });
						}
					}
				}
			}
		}
	});

	const handGrabMixin = (baseClass) => class extends baseClass {

		#worldPosition;
		static shortHandSchema = shortHandSchema({
			'joint-radius': {as: 'pincherRadius',default: 0, stage: schema.STORED_ON_EL }
		});

		static name = 'Gripper';

		async connectedCallback() {
			await super.connectedCallback();
			this.#worldPosition = new Vector3();
			grippers.set(this, this.#worldPosition);
			updateComboCache();
		}
	
		async disconnectedCallback () {
			await super.disconnectedCallback();
			grippers.delete(this);
			updateComboCache();
		}

		tick(time, delta, frame, renderer, session) {
			super.tick(time, delta, frame, renderer, session);
			if (this.#worldPosition && this.ready) {
				this.object.getWorldPosition(this.#worldPosition);
			}
		}
	};

	registerShortHandElement('sh-hand-grab', {
		type: Object3D,
		name: 'Gripper',
		mixin: handGrabMixin
	});

	const linesMap = new Map();
	function hideLine(what, color) {
		if (!linesMap.has(color)) linesMap.set(color, new Map());
		if (linesMap.get(color).has(what)) linesMap.get(color).get(what).visible = false;
	}
	function updateLine(what, color, ...points) {
		let infoLine;
		if (!linesMap.has(color)) linesMap.set(color, new Map());
		if (linesMap.get(color).has(what)) infoLine = linesMap.get(color).get(what);
		else {
			const lineGeometry = new BufferGeometry();
			infoLine = new Line(lineGeometry , new LineBasicMaterial( { color } ));
			infoLine.frustumCulled = false;
			linesMap.get(color).set(what, infoLine);
			document.querySelector('sh-scene').object.add(infoLine);
		}
		infoLine.visible = true;
		infoLine.geometry.setFromPoints( points );
	}

	schemas.get(Object3D).get('mixins').push(baseclass => class extends baseclass {
		static shortHandSchema = shortHandSchema({
			'grab-hand-location': { as: 'grabOffset', type: 'Vector3', stage: schema.STORED_ON_EL },
			'grab-hand-direction': { as: 'grabDirection', default: '0 1 0',  type: 'Vector3', stage: schema.STORED_ON_EL },
			'grab-hand-radius': { as: 'grabRadius', default: 0.01, stage: schema.STORED_ON_EL },
			'grab-hand-length': { as: 'grabLength', default: 0.03, stage: schema.STORED_ON_EL },
			'grab-hand-handle-visibility': {as: 'grabHandleVisible', type: 'boolean', stage: schema.STORED_ON_EL, map: {hidden: false, visible: true}},
		});

		static name = 'Grabbable';

		#grabHandleMesh;
		#grabHandleVisibleOldState;
		tick(time, delta, frame, renderer, session) {
			super.tick(time, delta, frame, renderer, session);
			const grabbable = this.properties.grabTarget >= 0;
			if ((this.properties.grabHandleVisible && grabbable) !== this.#grabHandleVisibleOldState) {
				this.#grabHandleVisibleOldState = this.properties.grabHandleVisible && grabbable;

				if (this.properties.grabHandleVisible && grabbable) {
					const mesh = new Mesh(cylinderGeom, previewMaterial);
					this.#grabHandleMesh = mesh;
					mesh.position.copy(this.properties.grabOffset || zeroVector);
					mesh.scale.set(this.properties.grabRadius, this.properties.grabLength, this.properties.grabRadius);
					mesh.quaternion.setFromUnitVectors(yVector3, this.properties.grabDirection);
					this.object.add(mesh);

				} else if (this.#grabHandleMesh) {
					this.object.remove(this.#grabHandleMesh);
					this.#grabHandleMesh.dispose();
					this.#grabHandleMesh = null;
				}
			}
		}
	});


}

