import { AudioListener } from 'three';
import { defaultDocumentationMessage } from '../strings.js';

let documentation = defaultDocumentationMessage;
documentation: {
	documentation = `Position of user's ears, try using it with <sh-user> and attaching it to the user's head:
	
	\`\`\`html

	<sh-user>
		<sh-audio-listener slot="head"></sh-audio-listener>
	</sh-user>
	\`\`\`
	
	`;
}

// The audio listener is global, one listener per page.
let listener;
export function getListener() {
	if (listener) return listener;
	return (listener = new AudioListener());
}

export const name = 'AudioListener';
export const type = AudioListener;
/** @param {typeof HTMLElement} baseClass */
export const mixin = (baseClass) => class extends baseClass {
	static name = name;
	static documentation=documentation; 

	async allAttributesChangedCallback() {
		const object = getListener();
		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
};
