import { Group, Quaternion, Vector3, Raycaster, Object3D, Matrix4 } from 'three';
import { STORED_ON_EL, schemas } from '../schema';
import { IterableWeakMap, shortHandSchema } from '../utils/utils';
import { refreshTransform } from '../features/transform.js';
import { markAsDirty } from '../features/style-attributes';

const tempQuaternion = new Quaternion();
const tempVectorA = new Vector3();
const tempVectorB = new Vector3();
const raycaster = new Raycaster( new Vector3(), new Vector3(0,-1,0), 0, 30 );
const tempMatrix = new Matrix4();
raycaster.firstHitOnly = true;

export const grabbables = new IterableWeakMap();

schemas.get(Object3D).get('mixins').push(baseClass => class extends baseClass {

	static name='MarkAsGrabbable';
	static shortHandSchema = shortHandSchema({
		'grab-target': {as: 'grabTarget', default: -1, type: 'number', map: {
			self: 0,
			parent: 1,
			grandparent: 2,
			greatgrandparent: 3
		}, stage: STORED_ON_EL},
		'grab-range': { as: 'grabRange', type: 'number' }
	});
	static shortHandEventDescriptions = {
		'yank': 'Fired when an object is rapidly pulled towards the hand.',
		'grabstart': 'Fired when this object has "grab-target" set and is picked up by the user.',
		'grabend': 'Fired when this object has "grab-target" set and is let go by the user.',
	};

	async attributeChangedCallback(attr, oldValue, newValue, fromStyleChange) {
		await super.attributeChangedCallback(attr, oldValue, newValue, fromStyleChange);
		if (typeof this.properties.grabTarget === 'number' && this.properties.grabTarget > -1) grabbables.set(this, this.properties.grabTarget);
	}

	async connectedCallback() {
		await super.connectedCallback();
		if (typeof this.properties.grabTarget === 'number' && this.properties.grabTarget > -1) grabbables.set(this, this.properties.grabTarget);
	}

	async disconnectedCallback () {
		await super.disconnectedCallback();
		grabbables.delete(this);
	}

	#hasPreviousPosition=false;
	#previousPosition = new Vector3();
	tick(time, delta, frame, renderer, session) {
		if (holdingObjectForPushPull.has(this)) {
			const holdingObject = holdingObjectForPushPull.get(this).object;
			if (this.#hasPreviousPosition) {
				refreshTransform(this);
				const l = this.object.position.length();
				const offsetScale = Math.max(0, 1 * (1.1 + Math.min(l, 5)) ** 2 - 1);
				tempQuaternion.copy(this.object.parent.quaternion).invert();

				holdingObject.getWorldPosition(tempVectorA);
				const normalComponent = tempVectorB
					.subVectors(tempVectorA, this.#previousPosition)
					.applyQuaternion(tempQuaternion)
					.dot(this.object.position);
				const length = tempVectorB.length();
				this.#previousPosition.copy(tempVectorA);

				this.object.position.multiplyScalar( (1 + (offsetScale * normalComponent)/(1+l))**0.5 );
				if (this.postConstruct.has('position')) this.postConstruct.get('position').copy(this.object.position);

				if (normalComponent < -1.2 * delta && normalComponent/length < -0.6) {
					this.emit('yank', {
						el: this,
						holdingObject
					}, true);
				}
			} else {
				this.#hasPreviousPosition = true;
				holdingObject.getWorldPosition(this.#previousPosition);
			}
		} else if (this.#hasPreviousPosition) {
			this.#hasPreviousPosition = false;
		}
		super.tick(time, delta, frame, renderer, session);
	}
});

export const name = 'SelectGrab';
export const type = Group; // Replace with what ever THREE object this is 
/** @param {typeof HTMLElement} baseClass */

/**
 * @type {Map<HTMLElement, Object3D>} Element being held, Old parent
 */
export const held = new IterableWeakMap();

/**
 * @type {Map<HTMLElement, HTMLElement>} Element being held, Holding Element
 */
export const holdingObjectForPushPull = new IterableWeakMap();
export const mixin = baseClass => class extends baseClass {
	static name = name;
	constructor() {
		super();
		this.addEventListener('selectstart', this);
		this.addEventListener('selectend', this);
	}
	async handleEvent(e) {
		if (e.type === 'selectstart') {
			const pose = e.detail.targetRayPose;
			raycaster.ray.direction.set(0,0,-1).applyQuaternion(tempQuaternion.copy(pose.transform.orientation));
			raycaster.ray.origin.copy(pose.transform.position);
			const objects = Array.from(grabbables.keys()).map(el => el.object).filter(o => o && !(o instanceof Promise));
			const result = raycaster.intersectObjects(objects, true);
			if (result.length) {
				let { object } = result[0];

				// ray could hit a child so traverse ancestors until actual target found
				while (!object.el || !grabbables.has(object.el)) object = object.parent;
				let el = object.el;

				// Target could redirect onto one of it's ancestors
				for (let i=0; i<grabbables.get(el); i++) el=el.parentNode;
				object = el.object;

				this.object.updateWorldMatrix( true, false );
				tempMatrix.copy( this.object.matrixWorld ).invert();
				object.parent.updateWorldMatrix( true, false );
				tempMatrix.multiply( object.parent.matrixWorld );
				const distance = tempVectorA.setFromMatrixPosition(tempMatrix).length();

				const range = object.el.properties.grabRange;
				if (range && range > 0 && distance > range) return;

				// Store object and it's parent to restore later
				const realParentObject = held.get(el) || object.parent;
				held.set(el, realParentObject);
				holdingObjectForPushPull.set(el, this);
				el.shReparent(this.object);
				el.classList.add('held');
				if (el.getRootNode().host) {
					el.part.add('held');
					el.getRootNode().host.emit('grabstart', { part: el, holdingParent: this.object, realParent: realParentObject, distance });
				}
				this.emit('grabstart', {target: el, holdingParent: this.object, realParent: realParentObject}, false);
				el.emit('grabstart', { holdingParent: this.object, realParent: realParentObject, distance });

				markAsDirty(el);
				el.tick.call(el); // trigger any style recalc immediately
			}
		}
		if (e.type === 'selectend') {
			for (const [el, holder] of holdingObjectForPushPull.entries()) {
				if (holder !== this) continue;
				const realParentObject = held.get(el);
				el.shReparent(realParentObject);
				el.classList.remove('held');
				el.part.remove('held');
				held.delete(el);
				holdingObjectForPushPull.delete(el);
				if (el.getRootNode().host) {
					el.getRootNode().host.emit('grabend', { part: el, holdingParent: this.object, realParent: realParentObject });
				}
				this.emit('grabend', {target: el, holdingParent: this.object, realParent: realParentObject}, false);
				el.emit('grabend', { holdingParent: this.object, realParent: realParentObject });

				markAsDirty(el);
				el.tick.call(el); // trigger any style recalc immediately
			}
		}
	}
	stopHolding(needle) {
		const oldHeld = [];
		for (const [el, holder] of holdingObjectForPushPull.entries()) {
			if (holder !== this) continue;
			if (needle && needle !== el) continue;
			const realParent = held.get(el);
			el.shReparent(realParent);
			held.delete(el);
			holdingObjectForPushPull.delete(el);
			el.classList.remove('held');
			el.part.remove('held');
			oldHeld.push({
				el, realParent, holdingParent: this.object
			});
		}
		return oldHeld;
	}
};
