import { WebGLRenderer } from "three";
import { defaultDocumentationMessage } from '../strings.js';
import { querySelectorAllLive, shortHandSchema, warnOnce } from '../utils/utils.js';
import { detectSupport } from "../utils/model-loaders.js";
const html = String.raw;
const style = html`<style>

	sh-renderer-webgl button:hover {
		box-shadow: 0 0 0.6em #00000044;
	}

	sh-renderer-webgl button:active {
		border-color: #dddddd;
		color: #dddddd;
		box-shadow: 0 0 0.3em #00000044;
	}

	:root:has(.clickable.hover) sh-renderer-webgl,
	:root:has(a .hover) sh-renderer-webgl {
		cursor: pointer;
	}

	sh-xr-session.vr-supported:not(:is(.in-ar, .in-vr, .in-inline-xr))~* button.enter-vr,
	sh-xr-session.ar-supported:not(:is(.in-ar, .in-vr, .in-inline-xr))~* button.enter-ar,
	sh-xr-session.inline-xr-supported:not(:is(.in-ar, .in-vr, .in-inline-xr))~* button.enter-inline-xr {
		display:inline;
	}

	sh-xr-session:is(.in-ar, .in-vr, .in-inline-xr)~* button.end-session {
		display:inline;
	}

</style>`;

let css = window.document.styleSheets[0];
if (!css) {
	document.head.appendChild(document.createElement('style'));
	css = window.document.styleSheets[0];
}
for (const rule of style.split('\n\n').slice(1,-1)) {
	css.insertRule(rule, css.cssRules.length);
}


const template = document.createElement('template');
template.innerHTML = html`
	<style>
	:host {
		position: relative;
		display: inline-block;
		width: 512px;
		height: 512px;
		touch-action: none;
	}
	canvas {
		touch-action: none;
	}
	canvas, [part~=content] {
		position: absolute;
		inset: 0;
		top: auto;
	}
	[part~=content] > slot {
		pointer-events: auto;
		position: absolute;
		top: 0;
		left: 0;
	}
	[part~=content] {
		padding: 1em;
		pointer-events: none;
		display: flex;
		flex-direction: row;
		align-items: flex-end;
		justify-content: center;
	}

	::slotted(button) {
		font-size: 1.5em;
		border: 0.1em solid white;
		border-radius: 0.5em;
		background-color: #00000044;
		color: white;
		box-shadow: 0 0 0em #00000044;
		transition: box-shadow 300ms ease;
		margin: 0 0.5em;
		cursor: pointer;
		display: none;
	}
	</style>
	<slot name="scene"></slot>
	<div part="content">
		<slot></slot>
	</div>
`;

let documentation = defaultDocumentationMessage;
documentation:
{
	documentation = `
The WebGL renderer component is used to render scenes using WebGL from a camera's point of view both properties are required.
The default size of the output is 512x512 but the render output size will be adjusted to fit the size of the lement should you
grow it or shrink it with CSS.

The renderer also controls the framerate of the scene. Each animation frame the renderer calls the \`tick\` method on each element that is a child of scene.`;
}

let fps = 0;
function timeout(){
	fps--;
}

function * iterateOverSlotsInQuerySelector(els) {
	for (const el of els) {
		if (el.tagName === 'SLOT') {
			for (const slotted of el.assignedElements()) {
				yield slotted;
				yield * iterateOverSlotsInQuerySelector(slotted.children);
			}
		}
		else yield el;
	}
}

export const mixins = [];
export const type = WebGLRenderer;
export const name = 'WebGLRenderer';
/** @param {typeof HTMLElement} baseClass */
export const mixin = (baseClass) => class extends baseClass {
	static shortHandSchema = shortHandSchema({ mixins,
		"log-depth-buffer": {as: 'logarithmicDepthBuffer ', default: true},
		"power-preference": {as: 'powerPreference', type: 'string'}
	});
	static shortHandEventDescriptions = {
		'postrender': 'An event containing statistics about the previously rendered frame, use this to display stats like framerate or number of drawcalls to help debug performance issues.',
	};
	isShRenderer = true;
	static name = name;
	width;
	height;
	left;
	top;
	static documentation = documentation;
	static template = template;
	constructor () {
		super();
		const resize_ob = new ResizeObserver(() => {
			this.#onResize();
		});
		resize_ob.observe(this);
		this.prevTime = 0;
	}
	async connectedCallback() {

		let css = this.getRootNode().styleSheets[0];
		if (!css) {
			this.getRootNode().appendChild(document.createElement('style'));
			css = this.getRootNode().styleSheets[0];
		}
		for (const rule of style.split('\n\n').slice(1,-1)) {
			css.insertRule(rule, css.cssRules.length);
		}

		let cameraEl;
		if (!this.properties.session) {
			this.properties.session = await this.getRootNode().querySelector('sh-xr-session')?.object;
		}
		if (!this.properties.scene) {
			this.properties.scene = this.querySelector('sh-scene');
		}
		if (this.properties.scene && !this.properties.camera) {
			cameraEl = this.querySelector('sh-camera-perspective');
			if (cameraEl) {
				await cameraEl.object;
				if (!this.properties.camera) this.properties.camera = await cameraEl.object;
			}
		}
		if (this.properties.scene && !this.properties.camera) {
			let shUser = this.properties.scene.querySelector('sh-user');
			if (shUser) {
				cameraEl = shUser.shadowRoot.querySelector('[part~=camera]');
				if (cameraEl) {
					await cameraEl.object;
					if (!this.properties.camera) this.properties.camera = await cameraEl.object;
				}
			}
		}

		await super.connectedCallback();
		if (this.properties.camera) {
			this.#onResize({
				width: this.offsetWidth,
				height: this.offsetHeight
			});
		}
	}
	tick(time, delta, frame, renderer, session) {
		if (!this.properties.camera) warnOnce('Renderer: Could not find camera');
		if (!this.properties.scene) warnOnce('Renderer: Could not find scene');
		try {
			if (this.properties.scene.object && !(this.properties.scene.object instanceof Promise) && this.properties.camera) {
				const rootHost = this.getRootNode().host;
				if (rootHost && rootHost.isShortHandElement) {
					rootHost.tick.call(rootHost, time, delta, frame, renderer, session);
				}
				this.properties.scene.tick(time, delta, frame, renderer, session);
				for (const el of this.sceneChildren) {
					if (el.isShortHandElement && typeof el.tick !== 'undefined') {
						el.tick(time, delta, frame, renderer, session);
					}
				}
				const startTime = performance.now();
				this.object.render( this.properties.scene.object, this.properties.camera );
				this.object.info.render.duration = performance.now() - startTime;
				this.object.info.render.fps = fps;
				this.object.info.render.xrFrame = frame;

				this.emit('postrender', this.object.info.render, true);
				fps++;
				setTimeout(timeout, 1000);
			}
			super.tick(time, delta, frame, renderer, session);
		} catch (e) {
			console.error(e);
			// do nothing
		}
	}
	async attributeChangedCallback(attr, oldValue, newValue, fromStyleChange) {
		await super.attributeChangedCallback(attr, oldValue, newValue, fromStyleChange);
		if ( this.ready === true ) {
			this.object.shadowMap.enabled = this.properties.shadowMapEnabled;
			this.object.shadowMap.type = this.properties.shadowMapType;
		}
	}
	#sceneChildren=[];
	get sceneChildren() {
		return iterateOverSlotsInQuerySelector(this.#sceneChildren);
	}
	async allAttributesChangedCallback() {

		this.#sceneChildren = querySelectorAllLive(this.properties.scene, '*')
			.sort((a,b) => (a.isShortHandElement ? a.constructor.tickPriority : 0) - (b.isShortHandElement ? b.constructor.tickPriority : 0));

		await super.allAttributesChangedCallback();
		const renderer = this.object;
		detectSupport(renderer);
		
		renderer.setAnimationLoop((time, frame) => {
			const delta = (time - this.prevTime)/1000;
			this.prevTime = time;
			this.tick(time, delta, frame, this, this.properties.session);
		});
		renderer.setPixelRatio(devicePixelRatio);
		renderer.xr.enabled = true;
		renderer.xr.cameraAutoUpdate = true;
		renderer.info.autoReset = true;

		renderer.domElement.part.add('canvas');
		this.shadowRoot.insertBefore( renderer.domElement,  this.shadowRoot.querySelector('slot'));
		this.#onResize({
			width: this.offsetWidth,
			height: this.offsetHeight
		});
	}
	async #onResize() {
		this.width = this.offsetWidth;
		this.height = this.offsetHeight;
		this.left = this.offsetLeft;
		this.top = this.offsetTop;
		(await this.object).setSize( this.width, this.height );
		if (this.properties.camera) {
			this.properties.camera.aspect = this.width / this.height;
			this.properties.camera.updateProjectionMatrix();
		}
		for (const el of this.sceneChildren) {
			if (el.isShortHandElement && typeof el.renderResize !== 'undefined') {
				el.renderResize(this.width, this.height);
			}
		}
	}
};

