
import { KTX2Loader } from 'three/examples/jsm/loaders/KTX2Loader.js';
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { DRACOLoader } from "three/examples/jsm/loaders/DRACOLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { USDZLoader } from "three/examples/jsm/loaders/USDZLoader.js";

let path;
try {
	path = import.meta.url;
// eslint-disable-next-line no-unused-vars
} catch (e) {
	const scripts= document.getElementsByTagName('script');
	path= scripts[scripts.length-1].src.split('?')[0];
}
const ktx2Loader = new KTX2Loader();
ktx2Loader.setTranscoderPath( new URL("../KTX2/", path).href );

let supportDetectedResolver;
export const ktxSupportDetectionPromise = new Promise(resolve => supportDetectedResolver = resolve);

let hasDetectedSupport = false;
export function detectSupport(renderer) {
	if (!hasDetectedSupport) {
		hasDetectedSupport = true;
		ktx2Loader.detectSupport(renderer);
		supportDetectedResolver();
	}
}

export const usdzLoader = new USDZLoader();
export const gltfLoader = new GLTFLoader();
const dracoLoader = new DRACOLoader();
gltfLoader.setDRACOLoader( dracoLoader );
gltfLoader.setKTX2Loader( ktx2Loader );
gltfLoader.setMeshoptDecoder(MeshoptDecoder);
dracoLoader.setDecoderPath( new URL("../DRACO/", import.meta.url).href );
export function setDracoPath(path) {
	dracoLoader.setDecoderPath( path );
}
