import { Texture } from 'three';
import { RGBELoader } from 'three/examples/jsm/loaders/RGBELoader.js';
import { filenameFromURL, shortHandSchema } from '../utils/utils';
import { STORED_ON_EL } from '../schema';

const rgbeLoader = new RGBELoader();
export const type = Texture;
export const name = 'ImageTexture';
export const native = {class: HTMLImageElement, tagName: 'img'};
export const mixin = (baseClass) => class SHImageTexture extends baseClass {
	static name = name;
	static canProxy = false;
	static shortHandSchema = shortHandSchema({
		src: {stage: STORED_ON_EL, type: 'string', example: 'some/image.hdr'},
	});
	constructor () {
		super();
		this.style.display = 'none';
	}
	async allAttributesChangedCallback() {
		let object;
		const fileName = filenameFromURL(this.src);
		if (fileName.toLowerCase().endsWith('.hdr')) {
			const {texture, textureData: _textureData} = await new Promise(resolve => rgbeLoader.load(this.src, function(texture, textureData) { resolve({texture, textureData}); }));
			object = texture;
		} else {
			if (!this.complete) await new Promise(resolve => this.addEventListener('load', resolve, {once: true}));
			object = new Texture(this);
		}
		object.needsUpdate = true;
		await this.assignPostConstructAttributes(object);
		this.updateObject(object);
	}
};
